void DrawTitle(Object* obj, int maxPixels){
    SetColorID(ColorID::white);

    //icono de la coleccion
    W3dDrawStrip4(IconMesh, IconsUV[ObjectIcon(obj)]->uvs);

    //texto render
    w3dEngine::PushMatrix();
    w3dEngine::Translatef(IconSizeGS + gapGS, 0, 0);
    RenderBitmapText(obj->name, textAlign::left, maxPixels);
    w3dEngine::PopMatrix();
    w3dEngine::Translatef(0, RowHeightGS + gapGS, 0);
}

