// nombre clasico del programa: Material, Material.001, Material.002...
// Delega en LA regla comun (el ctor de Material ya uniquifica igual; esto solo
// evita pedirle un nombre tomado). El bucle viejo tenia tope 999 y al llegar
// devolvia "Material.999" DUPLICADO.
static std::string FreeMaterialName(){
    return MaterialFreeName("Material", NULL);
}

// el desplegable del selector de materiales (se reconstruye al abrir)
static PopupMenu* MenuMaterials = NULL;

// opcion elegida: 0 = New Material, 1 = Default Material, 2+ = existentes
// Crea un material nuevo (nombre clasico: Material, Material.001, ...) y lo pone en el mesh part 'idx'. Vive aca
// porque aca vive FreeMaterialName; lo usa el Add > Reference, que necesita el material hecho para poder abrirle
// el selector de textura de una.
Material* NewMaterialInMeshPart(Mesh* mesh, int idx){
    if (!mesh || idx < 0 || idx >= (int)mesh->materialsGroup.size()) return NULL;
    Material* mat = FactoryMaterial(new Material(FreeMaterialName()));
    mesh->materialsGroup[idx].material = mat;
    return mat;
}

// LA CAPA DE MATERIAL elegida en la lista de la tarjeta Material (0 = la capa 1: MaterialGroup::material; k = layersMat[k-1])
static int gLayerMatSel = 0;
static int LayerMatCount(Mesh* m, int idx) {
    if (!m || idx < 0 || idx >= (int)m->materialsGroup.size()) return 0;
    return 1 + (int)m->materialsGroup[(size_t)idx].layersMat.size();
}
static int LayerPickedMat(Mesh* m, int idx) {
    // (otra malla u otra parte: arranca en la capa 1)
    static Mesh* lastM = NULL; static int lastI = -1;
    if (m != lastM || idx != lastI) { lastM = m; lastI = idx; gLayerMatSel = 0; }
    const int n = LayerMatCount(m, idx);
    if (gLayerMatSel >= n) gLayerMatSel = n - 1;
    if (gLayerMatSel < 0) gLayerMatSel = 0;
    return n ? gLayerMatSel : -1;
}
// el lugar del material de la capa k de la parte idx (NULL = no existe)
static Material** LayerMatPlace(Mesh* m, int idx, int k) {
    if (!m || idx < 0 || idx >= (int)m->materialsGroup.size() || k < 0) return NULL;
    MaterialGroup& g = m->materialsGroup[(size_t)idx];
    if (k == 0) return &g.material;
    return (k - 1 < (int)g.layersMat.size()) ? &g.layersMat[(size_t)(k - 1)] : NULL;
}
static void ActionPickedMaterial(int id){
    if (!PropsActive) return;
    if (!ActiveObj || ActiveObj->getType() != ObjectType::mesh) return;
    Mesh* mesh = static_cast<Mesh*>(ActiveObj);
    if (mesh->materialsGroup.empty()) return;
    PropListMeshParts* list =
        static_cast<PropListMeshParts*>(PropsActive->propMeshParts->properties[0]);
    int idx = list->selectIndex;
    if (idx < 0 || idx >= (int)mesh->materialsGroup.size()) idx = 0;

    // (el material va en la CAPA elegida de la lista de la tarjeta: la 1 es la de siempre; las de encima, layersMat)
    const int layer = LayerPickedMat(mesh, idx);
    if (layer <= 0) UndoCaptureMaterial(mesh, idx); // Ctrl+Z: guarda el Material* previo del mesh part
    else UndoCaptureMeshGeo(mesh);                  // (una capa de encima: la foto de las partes, con sus capas)
    Material** place = LayerMatPlace(mesh, idx, layer > 0 ? layer : 0);
    if (!place) return;

    if (id == 0) {
        // nombre clasico del programa: Material, Material.001, ...
        *place = FactoryMaterial(new Material(FreeMaterialName()));
    } else if (id == 1) {
        // el material por defecto (fuera de la lista global Materials:
        // no aparece entre los "existentes")
        if (!MaterialDefault) MaterialDefault = FactoryMaterial(new Material("Default Material", true));
        *place = MaterialDefault;
    } else if (id >= 2 && id - 2 < (int)Materials.size()) {
        *place = Materials[id - 2];
    }
    RebindMaterialMeshPart();
}

