// TEXTURA del objeto Particulas: dropdown de texturas ya cargadas + "Load Texture" (file browser), IGUAL que
// el material/Image2D. La particula guarda su textura como std::string (ruta) y la resuelve en render con
// Texture2DGet, asi que -como Image2D- el dropdown escribe la RUTA (no un Texture*): save/load/render/lua
// no se tocan. Patron: menu lazy con action registrado una vez; Clear()+repoblar Textures[5..] al abrir.
static PopupMenu* MenuPartTexture = NULL;
static Particles* ActivePart(){
    return (ActiveObj && ActiveObj->getType() == ObjectType::particles) ? (Particles*)ActiveObj : NULL;
}
// callback del file browser: importa (copia al .w3d) y aplica la ruta a la particula
static void PartPickedTexture(const std::string& pickedPath){
    Particles* pt = ActivePart(); if (!pt) return;
    const std::string path = W3dLoadExternal(pickedPath);   // (queda afuera: referencia externa)
    pt->texture = path;
    TextureTake(path);   // la registra en Textures[] para que aparezca en el dropdown la proxima vez
    if (PropsActive && PropsActive->propPartTexture)
        PropsActive->propPartTexture->button->text = FileName(path);
    g_redraw = true;
}
// 0 = No Texture; 1 = Load Texture (browser); 2+ = Textures[5 + id - 2] (las 5 primeras son de la UI)
static void ActionPartPickedTexture(int id){
    Particles* pt = ActivePart(); if (!pt) return;
    if (id == 0) { pt->texture = ""; }
    else if (id == 1) {
        OpenFileBrowser(T("Load Texture"), T("Open"), ".png .jpg .jpeg .bmp .tga .gif", PartPickedTexture);
        return;
    } else if (5 + id - 2 < (int)Textures.size()) {
        pt->texture = Textures[5 + id - 2]->path;   // guarda la RUTA (no el Texture*)
    }
    if (PropsActive && PropsActive->propPartTexture)
        PropsActive->propPartTexture->button->text = FileName(pt->texture);
    g_redraw = true;
}
static void ActionMenuPartTexture(){
    if (!PropsActive || !ActivePart()) return;
    if (!MenuPartTexture) { MenuPartTexture = new PopupMenu(); MenuPartTexture->action = ActionPartPickedTexture; }
    MenuPartTexture->Clear();
    MenuPartTexture->Add(T("No Texture"), 0, IconType::notifError);
    MenuPartTexture->Add(T("Load Texture"), 1, IconType::archive);
    for (size_t i = 5; i < Textures.size(); i++)
        MenuPartTexture->Add(TextureName(Textures[i]), 2 + (int)(i - 5), IconType::texture);
    OpenMenuUnderButton(MenuPartTexture, PropsActive->propPartTexture->button);
}

