// ===========================================================================
//  CAPAS DE TEXTURA (TexLayer, objects/Materials.h): hasta 4, en una LISTA como la de las partes de malla (el tacho
//  de cada fila la borra, se arrastran para reordenar, click derecho = menu). Abajo, lo de la capa ELEGIDA: su
//  textura, la capa UV de la malla con la que se dibuja, la mezcla y si esta prendida. "Add Layer" (abajo de la
//  lista): elegir una textura CREA la capa. Los desplegables comparten menu; gLayerMenu dice sobre que capa se abrio.
// ===========================================================================
static const int kLayersUI = 4;
static PopupMenu* MenuLayerTex = NULL;
static PopupMenu* MenuLayerUV = NULL;
static PopupMenu* MenuLayerMix = NULL;
static int gLayerMenu = 0;
static int gLayerSel = 0;     // la capa elegida en la lista (la que muestran los campos de abajo)
int gLoadTextureLayer = -1;   // "Load Texture" de una capa: main.cpp deja la imagen en esa capa (-1 = base/normal)
// la malla del mesh part que edita la tarjeta (para nombrar sus capas UV); NULL con el material de un recurso
static Mesh* ActiveMeshUI() {
    if (!ActiveObj || ActiveObj->getType() != ObjectType::mesh) return NULL;
    return (Mesh*)ActiveObj;
}
static std::string LayerNameUV(int k) {
    Mesh* m = ActiveMeshUI();
    if (m && k >= 0 && k < (int)m->uvMaps.size()) return m->uvMaps[(size_t)k]->name;
    char b[24]; snprintf(b, sizeof b, "UV %d", k + 1);
    return b;
}
static void ActionLayerPickedTex(int id) {
    Material* mat = ActiveMaterialUI();
    if (!PropsActive || !mat) return;
    const int n = gLayerMenu;
    if (id == 0) {                                     // "No Texture": la capa se va (y suelta su textura)
        if (n < (int)mat->layers.size()) {
            UndoMaterialModStart(mat);
            Texture* t = mat->layers[(size_t)n].tex;
            mat->layers.erase(mat->layers.begin() + n);
            TextureRelease(t);
            UndoMaterialModCommit();
        }
    } else if (id == 1) {                              // cargar archivo: el MISMO browser, con la capa como destino
        if (DialogLoadTexture) { gLoadTextureAsNormal = false; gLoadTextureLayer = n; DialogLoadTexture(mat); return; }
    } else if (5 + id - 2 < (int)Textures.size()) {    // una ya cargada (la ranura de la capa la retiene)
        UndoMaterialModStart(mat);
        if (n >= (int)mat->layers.size()) mat->layers.resize((size_t)n + 1);
        TextureSetIn(mat->layers[(size_t)n].tex, Textures[5 + id - 2]);
        UndoMaterialModCommit();
        gLayerSel = n;                                  // (la nueva queda elegida)
    }
    RebindMaterialMeshPart();
}
// la lista: cuantas hay, el nombre de cada una (su textura), elegir y cual esta elegida
static int LayerTexCount() { Material* mat = ActiveMaterialUI(); return (mat && mat != MaterialDefault) ? (int)mat->layers.size() : 0; }
static int LayerPickedTex() { const int n = LayerTexCount(); if (gLayerSel >= n) gLayerSel = n - 1; if (gLayerSel < 0) gLayerSel = 0; return n ? gLayerSel : -1; }
// EL FACTOR de la capa elegida, en % para la fila (la capa lo guarda de 0 a 1). El deshacer lo toma la edicion de la fila
// (como toda la tarjeta Material)
static float gLayerForcePct = 100.0f;
static void OnLayerForce() {
    Material* mat = ActiveMaterialUI(); const int n = LayerPickedTex();
    if (!mat || n < 0 || n >= (int)mat->layers.size()) return;
    float f = gLayerForcePct * 0.01f; if (f < 0.0f) f = 0.0f; if (f > 1.0f) f = 1.0f;
    mat->layers[(size_t)n].force = f;
    RTInvalidate();
    g_redraw = true;
}
static std::string LayerTexName(int i) {
    Material* mat = ActiveMaterialUI();
    if (!mat || i < 0 || i >= (int)mat->layers.size()) return std::string();
    return TextureName(mat->layers[(size_t)i].tex);
}
static void LayerTexPick(int i) { gLayerSel = i; RebindMaterialMeshPart(); }
static void ActionLayerDelete() {
    Material* mat = ActiveMaterialUI(); const int n = LayerPickedTex();
    if (!mat || n < 0) return;
    UndoMaterialModStart(mat);   // (Ctrl+Z la devuelve: el paso guarda la lista de capas)
    Texture* t = mat->layers[(size_t)n].tex;
    mat->layers.erase(mat->layers.begin() + n);
    TextureRelease(t);
    UndoMaterialModCommit();
    RebindMaterialMeshPart(); g_redraw = true;
}
static void LayerMove(int d) {
    Material* mat = ActiveMaterialUI(); const int n = LayerPickedTex();
    if (!mat || n < 0 || n + d < 0 || n + d >= (int)mat->layers.size()) return;
    UndoMaterialModStart(mat);
    std::swap(mat->layers[(size_t)n], mat->layers[(size_t)(n + d)]);   // (el orden es el de dibujado: la de abajo, encima)
    UndoMaterialModCommit();
    gLayerSel = n + d;
    RebindMaterialMeshPart(); g_redraw = true;
}
static void ActionLayerUpload() { LayerMove(-1); }
static void ActionLayerLower() { LayerMove(1); }
static struct LayerTexHooks { LayerTexHooks() { LayerTexRowsCount = LayerTexCount; LayerTexRowText = LayerTexName;
    LayerTexRowSelect = LayerTexPick; LayerTexActiveRow = LayerPickedTex; } } gLayerTexHooks;
static void ActionMenuLayerTex(int n) {
    if (!PropsActive || !ActiveMaterialUI()) return;
    // (los campos de abajo de la lista -la fila 0- son los de la capa ELEGIDA; n = -1: "Add Layer", una capa nueva)
    Button* button = PropsActive->propLayerTex[0]->button;
    if (n < 0) { n = LayerTexCount(); if (PropsActive->propLayerAdd) button = PropsActive->propLayerAdd->button; }
    else n = LayerPickedTex();
    if (n < 0 || n >= kLayersUI) return;
    gLayerMenu = n;
    if (!MenuLayerTex) { MenuLayerTex = new PopupMenu(); MenuLayerTex->action = ActionLayerPickedTex; }
    MenuLayerTex->Clear();
    MenuLayerTex->Add(T("No Texture"), 0, IconType::notifError);
    MenuLayerTex->Add(T("Load Texture"), 1, IconType::archive);
    for (size_t i = 5; i < Textures.size(); i++) MenuLayerTex->Add(TextureName(Textures[i]), 2 + (int)(i - 5), IconType::texture);
    OpenMenuUnderButton(MenuLayerTex, button);
}
