// === REFLECTION: el MODO del reflejo (Matcap HW / Sphere Map / Equirect) en un desplegable (reemplaza el viejo
// checkbox "Chrome 360"). Los tags (hardware)/(software) son para el N95 (donde importa el perf): el Matcap es por
// matriz de textura = HW en los 4 OS; el Sphere Map exacto es HW en PC (texgen) pero SW en el N95; el Equirect es SW.
// SOMBREADO del material: por vertice (la luz se calcula en cada vertice y se interpola) o por pixel (en cada pixel).
// Solo existe con shaders (gfx::ShadingPerPixelSupported): con el pipeline fijo (GLES 1.1) ni se muestra
static PopupMenu* MenuShading = NULL;
static const char* ShadingName(bool perPixel){ return perPixel ? "Per pixel" : "Per vertex"; }
static void ActionPickedShading(int id){
    Material* mat = ActiveMaterialUI();
    if (!mat || mat == MaterialDefault) return;
    UndoMaterialModStart(mat);
    mat->perPixel = (id == 1);
    UndoMaterialModCommit();
    RebindMaterialMeshPart();
}
static void ActionMenuShading(){
    if (!PropsActive) return;
    if (!MenuShading) { MenuShading = new PopupMenu(); MenuShading->action = ActionPickedShading; }
    Material* mat = ActiveMaterialUI();
    MenuShading->Clear();
    MenuShading->title = T("Shading");
    MenuItem* it = MenuShading->Add(T(ShadingName(false)), 0, IconType::material);
    if (it && mat) it->green = !mat->perPixel;
    it = MenuShading->Add(T(ShadingName(true)), 1, IconType::material);
    if (it && mat) it->green = mat->perPixel;
    OpenMenuUnderButton(MenuShading, PropsActive->propBtnShading->button);
}
// ===========================================================================
//  SHADER ESCRITO (objects/WrittenShader.h): el tilde "Custom shader", el archivo (los .glsl de shaders/ adentro del
//  proyecto, uno nuevo o uno del disco), "Compile" (con el lapiz que lo abre en el IDE) y el resultado de compilar
// ===========================================================================
static PopupMenu* MenuShader = NULL;
static std::vector<std::string> gShaderPaths;   // las entradas del menu (por id)
static const int kNewShader = 100000, kShaderDisk = 100001;
std::string W3dShaderName(const std::string& path) {   // "shaders/vidrio.glsl" -> "vidrio.glsl"
    const size_t b = path.find_last_of("/\\");
    return b == std::string::npos ? path : path.substr(b + 1);
}
// el material pasa a usar el archivo 'ruta' y se compila (el resultado lo muestra la tarjeta)
static void ShaderAssign(Material* mat, const std::string& path) {
    if (!mat) return;
    mat->shaderFile = path;
    mat->shaderOn = true;
    W3dShaderMaterialCompile(mat);
    W3dTouchedChanges();
    RebindMaterialMeshPart();
    g_redraw = true;
}
// Sin proyecto guardado (no hay .w3d montado) el shader se escribe en una carpeta de TRABAJO del editor y se usa en el
// acto; al guardar el proyecto entra adentro del .w3d (SaveW3D: Asset) y el material pasa a usar esa entrada.
static std::string FolderShadersJob() {
    std::string d = w3dFileSystem::GetUserDataDir();   // (la del usuario: config.start, atajos)
    if (d.empty()) d = w3dFileSystem::GetHomeDir();
    d = w3dFileSystem::JoinPath(d, "shaders_no_project");
#ifdef _WIN32
    _mkdir(d.c_str());
#else
    mkdir(d.c_str(), 0755);
#endif
    return d;
}
// un shader NUEVO (shader.glsl, shader1.glsl...) con la plantilla: adentro del proyecto o en la carpeta de trabajo; y al IDE
bool W3dNewShaderForMaterial(Material* mat) {
    if (!mat) return false;
    const bool inside = W3dContainerHasMounted();
    const std::string dir = inside ? std::string() : FolderShadersJob();
    std::string path;
    for (int i = 0; i < 1000; i++) {
        char n[64]; if (i == 0) snprintf(n, sizeof(n), "shader.glsl"); else snprintf(n, sizeof(n), "shader%d.glsl", i);
        const std::string r = inside ? std::string("shaders/") + n : w3dFileSystem::JoinPath(dir, n);
        if (inside ? !W3dContainerExists(r) : !w3dFileSystem::FileExists(r)) { path = r; break; }
    }
    const char* t = W3dShaderTemplate();
    bool ok = !path.empty();
    if (ok && inside) ok = W3dContainerWriteEntry(path, t, strlen(t));
    else if (ok) { FILE* f = fopen(path.c_str(), "wb"); ok = f && fwrite(t, 1, strlen(t), f) == strlen(t); if (f) fclose(f); }
    if (!ok) { Notify(T("Could not write the file"), true); mat->shaderOn = false; return false; }
    ShaderAssign(mat, path);
    extern bool IDEOpenScript(const std::string& path);
    IDEOpenScript(path);
    return true;
}
static void ActionShaderPickedDisk(const std::string& path) {
    Material* mat = ActiveMaterialUI();
    if (!mat || path.empty()) return;
    // (como los scripts: lo elegido del disco se copia adentro del proyecto; sin proyecto queda la ruta del disco)
    ShaderAssign(mat, W3dLoadExternal(path, "shaders"));
}
static void ActionPickedShader(int id) {
    Material* mat = ActiveMaterialUI();
    if (!mat) return;
    if (id == kNewShader) { W3dNewShaderForMaterial(mat); return; }
    if (id == kShaderDisk) { OpenFileBrowser(T("Load shader"), T("Open"), ".glsl", ActionShaderPickedDisk); return; }
    if (id >= 0 && id < (int)gShaderPaths.size()) ShaderAssign(mat, gShaderPaths[(size_t)id]);
}
static void ActionMenuShader() {
    if (!PropsActive) return;
    if (!MenuShader) { MenuShader = new PopupMenu(); MenuShader->action = ActionPickedShader; }
    Material* mat = ActiveMaterialUI();
    MenuShader->Clear();
    MenuShader->title = T("Shader");
    gShaderPaths.clear();
    std::vector<std::string> ents;
    W3dContainerListFolder("shaders/", ents);
    for (size_t i = 0; i < ents.size(); i++) {
        const std::string& e = ents[i];
        if (e.size() < 5 || e.compare(e.size() - 5, 5, ".glsl") != 0) continue;
        gShaderPaths.push_back(e);
        MenuItem* it = MenuShader->Add(W3dShaderName(e), (int)gShaderPaths.size() - 1, IconType::script);
        if (it && mat) it->green = (mat->shaderFile == e);
    }
    if (mat && !mat->shaderFile.empty() && !W3dIsEntryName(mat->shaderFile)) {   // (uno del disco)
        gShaderPaths.push_back(mat->shaderFile);
        MenuItem* it = MenuShader->Add(W3dShaderName(mat->shaderFile), (int)gShaderPaths.size() - 1, IconType::script);
        if (it) it->green = true;
    }
    MenuShader->Add(T("New shader"), kNewShader, IconType::plus);
    MenuShader->Add(T("Load from disk..."), kShaderDisk, IconType::folder);
    OpenMenuUnderButton(MenuShader, PropsActive->propBtnShader->button);
}
static void ActionShaderCompile() {
    Material* mat = ActiveMaterialUI();
    if (!mat || mat->shaderFile.empty()) return;
    // (lo que tiene el IDE sin guardar no lo ve el compilador: el archivo es la verdad. Se avisa)
    if (W3dShaderMaterialCompile(mat)) Notify(W3dShaderName(mat->shaderFile) + " " + T("compiled"), false);
    else Notify(std::string(T("The shader does not compile")) + ": " + W3dShaderName(mat->shaderFile), true);
    RebindMaterialMeshPart();
    g_redraw = true;
}
static void ActionShaderEdit() {
    Material* mat = ActiveMaterialUI();
    if (!mat || mat->shaderFile.empty()) return;
    extern bool IDEOpenScript(const std::string& path);
    if (!IDEOpenScript(mat->shaderFile)) Notify(T("There is no script editor (IDE) in the layout"), true);
}
static void OnMatShaderOn() {
    Material* mat = ActiveMaterialUI();
    if (mat && mat->shaderOn && mat->shaderFile.empty()) W3dNewShaderForMaterial(mat);   // (sin archivo: uno nuevo)
    W3dTouchedChanges();
    RebindMaterialMeshPart();
    PropertiesLayoutDirty = true;
    g_redraw = true;
}

