// --- MEZCLA: los modos de gfx::Mezcla, con el nombre del .mtl entre parentesis
static PopupMenu* MenuMix = NULL;
static const char* MixName(int m) {
    switch (m) {
        case w3dEngine::MixOff:      return T("Opaque (ONE, ZERO)");
        case w3dEngine::MixAdd:      return T("Additive (ADITIVO)");
        case w3dEngine::MixAddAlpha: return T("Additive by alpha");
        case w3dEngine::MixMultiply: return T("Multiply (darkens)");
        case w3dEngine::MixScreen:   return T("Screen (lightens)");
        case w3dEngine::MixPremult:  return T("Premultiplied alpha");
        case w3dEngine::MixSubtract: return T("Subtract (darkens)");
        default:                        return T("Alpha (normal)");
    }
}
static void ActionPickedMix(int id) {
    Mesh* me = MaterialMesh();
    Material* mat = ActiveMaterialUI();
    if (!mat || mat == MaterialDefault) return;
    if (id < 0 || id >= (int)w3dEngine::MixCount_) return;
    UndoCaptureMaterial(me, ActiveMeshPartIdx(me));
    mat->mix = id;
    RebindMaterialMeshPart();
}
