    if (!PropsActive || !PropsActive->propBtnMix) return;
    if (!MenuMix) { MenuMix = new PopupMenu(); MenuMix->action = ActionPickedMix; }
    MenuMix->Clear();
    for (int i = 0; i < (int)w3dEngine::MixCount_; i++)
        MenuMix->Add(MixName(i), i, IconType::material);
