// --- TEST DE PROFUNDIDAD: las 4 combinaciones de (test, escritura) en UN desplegable.
// Por separado son dos bools con nombres poco felices; juntos describen lo que se ve:
//   0 test+escribe = opaco normal | 1 test sin escribir = transparentes y calcomanias
//   2 sin test escribiendo = tapa lo de atras | 3 nada = HUD / overlays
static PopupMenu* MenuDepth = NULL;
static const char* DepthName(bool test, bool write) {
    if (test  &&  write) return T("Test + Write (opaque)");
    if (test  && !write) return T("Test, no Write (decal)");
    if (!test &&  write) return T("No Test, Write");
    return T("Off (no test, no write)");
}
static void ActionPickedDepth(int id) {
    Mesh* me = MaterialMesh();
    Material* mat = ActiveMaterialUI();
    if (!mat || mat == MaterialDefault) return;
    UndoCaptureMaterial(me, ActiveMeshPartIdx(me));
    mat->depth_test  = (id == 0 || id == 1);
    mat->depth_write = (id == 0 || id == 2);
    RebindMaterialMeshPart();
}
static void ActionMenuDepth() {
    if (!PropsActive || !PropsActive->propBtnDepth) return;
    if (!MenuDepth) { MenuDepth = new PopupMenu(); MenuDepth->action = ActionPickedDepth; }
    MenuDepth->Clear();
    MenuDepth->Add(DepthName(true,  true),  0, IconType::material);
    MenuDepth->Add(DepthName(true,  false), 1, IconType::material);
    MenuDepth->Add(DepthName(false, true),  2, IconType::material);
    MenuDepth->Add(DepthName(false, false), 3, IconType::material);
    OpenMenuUnderButton(MenuDepth, PropsActive->propBtnDepth->button);
}

// GL Light de la luz activa: el PropFloat edita un espejo float y al cambiar reasigna el LightID (0..7).
static float g_lightGLIdx = 0.0f;
static void OnLightGLChange(){
    if (!ActiveObj || ActiveObj->getType() != ObjectType::light) return;
    int idx = (int)(g_lightGLIdx + 0.5f); if (idx < 0) idx = 0; if (idx > 7) idx = 7;
    static_cast<Light*>(ActiveObj)->SetLightID(GL_LIGHT0 + (GLenum)idx);
}

// click en el selector: abre el desplegable (new / default / existentes)
// ====================================================================
//  TARJETA "AJUSTES" (pestania Render, abajo de todo): lo que vive en el config.start, editable desde adentro.
//  Antes habia que salir del programa y abrir el .ini con un editor de texto.
//  Casi todo esto SOLO se aplica al arrancar (el contexto GL, la fuente, el skin), asi que al cambiarlo se avisa
//  que hay que reiniciar en vez de fingir que ya paso.
// ====================================================================
extern bool W3dConfigSave();
#include "ViewPorts/PopUp/ShortcutsPopup.h"   // la ventana de atajos (tarjeta Ajustes)
static PopupMenu* MenuLanguage = NULL;

static void ActionPickedLanguage(int id){
    W3dLanguageSet((W3dLanguage)id);
    extern bool g_languageForced;
    g_languageForced = true;   // lo eligio el usuario: el idioma del SO ya no manda
    // SE GUARDA YA (como la escala y el backend): el aviso dice "reinicia" y antes, si no se apretaba "Guardar
    // cambios", al reiniciar volvia el del sistema (el config seguia en "auto")
    if (!W3dConfigSave()) { Notify(T("Could not write config.ini"), true); g_redraw = true; return; }
    Notify(T("Restart Whisk3D for this change to take effect"), false);
    g_redraw = true;
}
static void ActionMenuLanguage(){
    if (!PropsActive || !PropsActive->propSettingsLanguage) return;
    if (!MenuLanguage){ MenuLanguage = new PopupMenu(); MenuLanguage->action = ActionPickedLanguage; }
    MenuLanguage->Clear();
    // los idiomas se listan en SU PROPIO nombre y no traducidos: el que abre esto capaz no entiende el idioma actual
    // (las letras que font.png no tiene -la c cedilla, el cirilico- salen del atlas extendido de la fuente)
    for (int i = 0; i < (int)W3dLangCount; i++) MenuLanguage->Add(W3dLanguageName((W3dLanguage)i), i);
    OpenMenuUnderButton(MenuLanguage, PropsActive->propSettingsLanguage->button);
}

static PopupMenu* MenuBackend = NULL;
// EL BACKEND GRAFICO (Ajustes > Graphics): con varios en el ejecutable (la PC, graphics/w3dBackend.h) se elige al ARRANCAR;
// el boton dice el elegido y, si todavia corre otro (falta reiniciar, o el elegido no anda aca), cual esta corriendo
static std::string TextBackend(){
#if defined(__EMSCRIPTEN__)
    return "WebGL";   // en el navegador hay UNO solo (graphics/gles2 sobre WebGL): no hay nada que elegir
#elif defined(W3D_MULTIBACKEND)
    const int request = w3dEngine::BackendFromName(cfg.graphicsAPI.c_str());
    const int active  = w3dEngine::ActiveBackend();
    std::string t = w3dEngine::BackendName(request >= 0 ? request : active);
    if (request >= 0 && request != active) t += std::string(" (") + T("running") + ": " + w3dEngine::BackendName(active) + ")";
    return t;
#elif defined(__ANDROID__)
    return "OpenGL ES 2.0";   // el APK trae uno solo (graphics/gles2: Android.mk). Antes decia "opengl"/"opengles"
#else
    return cfg.graphicsAPI;
#endif
}
static void ActionPickedBackend(int id){
#if defined(__EMSCRIPTEN__) || defined(__ANDROID__)
    (void)id;   // WebGL / OpenGL ES 2.0 es el unico
#elif defined(W3D_MULTIBACKEND)
    if (!w3dEngine::BackendAvailable(id)) return;
    cfg.graphicsAPI = w3dEngine::BackendName(id);
    W3dConfigSave();
    if (id != w3dEngine::ActiveBackend()) Notify(T("Restart Whisk3D for this change to take effect"), false);
#else
    cfg.graphicsAPI = (id == 1) ? "opengles" : "opengl";
    Notify(T("Restart Whisk3D for this change to take effect"), false);
#endif
    if (PropsActive && PropsActive->propSettingsBackend) PropsActive->propSettingsBackend->button->text = TextBackend();
    g_redraw = true;
}
static void ActionMenuBackend(){
    if (!PropsActive || !PropsActive->propSettingsBackend) return;
    if (!MenuBackend){ MenuBackend = new PopupMenu(); MenuBackend->action = ActionPickedBackend; }
    MenuBackend->Clear();
#if defined(__EMSCRIPTEN__)
    { MenuItem* it = MenuBackend->Add("WebGL", 0); if (it) it->green = true; }
#elif defined(__ANDROID__)
    // (el APK trae uno solo: ES 2.0. Antes ofrecia "OpenGL" y "OpenGL ES", y elegir no cambiaba nada)
    { MenuItem* it = MenuBackend->Add("OpenGL ES 2.0", 0); if (it) it->green = true; }
#elif defined(W3D_MULTIBACKEND)
    const int request = w3dEngine::BackendFromName(cfg.graphicsAPI.c_str());
    for (int b = 0; b < w3dEngine::Backends_; b++) {
        if (!w3dEngine::BackendAvailable(b)) continue;
        MenuItem* it = MenuBackend->Add(w3dEngine::BackendName(b), b);
        if (it) it->green = (b == (request >= 0 ? request : w3dEngine::ActiveBackend()));
    }
#else
    MenuBackend->Add("OpenGL", 0);
    MenuBackend->Add("OpenGL ES", 1);
#endif
    OpenMenuUnderButton(MenuBackend, PropsActive->propSettingsBackend->button);
}

// Los skins que hay: carpetas dentro de res/Skins. Vive ACA y no en w3dFileSystem porque eso es del Core, y el
// Core no tiene por que saber que existe el concepto "skin del editor". Si no se puede listar (o no hay nada),
// queda al menos el que esta puesto: el dropdown nunca sale vacio.
static void W3dListSkins(std::vector<std::string>& out){
    out.clear();
    std::vector<w3dFileSystem::DirEntry> dir;
    if (w3dFileSystem::ListDir(w3dFileSystem::GetResDir() + "/Skins", dir))
        for (size_t i = 0; i < dir.size(); i++) if (dir[i].isDir) out.push_back(dir[i].name);
    if (out.empty()) out.push_back(cfg.SkinName);
}

// LOGS del editor: el nivel en vivo (w3dlog.h). Apagados no cuestan ni el formateo de la linea.
static const char* LogsLabel(int n) {
    switch (n) { case 0: return "Off"; case 1: return "Errors only"; case 2: return "Warnings and errors"; default: return T("All"); }
}
static PopupMenu* MenuLogs = NULL;
static void ActionPickedLogs(int id){
    if (id < 0 || id > 3) return;
    cfg.logs = id; g_w3dLogLevel = id;
    if (PropsActive && PropsActive->propSettingsLogs) PropsActive->propSettingsLogs->button->text = T(LogsLabel(id));
    g_redraw = true;
}
static void ActionMenuLogs(){
    if (!PropsActive || !PropsActive->propSettingsLogs) return;
    if (!MenuLogs){ MenuLogs = new PopupMenu(); MenuLogs->action = ActionPickedLogs; }
    MenuLogs->Clear();
    for (int n = 3; n >= 0; n--) MenuLogs->Add(T(LogsLabel(n)), n);
    OpenMenuUnderButton(MenuLogs, PropsActive->propSettingsLogs->button);
}
static PopupMenu* MenuSkin = NULL;
static void ActionPickedSkin(int id){
    std::vector<std::string> skins; W3dListSkins(skins);
    if (id >= 0 && id < (int)skins.size()) cfg.SkinName = skins[id];
    Notify(T("Restart Whisk3D for this change to take effect"), false);
    g_redraw = true;
}
static void ActionMenuSkin(){
    if (!PropsActive || !PropsActive->propSettingsSkin) return;
    if (!MenuSkin){ MenuSkin = new PopupMenu(); MenuSkin->action = ActionPickedSkin; }
    MenuSkin->Clear();
    std::vector<std::string> skins; W3dListSkins(skins);
    for (size_t i = 0; i < skins.size(); i++) MenuSkin->Add(skins[i], (int)i);
    if (skins.empty()) MenuSkin->Add(cfg.SkinName, 0);
    OpenMenuUnderButton(MenuSkin, PropsActive->propSettingsSkin->button);
}

