static const char* T2dAlignName(int v, bool horizontal){
    if (horizontal) return v==0 ? T("Left") : (v==1 ? T("Center") : T("Right"));
    return v==0 ? T("Top") : (v==1 ? T("Center") : T("Bottom"));
}
