// EXPORTAR el UI activo como .w3dui: elegis la carpeta y se escribe <nombre>.w3dui
static void UIExportPickedFolder(const std::string& folder){
    UI* u = UIActiveProps(); if (!u) return;
    // "Usar carpeta actual" devuelve la CARPETA -> carpeta + nombre de la UI + ".w3dui".
    // (antes se concatenaba con "/" a mano: en la raiz salia "//menu.w3dui")
    std::string path = W3dOutputPath(folder, u->name, ".w3dui");
    if (UI2DSave(u, path)) { Notify(std::string(T("Saved: ")) + path, false); W3dDownloadIfWeb(path); }
    else                      Notify(T("Could not write the file"), true);
}
// Volumen del gameplay (0..100): escribe g_projCompile.volume (viaja en el .w3d) y aplica YA la ganancia al
// mixer del Core (0..100 -> 0..1), asi baja/sube en vivo mientras jugas. Ver W3dAudioGameVolume.
namespace w3dEngine { void W3dAudioGameVolume(float v); }
static float g_gameVolF = 100.0f;
static void ActionGameVolume(){
    int v = (int)(g_gameVolF + 0.5f);
    if (v < 0) v = 0; else if (v > 100) v = 100;
    g_projCompile.volume = v;
    w3dEngine::W3dAudioGameVolume(v / 100.0f);
}
// RESOLUCION del juego compilado (25..100 % de la pantalla; hoy la usa Android 2.3: dibuja a menos pixeles y el
// sistema la estira, el driver de esos telefonos cuesta por pixel). Viaja en el .w3d
static float g_gameResF = 100.0f;
static void ActionGameResolution(){
    int v = (int)(g_gameResF + 0.5f);
    if (v < 25) v = 25; else if (v > 100) v = 100;
    g_projCompile.resolution = v;
}
// refresca los numeros mostrados desde g_projCompile (lo llama import_w3d al abrir un .w3d con el bloque guardado)
void W3dGameVolRefUI(){ g_gameVolF = (float)g_projCompile.volume; g_gameResF = (float)g_projCompile.resolution; }
// el editor WEB no puede compilar juegos (sin cmake/emcc/gradle ni procesos en el navegador): esconde esas filas
static bool GameNoCompiler() {
#ifdef __EMSCRIPTEN__
    return true;
#else
    return false;
#endif
}
// Compilar juego: exporta + genera + compila EN SEGUNDO PLANO (worker): el editor no
// se congela; el progreso (etapa + %) lo muestra la barra overlay de abajo y el
// resultado llega por notificacion. Si ya hay un build corriendo, CompileGame avisa
// y no dispara otro. Usa el UI activo o el primero de la escena (boton tarjeta Juego).
// La CONFIG entera de la tarjeta (plataforma, modo ventana, orientacion, assets,
// fisica/sonido/debug) vive en g_projCompile (SaveW3D.h): viaja con el
// PROYECTO en el bloque raiz "compilar" del .w3d, se carga al abrir (import_w3d)
// y se escribe al guardar con los valores vigentes. Antes eran statics de aca y
// se reseteaban en cada arranque (el modo ventana elegido se perdia).
// nombres VISIBLES de cada valor (los del JSON son otros: ver W3dCompilar*Str)
static const char* PlatName(int p){ return (p==10)?"Dreamcast":(p==9)?"Nintendo 3DS":(p==8)?"PS Vita":(p==7)?"PSP":
    (p==6)?"Android 2.3":(p==5)?"Symbian .sisx":(p==4)?"Windows .exe":(p==3)?"Android":(p==2)?"WebGL":(p==1)?"Linux AppImage":"Linux .deb"; }
// el backend grafico que se usa con la plataforma elegida (SaveW3D: los que tiene cada una)
static const char* BackendNameGame(){
    return W3dCompileBackendName(g_projCompile.platform, W3dCompileBackendOf(g_projCompile.platform));
}
static const char* VentModeName(int m){ return (m==2)?T("Borderless"):(m==0)?T("Window"):T("Fullscreen"); }
// la ORIENTACION solo afecta a Android (manifest + hint SDL); en desktop/web no aplica.
static const char* OrientationName(int o){ return (o==2)?T("Landscape only"):(o==1)?T("Portrait only"):T("Any orientation"); }
// ASSETS: Sueltos = archivos visibles y editables al lado del binario (modding
// facil). Empaquetados = protegidos, DENTRO del binario, ofuscados (pak.cpp).
static const char* AssetNameMode(int m){ return (m==1)?T("Packed (protected)"):T("Loose (editable)"); }
// UID3 de Symbian del juego: 0 = sin asignar (el boton lo genera). Se muestra en hex.
static const char* UIDName(){
    static char buf[16];
    if (g_projCompile.uid == 0) return T("Generate");
    snprintf(buf, sizeof(buf), "0x%08X", g_projCompile.uid);
    return buf;
}
static UI* UIToCompile(){
    UI* u = (ActiveObj && ActiveObj->getType() == ObjectType::ui) ? (UI*)ActiveObj : NULL;
    if (!u && SceneCollection)
        for (size_t i = 0; i < SceneCollection->Childrens.size(); i++)
            if (SceneCollection->Childrens[i]->getType() == ObjectType::ui)
                { u = (UI*)SceneCollection->Childrens[i]; break; }
    return u;
}
static void ActionCompileGame(){
    extern bool CompileGame(UI*, int, int, int, bool, bool, bool, bool);
    // (un juego 3D no necesita UI: CompileGame decide si hay un juego que compilar)
    CompileGame(UIToCompile(), g_projCompile.platform, g_projCompile.windowMode,
                  g_projCompile.orientation, g_projCompile.usePhysics,
                  g_projCompile.useSound, g_projCompile.debugMode,
                  g_projCompile.assetsMode == 1);
}
// "EMPIEZA CON": la escena o el juego con que arranca el juego compilado. En un juego 3D, una raiz 3D del proyecto
// (escena3dInicial: W3dRootSetInitial); en uno solo 2D, una de sus escenas UI (escenaInicial). Queda en el .w3d
static std::string StartNameGame(){
    if (CompileGameEs3D()) {
        const std::vector<W3dRootRow>& fs = W3dRoots();
        const int i = W3dInitialRootIdx();
        if (i >= 0 && i < (int)fs.size()) return fs[(size_t)i].name;
        return SceneCollection ? SceneCollection->name : std::string();
    }
    if (!W3dInitialScene().empty()) return W3dInitialScene();
    UI* u = UIToCompile();
    return u ? u->name : std::string("-");
}
static PopupMenu* MenuStartGame = NULL;
static std::vector<std::string> gStartNames;   // los del menu abierto (id = indice; 3D o 2D segun el proyecto)
static void ActionPickedStart(int id){
    if (id < 0 || id >= (int)gStartNames.size()) return;
    if (CompileGameEs3D()) W3dRootSetInitial(gStartNames[(size_t)id]);
    else                     W3dSceneSetInitial(gStartNames[(size_t)id]);
    if (PropsActive && PropsActive->propGameStart) PropsActive->propGameStart->button->text = StartNameGame();
    g_redraw = true;
}
static void ActionMenuStart(){
    if (!PropsActive || !PropsActive->propGameStart) return;
    if (!MenuStartGame){ MenuStartGame = new PopupMenu(); MenuStartGame->action = ActionPickedStart; }
    MenuStartGame->Clear();
    MenuStartGame->title = T("Starts with");
    gStartNames.clear();
    if (CompileGameEs3D()) {
        const std::vector<W3dRootRow>& fs = W3dRoots();
        for (size_t i = 0; i < fs.size(); i++) if (W3dRootEs3D(fs[i].type)) gStartNames.push_back(fs[i].name);
        if (gStartNames.empty() && SceneCollection) gStartNames.push_back(SceneCollection->name);
    } else if (SceneCollection) {
        for (size_t i = 0; i < SceneCollection->Childrens.size(); i++)
            if (SceneCollection->Childrens[i]->getType() == ObjectType::ui) gStartNames.push_back(SceneCollection->Childrens[i]->name);
    }
    for (size_t i = 0; i < gStartNames.size(); i++) MenuStartGame->Add(gStartNames[i], (int)i);
    OpenMenuUnderButton(MenuStartGame, PropsActive->propGameStart->button);
}
