    if (PropsActive && PropsActive->propGameUID) PropsActive->propGameUID->hidden = (id != 5) || GameNoCompiler(); // UID: solo con Symbian
    if (PropsActive && PropsActive->propGameBackend) PropsActive->propGameBackend->button->text = BackendNameGame();
    g_redraw = true;
