// GENERAR un UID3 random para el JUEGO (app propia de Symbian: no pisa el editor). Rango
// self-signed 0xE0000000-0xEFFFFFFF. Queda en el .w3d (bloque "compilar") al guardar.
static void ActionGenerateUID(){
    static bool seeded = false;
    if (!seeded){ srand((unsigned)time(NULL)); seeded = true; }
    unsigned r = ((unsigned)rand() << 17) ^ ((unsigned)rand() << 6) ^ (unsigned)rand();
    g_projCompile.uid = 0xE0000000u | (r & 0x0FFFFFFFu);
    if (PropsActive && PropsActive->propGameUID) PropsActive->propGameUID->button->text = UIDName();
    Notify(T("Game UID generated (saved with the project)"), false);
    g_redraw = true;
}
