// ICONO del juego: un PNG con alpha en su MAXIMA definicion; Compilar juego genera
// de ahi los tamanos chicos (hicolor del .deb, mipmaps del APK, icono de ventana).
// Se persiste en el .w3d como ruta EXTERNA relativa (g_projIcon, ver SaveW3D.h).
static std::string IconNameGame(){
    if (g_projIcon.empty()) return T("(none)");
    size_t s = g_projIcon.find_last_of("/\\");
    return (s == std::string::npos) ? g_projIcon : g_projIcon.substr(s + 1);
}
static void ActionPickedIcon(const std::string& pickedPath){
    // CARGAR = QUEDA AFUERA: el archivo que el usuario acaba de elegir de su disco se referencia como EXTERNO
    // (W3dLoadExternal); a meterlo adentro del .w3d se lo pasa desde la Biblioteca
    // ("textures/piso.png"). Sin contenedor montado (proyecto v3) no cambia nada.
    const std::string path = W3dLoadExternal(pickedPath);
    std::string r = path;
    // relativa al .w3d si el archivo cae bajo su carpeta (asi el proyecto viaja entero)
    if (!w3dPath.empty()){
        size_t s = w3dPath.find_last_of("/\\");
        std::string dir = (s == std::string::npos) ? std::string() : w3dPath.substr(0, s + 1);
        if (!dir.empty() && r.size() > dir.size() && r.compare(0, dir.size(), dir) == 0)
            r = r.substr(dir.size());
    }
    g_projIcon = r;
    if (PropsActive && PropsActive->propGameIcon)
        PropsActive->propGameIcon->button->text = IconNameGame();
    g_redraw = true;
}
static void ActionMenuIcon(){
    OpenFileBrowser(T("Game icon"), T("Open"), ".png", ActionPickedIcon);
}
