// ajusta unidad/rango/pasos de una fila Width/Height segun la unidad (sizeMode)
static void FitRowSize(PropFloat* f, int mode){
    if (!f) return;
    bool px = (mode != TAM2D_FRACTION);   // pixeles y escalado editan en px
    f->unit = (mode == TAM2D_PX) ? "px" : (mode == TAM2D_SCALED ? "esc" : "");
    f->SetRange(px ? 1.0f : 0.005f, px ? 8192.0f : 8.0f);
    f->fineStep  = px ? 1.0f  : 0.005f;
    f->thickStep = px ? 10.0f : 0.05f;
    f->dragStep  = px ? 1.0f  : 0.002f;
}
