static void PickedScript(const std::string& pickedPath) {
    if (!ActiveObj) return;
    // lo GENERADO por una instancia de prefab: sus scripts son los del prefab (uno agregado o cambiado no se
    // guarda y corria los valores de los demas al guardar sus overrides). Se edita el prefab
    if (W3dPrefabIsGeneratedNotice(ActiveObj, true)) { g_scriptChangeIdx = -1; return; }
    // CARGAR = QUEDA AFUERA: el archivo que el usuario acaba de elegir de su disco se referencia como EXTERNO
    // (W3dLoadExternal); a meterlo adentro del .w3d se lo pasa desde la Biblioteca
    // ("textures/piso.png"). Sin contenedor montado (proyecto v3) no cambia nada.
    const std::string path = W3dLoadExternal(pickedPath);
    if (!ActiveObj->scriptData) ActiveObj->scriptData = new W3dScriptData();
    if (g_scriptChangeIdx >= 0 && g_scriptChangeIdx < (int)ActiveObj->scriptData->scripts.size()) {
        ActiveObj->scriptData->scripts[g_scriptChangeIdx].path = path;
    } else {
        W3dScriptEntry e; e.path = path;
        ActiveObj->scriptData->scripts.push_back(e);
    }
    g_scriptChangeIdx = -1;
    { extern void SimScriptsChanged(Object*); SimScriptsChanged(ActiveObj); }
    ScriptRefresh();
}
// ANIADIR un script: un MENU bajo el boton con los scripts del PROYECTO (los de adentro del .w3d y los que ya usa la
// escena: IDECollectScripts, la misma lista que el selector del IDE, solo los .lua) y al final "Cargar .lua...": el
// explorador del disco, para un script de AFUERA (escrito en otro IDE o guardado fuera del .w3d). Antes Aniadir abria
// directo el explorador, y un script guardado ADENTRO del .w3d no se le podia poner a ningun objeto (2026-11-11).
static PopupMenu* MenuScriptAdd = NULL;
static std::vector<std::string> gScriptAddPaths;
static const int kScriptLoadLua = 100000;
static void ActionScriptAddPicked(int id) {
    if (!ActiveObj) return;
    g_scriptChangeIdx = -1;
    if (id == kScriptLoadLua) { OpenFileBrowser(T("Load script"), T("Open"), ".lua .luac", PickedScript); return; }
    if (id < 0 || id >= (int)gScriptAddPaths.size()) return;
    PickedScript(gScriptAddPaths[(size_t)id]);   // (una entrada de adentro queda tal cual: W3dImportAsset)
}
static void ActionScriptAdd() {
    if (!ActiveObj) return;
    if (W3dPrefabIsGeneratedNotice(ActiveObj, true)) return;   // (ver PickedScript)
    if (!PropsActive || !PropsActive->propRowScript || PropsActive->propRowScript->buttons.empty()) return;
    if (!MenuScriptAdd) { MenuScriptAdd = new PopupMenu(); MenuScriptAdd->action = ActionScriptAddPicked; }
    MenuScriptAdd->Clear();
    MenuScriptAdd->title = T("Add");
    extern void IDECollectScripts(std::vector<std::string>* paths); extern std::string IDEScriptName(const std::string& path);
    std::vector<std::string> all;
    IDECollectScripts(&all);
    gScriptAddPaths.clear();
    for (size_t i = 0; i < all.size(); i++) {
        const std::string& r = all[i];
        if (r.size() >= 4 && r.compare(r.size() - 4, 4, ".lua") == 0) gScriptAddPaths.push_back(r);
    }
    if (gScriptAddPaths.empty()) MenuScriptAdd->Add(T("(no .lua scripts)"), -1);
    for (size_t i = 0; i < gScriptAddPaths.size(); i++)
        MenuScriptAdd->Add(IDEScriptName(gScriptAddPaths[i]), (int)i, (int)IconType::archive);
    MenuScriptAdd->Add(T("Load .lua..."), kScriptLoadLua, (int)IconType::folder);
    OpenMenuUnderButton(MenuScriptAdd, PropsActive->propRowScript->buttons[0]);
}
void _ScriptAddFwd(){ ActionScriptAdd(); }   // (el harness: el mismo boton)
// el script SELECCIONADO en la lista de la tarjeta Control (-1 = ninguno)
static int ActiveScriptIdx() {
    if (!ActiveObj || !ActiveObj->scriptData) return -1;
    int n = (int)ActiveObj->scriptData->scripts.size();
    if (n == 0) return -1;
    int a = ActiveObj->scriptData->active;
    if (a < 0) a = 0; if (a >= n) a = n - 1;
    ActiveObj->scriptData->active = a;
    return a;
}
// guarda el valor elegido para una propiedad de UN script
static void ScriptAssign(int yes, const std::string& prop, const std::string& value) {
    if (!ActiveObj || !ActiveObj->scriptData) return;
    if (yes < 0 || yes >= (int)ActiveObj->scriptData->scripts.size()) return;
    W3dScriptEntry& e = ActiveObj->scriptData->scripts[yes];
    for (size_t i = 0; i < e.refs.size(); i++)
        if (e.refs[i].first == prop) { e.refs[i].second = value; return; }
    e.refs.push_back(std::make_pair(prop, value));
}
static const char* ScriptValueOf(Object* o, int yes, const std::string& prop) {
    if (!o || !o->scriptData || yes < 0 || yes >= (int)o->scriptData->scripts.size()) return "";
    W3dScriptEntry& e = o->scriptData->scripts[yes];
    for (size_t i = 0; i < e.refs.size(); i++)
        if (e.refs[i].first == prop) return e.refs[i].second.c_str();
    return "";
}
// ---- propiedades de VALOR (tipo 2: numero / bool / texto) -------------------
// Cada fila tiene su editor nativo (PropFloat/PropBool/PropText) apuntando a un
// buffer PROPIO de esta lista; el commit escribe el string por instancia en
// W3dScriptEntry.refs (el MISMO canal donde viajan las refs) via ScriptAssign.
// Las filas viven exactamente lo que las tarjetas: se reconstruyen juntas.
struct ScriptValRow {
    int card;           // que tarjeta de script (indice en scriptData->scripts)
    std::string prop;   // el nombre de la propiedad en el .lua
    PropFloat* pf;      // subtipo 0 (numero); NULL si no
    PropBool*  pb;      // subtipo 1 (bool)
    PropText*  pt;      // subtipo 2 (texto)
    float f; bool b;    // los buffers estables que edita el widget
    std::string last;   // lo ULTIMO escrito/leido (si el widget difiere, hay que guardar)
    ScriptValRow() : card(-1), pf(NULL), pb(NULL), pt(NULL), f(0.0f), b(false) {}
};
static std::vector<ScriptValRow*> gScriptValRows;
static std::string ScriptValFmtFloat(float v) {
    char buf[48]; snprintf(buf, sizeof(buf), "%g", (double)v); return std::string(buf);
}
// guarda el valor de UNA fila si cambio (y avisa a la sim para verlo en vivo)
static void ScriptValSave(ScriptValRow* r, const std::string& v) {
    if (r->last == v || !ActiveObj) return;
    ScriptAssign(r->card, r->prop, v);
    r->last = v;
    // el proyecto queda con cambios (el guardado los lleva) y se ve al instante
    { extern bool SimActive(); extern void SimReresolve(Object*);
      if (SimActive()) SimReresolve(ActiveObj); }
    g_redraw = true;
}
// pasa por TODAS las filas de valor y persiste lo que el usuario haya editado.
// Corre una vez por frame (en el rebind) y tambien como onChange de los widgets:
// cubre flechas, arrastre, numpad, checkbox y el tipeo del campo de texto.
static void ScriptValsSync() {
    for (size_t i = 0; i < gScriptValRows.size(); i++) {
        ScriptValRow* r = gScriptValRows[i];
        if (r->pf)      ScriptValSave(r, ScriptValFmtFloat(r->f));
        else if (r->pb) ScriptValSave(r, r->b ? "true" : "false");
        else if (r->pt) ScriptValSave(r, r->pt->field.text);
    }
}
// las filas se destruyen JUNTO con las tarjetas (rebuild): soltar los buffers y,
// si el foco de texto estaba en una de estas filas, soltarlo tambien (mismo
// criterio que la tarjeta Paletas: un puntero colgado = crash al tipear).
static void ScriptValsClear() {
    for (size_t i = 0; i < gScriptValRows.size(); i++) delete gScriptValRows[i];
    gScriptValRows.clear();
}
static void CollectNames(Object* o, std::vector<std::string>* v) {
    if (!o) return;
    if (o != SceneCollection) v->push_back(o->name);
    for (size_t i = 0; i < o->Childrens.size(); i++) CollectNames(o->Childrens[i], v);
}
static void ActionPickedScriptRef(int id) {
    if (g_scriptCardSel < 0 || g_scriptCardSel >= (int)gScriptPropsMulti.size()) return;
    std::vector<W3dScriptProp>& props = gScriptPropsMulti[g_scriptCardSel];
    if (g_scriptPropSel < 0 || g_scriptPropSel >= (int)props.size()) return;
    W3dScriptProp& p = props[g_scriptPropSel];
    std::string value;
    if (p.type == 1) { if (id >= 0 && id < (int)p.options.size()) value = p.options[id]; }
    else             { if (id >= 0 && id < (int)gScriptObjNames.size()) value = gScriptObjNames[id]; }
    if (!value.empty()) ScriptAssign(g_scriptCardSel, p.name, value);
    // con el juego ANDANDO el cambio se ve al instante (se re-resuelven las refs)
    { extern bool SimActive(); extern void SimReresolve(Object*);
      if (SimActive()) SimReresolve(ActiveObj); }
    ScriptRefresh();
}
// QUITAR un script de un objeto (la ultima fila de su tarjeta). Sale de la UI para que el
// aviso al undo y el erase queden en UN solo lugar (mismo criterio que UndoDeleteClipArm).
//
// QUITARLO CORRE LOS INDICES de la lista de scripts, y los destinos de rename de las refs de
// lua van por (objeto, INDICE de script, indice de ref): sin el aviso, el Ctrl+Z de un rename
// anterior no deshacia la ref Y ADEMAS escribia el nombre viejo encima de la ref de OTRO
// script (vinculo roto en silencio, ni crash ni aviso). Quitar un script todavia no es
// deshacible -> es la familia (2) de Undo.h: hay que avisar. El .i del destino ES el indice de
// script, que es justo el que corre; el .j (la ref) no se toca, las refs solo crecen.
static void RemoveObjectScript(Object* o, int card) {
    if (!o || !o->scriptData) return;
    if (card < 0 || card >= (int)o->scriptData->scripts.size()) return;
    if (W3dPrefabIsGeneratedNotice(o, true)) return;   // (los scripts de lo generado son los del prefab)
    UndoDeletedList(W3dDestRefLua(o, card, 0));
    o->scriptData->scripts.erase(o->scriptData->scripts.begin() + card);
    { extern void SimScriptsChanged(Object*); SimScriptsChanged(o); }
}
// el harness de tests aprieta el MISMO boton (mismo idiom que _DeleteVertexFwdAnim)
void _RemoveObjectFwdScript(Object* o, int card){ RemoveObjectScript(o, card); }

// ---- botones de la tarjeta "Control" (la lista de scripts, estilo modificadores) ----
// QUITAR el script seleccionado.
static void ActionScriptRemove() {
    int a = ActiveScriptIdx();
    if (a < 0) return;
    RemoveObjectScript(ActiveObj, a);
    // la seleccion se queda en el lugar que ocupaba el borrado (o en el ultimo)
    int n = (int)ActiveObj->scriptData->scripts.size();
    ActiveObj->scriptData->active = (a >= n) ? n - 1 : a;
    ScriptRefresh();
}
// REORDENAR: el orden de la lista ES el orden de ejecucion, asi que mover uno cambia el
// comportamiento del juego. Mover CORRE LOS INDICES y los destinos de rename de las refs
// de lua van por (objeto, indice de script, indice de ref) -> hay que avisarle al undo
// (UndoMovedList), que es lo que exige el criterio general de Undo.h. Mover scripts no
// es deshacible todavia, igual que quitarlos.
static void MoveScriptOf(Object* o, int i, int j) {
    if (!o || !o->scriptData) return;
    std::vector<W3dScriptEntry>& v = o->scriptData->scripts;
    if (i < 0 || j < 0 || i >= (int)v.size() || j >= (int)v.size() || i == j) return;
    if (W3dPrefabIsGeneratedNotice(o, true)) return;   // (los scripts de lo generado son los del prefab)
    W3dScriptEntry t = v[i]; v[i] = v[j]; v[j] = t;
    o->scriptData->active = j;                    // el activo VIAJA con el script que se movio
    UndoMovedList(W3dDestRefLua(o, -1, 0), i, j);
    { extern void SimScriptsChanged(Object*); SimScriptsChanged(o); }
    ScriptRefresh();
}
// el harness de tests aprieta los MISMOS botones (mismo idiom que _RemoveObjectFwdScript)
void _MoveObjectFwdScript(Object* o, int i, int j){ MoveScriptOf(o, i, j); }
// el OJO de la lista de scripts (tarjeta Control): prende o apaga el script i del objeto activo SIN quitarlo y sin
// ocultar el objeto. Apagado, el motor no llama a ninguna de sus funciones (W3dScriptEntry::apagado, se guarda en el
// .w3d); con el juego andando cambia en ese momento (W3dScriptSetOff: prenderlo corre su start() si no corrio).
static bool ScriptToggleEye(int i) {
    if (!ActiveObj || !ActiveObj->scriptData) return false;
    std::vector<W3dScriptEntry>& v = ActiveObj->scriptData->scripts;
    if (i < 0 || i >= (int)v.size()) return false;
    if (W3dPrefabIsGeneratedNotice(ActiveObj, true)) return true;   // (los scripts de lo generado son los del prefab)
    v[i].off = !v[i].off;
    W3dScriptSetOff(ActiveObj, i, v[i].off);
    g_redraw = true;
    return true;
}
void _ScriptToggleEyeFwd(int i){ ScriptToggleEye(i); }   // (el harness: el mismo click)
static void MoveScript(int i, int j) { MoveScriptOf(ActiveObj, i, j); }
static void ActionScriptUp()   { int a = ActiveScriptIdx(); if (a > 0) MoveScript(a, a - 1); }
static void ActionScriptDown() {
    int a = ActiveScriptIdx();
    if (a >= 0 && ActiveObj && ActiveObj->scriptData &&
        a + 1 < (int)ActiveObj->scriptData->scripts.size()) MoveScript(a, a + 1);
}
// el click en cualquier fila de una tarjeta de script: se localiza QUE tarjeta fue
// (el handler del panel deja su selectIndex >= 0) y que fila
static void ActionScriptCardRow() {
    if (!PropsActive) return;
    int card = -1, row = -1;
    for (int i = 0; i < Properties::kMaxScriptCards; i++) {
        GroupPropertie* g = PropsActive->propScriptCards[i];
        if (g && g->visible && g->selectIndex >= 0) { card = i; row = g->selectIndex; break; }
    }
    if (card < 0 || !ActiveObj || !ActiveObj->scriptData) return;
    if (card >= (int)ActiveObj->scriptData->scripts.size()) return;
    GroupPropertie* g = PropsActive->propScriptCards[card];
    if (row == 0) {                 // [0] el archivo: elegir otro .lua
        if (W3dPrefabIsGeneratedNotice(ActiveObj, true)) return;   // (ver PickedScript)
        g_scriptChangeIdx = card;
        OpenFileBrowser(T("Load script"), T("Open"), ".lua .luac", PickedScript);
        return;
    }
    // las demas filas: una PROPIEDAD expuesta (desplegable de objetos u opciones). (Antes la ultima era "Quitar
    // script"; ya no esta: se quita con Quitar en la tarjeta Control.)
    int pi = row - 1;
    g_scriptCardSel = card; g_scriptPropSel = pi;
    if (card >= (int)gScriptPropsMulti.size() || pi < 0 || pi >= (int)gScriptPropsMulti[card].size()) return;
    W3dScriptProp& p = gScriptPropsMulti[card][pi];
    if (p.type == 3) {   // un BOTON: llama a su funcion (con el juego andando, en vivo; sin el, como un complemento)
        // con el juego PARADO lo que haga es un cambio del usuario: va al historial (Ctrl+Z lo deshace entero). Jugando
        // no (SimUndoScriptStart no hace nada): al Parar se repone todo igual
        SimUndoScriptStart();
        const bool ok = W3dScriptCallButton(ActiveObj, card, p.name);
        SimUndoScriptConfirm();    // (aunque haya fallado a la mitad: lo que alcanzo a hacer tambien se deshace)
        if (!ok) {
            Notify(std::string(T("The button's function failed")) + ": " + W3dScriptLastError(), true);
        }
        ScriptRefresh();
        return;
    }
    if (!MenuScriptRef) { MenuScriptRef = new PopupMenu(); MenuScriptRef->action = ActionPickedScriptRef; }
    MenuScriptRef->Clear();
    MenuScriptRef->title = p.name;
    if (p.type == 1) {
        for (size_t i = 0; i < p.options.size(); i++)
            MenuScriptRef->Add(p.options[i], (int)i);
    } else {
        gScriptObjNames.clear();
        CollectNames(SceneCollection, &gScriptObjNames);
        for (size_t i = 0; i < gScriptObjNames.size(); i++)
            MenuScriptRef->Add(gScriptObjNames[i], (int)i);
    }
    PropButton* pb = (PropButton*)g->properties[row];
    OpenMenuUnderButton(MenuScriptRef, pb->button);
}

// ============================ PALETA DE COLORES ============================
// Las paletas viven a NIVEL PROYECTO (W3dPalettes.h): cualquier objeto (3D o
// 2D) elige una POR NOMBRE con herencia (tarjeta "Paleta" del objeto; "" =
// igual que el padre). La GESTION completa (crear/renombrar/borrar paletas y
// colores, con los invariantes de mismo-largo y correccion de referencias)
// vive en la tarjeta "Paletas" de la pestania 0 (la del proyecto).
static Image2D* Img2dActive();      // (definidos mas abajo; las acciones de paleta los usan)
static Rect2D* Rect2dActive();
static Slice9* S9Active();
static Button2D* Btn2dActive();
static UI* UIActiveProps();
// nombre a mostrar para un indice pal* del objeto (contra su paleta EFECTIVA)
static const char* PalName(Object* o, int idx){
    if (!o || idx < 0) return T("Own");
    std::vector<PaletteColor>* cs = W3dEffectiveColors(o);
    if (!cs || idx >= (int)cs->size()) return T("Own");
    return (*cs)[idx].name.c_str();
}
// que indice esta editando el menu de paleta abierto (apunta al campo int del elemento)
static int* g_palTarget = NULL;
static PropButton* g_palButton = NULL;
static PopupMenu* MenuPal = NULL;
static void ActionPalPicked(int id){
    if (!g_palTarget) return;
    *g_palTarget = id;   // -1 = color propio
    if (g_palButton) g_palButton->button->text = PalName(ActiveObj, id);
    if (PropsActive) PropsActive->target = NULL;   // re-bind: el swatch aparece/desaparece
    g_redraw = true;
}
static void OpenMenuPal(int* target, PropButton* button){
    if (!button) return;
    std::vector<PaletteColor>* cs = W3dEffectiveColors(ActiveObj);
    g_palTarget = target; g_palButton = button;
    if (!MenuPal){ MenuPal = new PopupMenu(); MenuPal->action = ActionPalPicked; }
    MenuPal->Clear();
    MenuPal->title = T("Palette");
    MenuPal->Add(T("Own"), -1);
    if (cs)
        for (size_t i = 0; i < cs->size(); i++)
            MenuPal->Add((*cs)[i].name, (int)i);
    OpenMenuUnderButton(MenuPal, button->button);
}
static void ActionPalT2d(){  Text2D* t = T2dActive();   if (t && PropsActive) OpenMenuPal(&t->palColor, PropsActive->propT2dPal); }
static void ActionPalImg(){  Image2D* i = Img2dActive();if (i && PropsActive) OpenMenuPal(&i->palTint, PropsActive->propImgPal); }
static void ActionPalRect(){ Rect2D* r = Rect2dActive(); if (r && PropsActive) OpenMenuPal(&r->palColor, PropsActive->propRectPal); }
static void ActionPalS9(){   Slice9* s = S9Active();     if (s && PropsActive) OpenMenuPal(&s->palTint, PropsActive->propS9Pal); }
static void ActionPalBtnBackground(){ Button2D* b = Btn2dActive(); if (b && PropsActive) OpenMenuPal(&b->palBackground, PropsActive->propBtnPalBackground); }
static void ActionPalBtnText(){ Button2D* b = Btn2dActive(); if (b && PropsActive) OpenMenuPal(&b->palText, PropsActive->propBtnPalText); }
static void ActionPalBtnBorder(){ Button2D* b = Btn2dActive(); if (b && PropsActive) OpenMenuPal(&b->palBorder, PropsActive->propBtnPalBorder); }
static void ActionPalBtnHover(){ Button2D* b = Btn2dActive(); if (b && PropsActive) OpenMenuPal(&b->palHover, PropsActive->propBtnPalHover); }
// cual paleta del proyecto muestra/edita la tarjeta "Paletas" (pestania 0)
static int gPalEdit = 0;
// agregar un color: INVARIANTE 1 (va a TODAS las paletas, mismo nombre/valor)
static void ActionPaletteAdd(){
    if (W3dPalettes().empty()) return;   // primero crear una paleta (desplegable)
    // el nombre unico lo pone W3dPaletteAddColor (antes "Color N" con cantidad+1 y SIN
    // chequear: borrar uno del medio y agregar otro repetia el nombre)
    float white[4] = { 1.0f, 1.0f, 1.0f, 1.0f };
    W3dPaletteAddColor("Color", white);
    if (PropsActive) PropsActive->target = NULL;   // re-bind: la tarjeta se reconstruye
    g_redraw = true;
}
// los nombres de los colores se editan EN VIVO (las filas PropColorPal de la
// tarjeta); el de la PALETA en edicion, en su PropText (SyncPaletteName)
// desplegable de PALETAS de la tarjeta del proyecto: elegir cual se EDITA,
// crear una nueva (copia de la editada) o borrar la editada
static PopupMenu* MenuPalettes = NULL;
static PopupMenu* MenuDeletePalette = NULL;   // submenu "Borrar paleta > <cual>"
static void ActionPickedPalettes(int id){
    // FUSIONADA: el dropdown elige la paleta DEL OBJETO (o hereda), y ademas gestiona.
    // gPalEdit sigue a ActiveObj->palette (se recalcula en el rebind), no se fija aca.
    std::vector<Palette>& ps = W3dPalettes();
    int n = (int)ps.size();
    if (id == -1) {                      // "Igual que el padre": el objeto hereda
        if (ActiveObj) ActiveObj->palette.clear();
    } else if (id == n) {                // "Nueva paleta": una nueva por defecto, asignada al objeto
        int idx = W3dNewPalette("Palette", -1);
        if (idx >= 0 && ActiveObj) ActiveObj->palette = W3dPalettes()[idx].name;
    } else if (id == n + 2) {            // "Duplicar": copia de la actual, asignada al objeto
        int idx = W3dNewPalette("Palette", gPalEdit);
        if (idx >= 0 && ActiveObj) ActiveObj->palette = W3dPalettes()[idx].name;
    } else if (id >= 2000) {             // "Borrar paleta > <cual>": del SUBMENU, cualquiera del proyecto
        // Se puede borrar CUALQUIER paleta, no solo la asignada a este objeto: antes el item
        // aparecia unicamente con una paleta propia asignada, asi que heredando (que es el
        // default) no habia forma de borrar ninguna.
        const int victim = id - 2000;
        if (victim >= 0 && victim < n) {
            const std::string name = ps[victim].name;
            W3dPaletteDeletePalette(victim);
            // el objeto solo pierde su seleccion si borro JUSTO la que tenia elegida
            if (ActiveObj && ActiveObj->palette == name) ActiveObj->palette.clear();
        }
    } else {                             // elegir una paleta existente -> asignar al objeto
        if (ActiveObj && id >= 0 && id < n) ActiveObj->palette = W3dPalettes()[id].name;
    }
    if (PropsActive) PropsActive->target = NULL;
    g_redraw = true;
}
static void ActionMenuPalettes(){
    if (!PropsActive || !PropsActive->propPaletteSel) return;
    if (!MenuPalettes){ MenuPalettes = new PopupMenu(); MenuPalettes->action = ActionPickedPalettes; }
    MenuPalettes->Clear();
    MenuPalettes->title = T("Palette");
    std::vector<Palette>& ps = W3dPalettes();
    int n = (int)ps.size();
    MenuPalettes->Add(T("Same as parent"), -1);       // heredar del padre (default)
    for (int i = 0; i < n; i++)
        MenuPalettes->Add(ps[i].name, i);
    MenuPalettes->Add(T("New Palette"), n);             // nueva por defecto, asignada al objeto
    if (gPalEdit >= 0 && gPalEdit < n)
        MenuPalettes->Add(T("Duplicate"), n + 2);      // copia de la actual (necesita una asignada)
    if (n > 0) {
        // BORRAR: submenu con TODAS las paletas del proyecto. Antes borraba "la actual" y solo
        // aparecia con una asignada al objeto -> heredando no se podia borrar ninguna, que es
        // el caso normal. Ademas asi se ve CUAL se esta por borrar.
        if (!MenuDeletePalette) MenuDeletePalette = new PopupMenu();
        MenuDeletePalette->Clear();
        MenuDeletePalette->title  = T("Delete Palette");
        MenuDeletePalette->action = ActionPickedPalettes;   // los ids 2000+i los maneja la misma accion
        for (int i = 0; i < n; i++) MenuDeletePalette->Add(ps[i].name, 2000 + i);
        MenuPalettes->Add(T("Delete Palette"), -2, -1, MenuDeletePalette);
    }
    OpenMenuUnderButton(MenuPalettes, PropsActive->propPaletteSel->button);
}
// el desplegable "Paleta" del OBJETO: "Igual que el padre" (default, hereda)
// o una paleta del proyecto. Cambiarla re-pinta al objeto Y sus herederos
// (palette swap en vivo).
static PopupMenu* MenuPaletteObj = NULL;
