// ====================================================================
// selector de TARGET (objeto linkeado) para camara e instance/array/mirror
// (ambos tipos heredan de Target). Un desplegable con los objetos de la escena.
// ====================================================================
static PopupMenu* MenuTarget = NULL;
static std::vector<Object*> gTargetCandidates; // id - 1 -> objeto

// devuelve la parte Target* de ActiveObj si es camara o instance (sino NULL)
static Target* ObjAsTarget(Object* o){
    if (!o) return NULL;
    if (o->getType() == ObjectType::camera)   return static_cast<Camera*>(o);
    if (o->getType() == ObjectType::instance) return static_cast<Instance*>(o);
    return NULL;
}

// junta los objetos de la escena que pueden ser target (no el activo, no las
// colecciones, no a si mismo para evitar recursion)
static void CollectTargets(Object* node){
    if (!node) return;
    for (size_t i = 0; i < node->Childrens.size(); i++){
        Object* c = node->Childrens[i];
        if (c != ActiveObj && c->getType() != ObjectType::collection)
            gTargetCandidates.push_back(c);
        CollectTargets(c);
    }
}

static void ActionPickedTarget(int id){
    Target* tgt = ObjAsTarget(ActiveObj);
    if (!tgt) return;
    if (id == 0){ tgt->target = NULL; tgt->targetName = ""; return; } // None
    int idx = id - 1;
    if (idx >= 0 && idx < (int)gTargetCandidates.size()){
        Object* o = gTargetCandidates[idx];
        tgt->target = o;
        tgt->targetName = o->name;
    }
}

static void ActionMenuTarget(){
    if (!PropsActive) return;
    if (!ObjAsTarget(ActiveObj)) return;
    if (!MenuTarget){ MenuTarget = new PopupMenu(); MenuTarget->action = ActionPickedTarget; }
    MenuTarget->Clear();
    MenuTarget->Add(T("None"), 0);
    gTargetCandidates.clear();
    CollectTargets(SceneCollection);
    for (size_t i = 0; i < gTargetCandidates.size(); i++)
        MenuTarget->Add(gTargetCandidates[i]->name, 1 + (int)i,
                            (int)ObjectIcon(gTargetCandidates[i]));
    bool isCam = ActiveObj->getType() == ObjectType::camera;
    Button* b = (isCam ? PropsActive->propBtnCamTarget
                       : PropsActive->propBtnInstTarget)->button;
    MenuTarget->Open(b->sx, b->sy + b->height - GlobalScale,
                      MenuScreenW, MenuScreenH);
    OpenMenu = MenuTarget;
}

