static Modifier* ActiveModUI(){
    if (!ActiveObj || ActiveObj->getType()!=ObjectType::mesh) return NULL;
    Mesh* m=(Mesh*)ActiveObj;
    if (m->activeModifier<0 || m->activeModifier>=(int)m->modifiers.size()) return NULL;
    return m->modifiers[m->activeModifier];
}
// un param del modificador cambio (checkbox/float/target) -> REGENERAR la malla generada + redibujar
static void ActionModParamChanged(){
    if (ActiveObj && ActiveObj->getType()==ObjectType::mesh) ((Mesh*)ActiveObj)->GenerateMeshModified();
    g_redraw = true;
}
// EDIT MODE: al editar un campo X/Y/Z del panel de Vertices, traslada RIGIDO la seleccion para que su centro caiga
// en el valor tipeado. Convencion Z-up del panel: campo X->local x, campo Y->local z, campo Z->local y (igual que
// el transform de objeto). Permite dejar un vert EXACTO (ej. X e Y en 0 -> sobre el eje del Screw).
static void ActionEditPos(){
    if (InteractionMode != EditMode || !g_editMesh || !PropsActive) return;
    Mesh* m = (Mesh*)g_editMesh; m->EnsureEdit();
    if (!m->edit) return;
    float cx, cy, cz; if (!m->edit->SelectionCenter(cx, cy, cz)) return; // centro LOCAL actual
    Vector3 delta(PropsActive->editPosX - cx, PropsActive->editPosZ - cy, PropsActive->editPosY - cz);
    MoveSelectionEditLocal(m, delta); // no-op si delta=0
    g_redraw = true;
}
// centro UV de la SELECCION EFECTIVA (tarjeta "Transform UV" de la pestania Transformar):
// promedio de las posiciones UV UNICAS de los verts seleccionados (misma regla que el pivote
// mediana del editor UV: los splits en el mismo lugar cuentan 1 sola vez). El conjunto sale de
// UVVertsSelEffective (UVEditor.cpp): si hay un editor UV con seleccion PROPIA (sync OFF) manda
// esa -- lo que se ve marcado en el UV es lo que la tarjeta muestra y mueve; si no, la del 3D.
// false si la malla no tiene uv o no hay nada seleccionado.
bool UVVertsSelEffective(Mesh* m, std::vector<char>& sv); // (decl. en UVEditor.h)
static bool CenterUVSelectionEdit(Mesh* m, float& cu, float& cv){
    if (!m || !m->uv || m->vertexSize <= 0) return false;
    std::vector<char> sv;
    if (!UVVertsSelEffective(m, sv)) return false;
    std::set< std::pair<float,float> > unique;
    double su = 0, svv = 0;
    for (int i = 0; i < m->vertexSize; i++) if (sv[i]) {
        std::pair<float,float> p(m->uv[i*2], m->uv[i*2+1]);
        if (unique.insert(p).second) { su += p.first; svv += p.second; }
    }
    if (unique.empty()) return false;
    cu = (float)(su / (double)unique.size());
    cv = (float)(svv / (double)unique.size());
    return true;
}
// pestania TRANSFORMAR: al editar X/Y de la tarjeta "Transform UV", traslada RIGIDO los UVs de la
// seleccion de edit mode para que su centro caiga en el valor tipeado. Reusa el NUCLEO compartido
// UVMoveSelectionEdit (UVEditor.cpp): mismo tratamiento que el G de UVs, con su undo LIVIANO
// (UndoUV*, un paso por edicion de campo -> Ctrl+Z lo deshace).
bool UVMoveSelectionEdit(Mesh* m, float dU, float dV); // nucleo compartido (decl. en UVEditor.h)
static void ActionEditUV(){
    if (InteractionMode != EditMode || !g_editMesh || !PropsActive) return;
    Mesh* m = (Mesh*)g_editMesh;
    float cu, cv; if (!CenterUVSelectionEdit(m, cu, cv)) return;
    UVMoveSelectionEdit(m, PropsActive->uvPosU - cu, PropsActive->uvPosV - cv); // no-op si delta=0
    g_redraw = true;
}
