static void ActionPickedArmTarget(int id){
    Modifier* mod = ActiveModUI(); if (!mod) return;
    int idx = id - 1;
    mod->target = (idx >= 0 && idx < (int)gArmTargets.size()) ? gArmTargets[idx] : NULL;
    if (ActiveObj && ActiveObj->getType() == ObjectType::mesh) UpdateSkinArmature((Mesh*)ActiveObj);
    g_redraw = true;
}
