    for (size_t i = 0; i < gArmTargets.size(); i++)
        MenuArmTarget->Add(gArmTargets[i]->name, 1 + (int)i, (int)IconType::armature);
    OpenMenuUnderButton(MenuArmTarget, PropsActive->propArmTarget->button);
