// ===== tarjeta "Post Processing": la pila de efectos (render/PostProcess.h) =====
// la pila del objeto Postproceso ACTIVO (la tarjeta es suya); sin uno, una vacia y apagada (la tarjeta no se ve)
static W3dPostOptions gEmptyPostPanel;
static W3dPostOptions& PostPanel() {
    if (ActiveObj && ActiveObj->getType() == ObjectType::postProcess) return ((PostProcess*)ActiveObj)->opt;
    gEmptyPostPanel = W3dPostOptions();
    return gEmptyPostPanel;
}
#define g_post PostPanel()
// las filas del efecto ELEGIDO apuntan a SUS numeros (la lista es un vector: al agregar o quitar se vuelven a enlazar)
void PostRowsPanel(Properties* P) {
    if (!P || !P->propPost) return;
    const bool hasObj = ActiveObj && ActiveObj->getType() == ObjectType::postProcess;
    if (P->propPostOn) P->propPostOn->value = hasObj ? &g_post.on : NULL;
    const int n = (int)g_post.effects.size();
    if (g_post.active >= n) g_post.active = n - 1;
    if (g_post.active < 0 && n > 0) g_post.active = 0;
    W3dPostEffect* e = (g_post.on && g_post.active >= 0) ? &g_post.effects[(size_t)g_post.active] : NULL;
    const int t = e ? e->type : -1;
    if (P->propPostCPU) {
        const bool show = g_post.on && W3dPostByCPU();
        if (P->propPostCPU->hidden != !show) { P->propPostCPU->hidden = !show; PropertiesLayoutDirty = true; }
    }
    if (P->propListPost) { P->propListPost->selectIndex = g_post.active; P->propListPost->FitWindow(); }
    if (P->propRowPost && !P->propRowPost->buttons.empty()) {
        VisibleIfChanges(P->propRowPost->buttons[0], g_post.on);
    }
    if (P->propRowPostMove && P->propRowPostMove->buttons.size() >= 2) {
        VisibleIfChanges(P->propRowPostMove->buttons[0], g_post.on && n >= 2);
        VisibleIfChanges(P->propRowPostMove->buttons[1], g_post.on && n >= 2);
    }
    P->propPostActive->value     = e ? &e->active : NULL;
    P->propPostGrainInt->value   = (t == W3dPostGrain) ? &e->v[0] : NULL;
    P->propPostGrainSize->value  = (t == W3dPostGrain) ? &e->v[1] : NULL;
    P->propPostGrainColor->value = (t == W3dPostGrain) ? &e->opt : NULL;
    P->propPostFocusCam->value   = (t == W3dPostFocus) ? &e->opt : NULL;
    // (con el foco de la camara la distancia la pone ella: la fila se esconde)
    P->propPostFocusDist->value   = (t == W3dPostFocus && !e->opt) ? &e->v[0] : NULL;
    P->propPostFocusRange->value  = (t == W3dPostFocus) ? &e->v[1] : NULL;
    // (y el desenfoque lo da la APERTURA de la camara)
    P->propPostFocusBlur->value = (t == W3dPostFocus && !e->opt) ? &e->v[2] : NULL;
    P->propPostMovObt->value    = (t == W3dPostMotion) ? &e->v[0] : NULL;
    for (int k = 0; k < 6; k++) if (P->propPostBloom[k]) P->propPostBloom[k]->value = (t == W3dPostBloom) ? &e->v[k] : NULL;
    if (P->propPostBloomColor)  P->propPostBloomColor->value  = (t == W3dPostBloom) ? e->col : NULL;
    if (P->propPostFastBloom) P->propPostFastBloom->value = (t == W3dPostBloom) ? &e->opt : NULL;
    PropertiesLayoutDirty = true;
}
static void ActionPostChange() { PostRowsPanel(PropsActive); g_redraw = true; }
static int PostCount() { return (int)g_post.effects.size(); }
static std::string PostText(int i) {
    if (i < 0 || i >= (int)g_post.effects.size()) return std::string();
    const W3dPostEffect& e = g_post.effects[(size_t)i];
    return std::string(T(W3dPostName(e.type))) + (e.active ? "" : std::string(" (") + T("off") + ")");
}
static void PostPick(int i) { g_post.active = i; PostRowsPanel(PropsActive); g_redraw = true; }
struct RegisterPostList { RegisterPostList() { PostRowsCount = PostCount; PostRowText = PostText; PostRowSelect = PostPick; } };
static RegisterPostList gRegisterPostList;
static PopupMenu* MenuAddPost = NULL;
static void ActionAddPickedPost(int type) {
    if (type < 0 || type >= W3dPostTypes) return;
    W3dPostEffect e; W3dPostDefaults(e, type);
    g_post.effects.push_back(e);
    g_post.active = (int)g_post.effects.size() - 1;
    PostRowsPanel(PropsActive); g_redraw = true;
}
static void ActionMenuAddPost() {
    if (!PropsActive || !PropsActive->propRowPost || PropsActive->propRowPost->buttons.empty()) return;
    if (!MenuAddPost) {
        MenuAddPost = new PopupMenu(); MenuAddPost->action = ActionAddPickedPost;
        for (int t = 0; t < W3dPostTypes; t++) MenuAddPost->Add(T(W3dPostName(t)), t);
    }
    OpenMenuUnderButton(MenuAddPost, PropsActive->propRowPost->buttons[0]);
}
static void ActionRemovePost() {
    if (g_post.active < 0 || g_post.active >= (int)g_post.effects.size()) return;
    g_post.effects.erase(g_post.effects.begin() + g_post.active);
    if (g_post.active >= (int)g_post.effects.size()) g_post.active = (int)g_post.effects.size() - 1;
    PostRowsPanel(PropsActive); g_redraw = true;
}
static void MovePost(int d) {
    const int i = g_post.active, j = i + d;
    if (i < 0 || j < 0 || i >= (int)g_post.effects.size() || j >= (int)g_post.effects.size()) return;
    std::swap(g_post.effects[(size_t)i], g_post.effects[(size_t)j]);
    g_post.active = j;
    PostRowsPanel(PropsActive); g_redraw = true;
}
static void ActionPostUpload() { MovePost(-1); }
static void ActionPostLower() { MovePost(1); }
