// las filas que dependen del FORMATO y de la COMPOSICION FINAL: la calidad (JPG y video), el alfa RGBA (PNG) y el
// postprocesado. Sin la composicion final, solo se guardan los pases tildados. Un VIDEO es solo la composicion final:
// sin los tildes de los pases ni el de la composicion (queda el postprocesado)
static const char* AntialiasText(int s);   // (el menu del antialiasing: mas abajo)
void RenderRowsFormat(Properties* P){
    if (!P || !P->propRenderFormat) return;
    if (g_render.format < 0 || g_render.format >= kRenderFormatsN) g_render.format = 0;
    const bool video = g_render.format >= 2;
    P->propRenderFormat->button->text = kRenderFormats[g_render.format];
    P->propRenderQuality->value = (RenderFormat() == 1) ? &g_render.quality : NULL;   // (JPG; el video va por su bitrate)
    if (P->propRenderVideoCodec) { P->propRenderVideoCodec->hidden = !video; P->propRenderVideoCodec->button->text = kVideoCodecs[VideoCodec()]; }
    if (P->propRenderVideoKbps) P->propRenderVideoKbps->value = video ? &g_render.videoKbps : NULL;
    // el ANTIALIASING: solo sin trazado de rayos (el trazado ya promedia sus muestras)
    if (P->propRenderAntialias) { P->propRenderAntialias->hidden = g_rt.on; P->propRenderAntialias->button->text = AntialiasText(g_render.antialias); }
    if (P->propRenderZbuffer)  P->propRenderZbuffer->value  = video ? NULL : &g_render.zbuffer;
    if (P->propRenderNormal)   P->propRenderNormal->value   = video ? NULL : &g_render.normal;
    if (P->propRenderAlpha)    P->propRenderAlpha->value    = video ? NULL : &g_render.alpha;
    if (P->propRenderVectors) P->propRenderVectors->value = video ? NULL : &g_render.vectors;
    P->propRenderFinal->value = video ? NULL : &g_render.final;
#ifdef W3D_SYMBIAN
    P->propRenderFinalAlpha->value = NULL;   // (el N95 guarda PNG sin alfa)
#else
    P->propRenderFinalAlpha->value = (g_render.final && g_render.format == 0) ? &g_render.finalAlpha : NULL;
#endif
    P->propRenderPost->value = (video || g_render.final) ? &g_render.post : NULL;
    // el AUDIO: "Con sonido" es de los videos; el formato y el bitrate, del sonido del video y de "Renderizar audio"
    if (P->propRenderSound) P->propRenderSound->value = video ? &g_render.sound : NULL;
    if (P->propRenderAudioFmt) P->propRenderAudioFmt->button->text = kAudioFormats[AudioFormat()];
    // (el bitrate: el del formato elegido; en el telefono y en la web, tambien el del sonido de su MP4, que va siempre
    // en AAC)
    bool withKbps = AudioWithBitrate(AudioFormat());
#if defined(W3D_VIDEO_ANDROID) || defined(W3D_VIDEO_SYMBIAN) || defined(W3D_VIDEO_WEB)
    if (video) withKbps = true;   // (el sonido del MP4 va siempre en AAC)
#endif
    if (P->propRenderAudioKbps) P->propRenderAudioKbps->value = withKbps ? &g_render.audioKbps : NULL;
    PropertiesLayoutDirty = true;
    g_redraw = true;
}
static void ActionRenderFinal(){ RenderRowsFormat(PropsActive); }
