// valida que el proyecto tenga NOMBRE antes de guardar. Si falta, marca el campo en rojo
// (PropText::error) + avisa por toast, y devuelve false: el caller NO guarda (antes, sin
// nombre, caia silenciosamente en el explorador de "Guardar como" -> parecia que no pasaba nada).
static bool ProjValidateName() {
    if (!PropsActive || !PropsActive->propProjName) return false;
    bool missing = PropsActive->propProjName->field.text.find_first_not_of(" \t") == std::string::npos;
    PropsActive->propProjName->error = missing;
    if (missing) {
        extern void Notify(const std::string&, bool);
        Notify(T("Give the project a name to save it"), true);
        g_redraw = true;
    }
    return !missing;
}
static void ActionProjSave() {
    if (!ProjValidateName()) return;
    std::string r = ProjCompletePath();
    if (SaveW3D(r)) { w3dPath = r; ProjectSyncFields(); }
}
