// ROMBO de keyframe del panel: opera sobre el OBJETO ACTIVO en el FRAME ACTUAL.
// rombo de la CAMARA ACTIVA: 3 (verde) = la camara elegida NO es la que dice la pista en este frame (cambio sin
// guardar); 2 = hay un corte en este frame y coincide; 1 = la pista existe y coincide; 0 = no hay pista
static int ActiveCamState(){
    AnimProperty* ap = W3dCamTrack(ActiveSceneAnim, false);
    const char* track = W3dCamInFrame(ActiveSceneAnim, CurrentFrame);
    // SIN PISTA (lo de siempre al arrancar: ninguna camara activa esta animada) no hay nada que marcar. Antes salia en
    // verde "cambio sin guardar" como si hubiera un keyframe; la camara activa se cambia cuando se quiera
    if (!ap || ap->keyframes.empty() || !track) return 0;
    if (!CameraActive || CameraActive->name != track) return 3;
    for (size_t i = 0; i < ap->keyframes.size(); i++) if (ap->keyframes[i].frame == CurrentFrame) return 2;
    return 1;
}
// el rombo de la casilla "Camara activa" de UNA camara (la tarjeta Camara): 0 = la pista no la nombra nunca; 1 = tiene
// algun corte (verde oscuro); 2 = hay un corte con ella en este frame (verde); 3 = la casilla no dice lo que dice la
// pista en este frame (cambio sin guardar: un click lo keya)
static int CamCheckState(Object* o){
    AnimProperty* ap = W3dCamTrack(ActiveSceneAnim, false);
    if (!o || o->getType() != ObjectType::camera || !ap || ap->keyframes.empty()) return 0;
    const char* track = W3dCamInFrame(ActiveSceneAnim, CurrentFrame);
    const bool isActive = CameraActive == static_cast<Camera*>(o);
    const bool trackDiceIs = track && o->name == track;
    for (size_t i = 0; i < ap->keyframes.size(); i++)
        if (ap->keyframes[i].frame == CurrentFrame && trackDiceIs) return isActive ? 2 : 3;
    if (isActive != trackDiceIs) return 3;
    for (size_t i = 0; i < ap->keyframes.size(); i++) {
        const char* n = W3dCamInFrame(ActiveSceneAnim, ap->keyframes[i].frame);
        if (n && o->name == n) return 1;
    }
    return 0;
}
// su rombo: con un corte de ESTA camara en este frame, lo saca; si no, la hace la activa y pone el corte aca
static void CamCheckToggle(Object* o){
    if (!o || o->getType() != ObjectType::camera) return;
    if (ActiveAnimKind == 2) { Notify(T("A game has no keyframes: choose one of its clips in the timeline to animate"), true); return; }
    UndoKeyframesStart();
    AnimProperty* ap = W3dCamTrack(ActiveSceneAnim, false);
    bool removed = false;
    if (ap) for (size_t i = 0; i < ap->keyframes.size(); i++) {
        if (ap->keyframes[i].frame != CurrentFrame) continue;
        const char* n = W3dCamInFrame(ActiveSceneAnim, CurrentFrame);
        if (n && o->name == n) { ap->keyframes.erase(ap->keyframes.begin() + i); removed = true; }
        break;
    }
    if (removed) W3dActiveCamApply(ActiveSceneAnim, CurrentFrame);   // la pista vuelve a mandar
    else { CameraActive = static_cast<Camera*>(o); W3dCamKey(ActiveSceneAnim, CurrentFrame, o->name); }
    UndoKeyframesConfirm();
    PropertiesLayoutDirty = true; g_redraw = true;
}
static void ActiveCamToggle(){
    // "Juego" no tiene keyframes (ver KeysInGame en ObjectMode.cpp): el corte iba a parar al ultimo clip elegido
    if (ActiveAnimKind == 2) { Notify(T("A game has no keyframes: choose one of its clips in the timeline to animate"), true); return; }
    if (!CameraActive) { Notify(T("There is no active camera"), false); return; }
    UndoKeyframesStart();
    const int est = ActiveCamState();
    AnimProperty* ap = W3dCamTrack(ActiveSceneAnim, false);
    if (est == 2 && ap) {                                     // corte aca y coincide: el click lo SACA (como los demas rombos)
        for (size_t i = 0; i < ap->keyframes.size(); i++)
            if (ap->keyframes[i].frame == CurrentFrame) { ap->keyframes.erase(ap->keyframes.begin() + i); break; }
        W3dActiveCamApply(ActiveSceneAnim, CurrentFrame);   // la pista vuelve a mandar
    } else {
        W3dCamKey(ActiveSceneAnim, CurrentFrame, CameraActive->name);   // guarda el CORTE en el frame actual
    }
    UndoKeyframesConfirm();
    PropertiesLayoutDirty = true; g_redraw = true;
}
static int PropKeyStateHook(int prop, int comp){
    if (ActiveAnimKind == 2) return 0;   // "Juego": los rombos no muestran keyframes (no tiene)
    if (prop == AnimCamActive) return comp == AnimY ? CamCheckState(ActiveObj) : ActiveCamState();
    extern int AnimChannelState(Object*, int, int, int);
    // el FONDO (tarjeta Render): sus curvas son de la COLECCION de la escena, no del objeto elegido
    if (prop == AnimBackground || prop == AnimBackgroundRot || prop == AnimBackgroundTex)
        return SceneCollection ? AnimChannelState(SceneCollection, prop, prop == AnimBackground ? AnimX : comp, CurrentFrame) : 0;
    return ActiveObj ? AnimChannelState(ActiveObj, prop, comp, CurrentFrame) : 0;
}
static void PropKeyToggleHook(int prop, int comp){
    if (prop == AnimCamActive) { if (comp == AnimY) CamCheckToggle(ActiveObj); else ActiveCamToggle(); return; }
    extern void AnimChannelToggle(Object*, int, int, int);
    if (prop == AnimBackground || prop == AnimBackgroundRot || prop == AnimBackgroundTex) {   // el FONDO: en la coleccion de la escena
        if (SceneCollection) { AnimChannelToggle(SceneCollection, prop, comp, CurrentFrame); PropertiesLayoutDirty = true; g_redraw = true; RTInvalidate(); }
        return;
    }
    if (ActiveObj){ AnimChannelToggle(ActiveObj, prop, comp, CurrentFrame);
                    PropertiesLayoutDirty = true; g_redraw = true; }
}

