static void ActionObjAnimEnd(){ int v=(int)(g_objAnimEndF+0.5f); if(v<1)v=1; AnimSetEnd(v); if(CurrentFrame>EndFrame)CurrentFrame=EndFrame; g_redraw=true; }
static void ActionObjAnimFps(){ int v=(int)(g_objAnimFpsF+0.5f); if(v<1)v=1; if(v>120)v=120; AnimSetFps(v); g_objAnimFpsF=(float)v; g_redraw=true; }

