// DROPDOWN de la CAMARA de un Recorte: "(ninguna)" = solo recorta; una camara = los hijos se ven desde ella
static PopupMenu* MenuRcCamera = NULL;
// ---- la BIBLIOTECA DE CLIPS DE JERARQUIA del objeto activo (tarjeta Animacion, pestania Objeto). Todos los
//      objetos que la eligen comparten sus clips (una copia en memoria): cualquier jerarquia con los mismos
//      nombres los reproduce con animObjeto(). ----
static PopupMenu* MenuHierLib = NULL;
static std::vector<std::string> gHierLibMenu;   // id-2 -> nombre de la biblioteca
static void ActionHierPickedLib(int id){
    if (!ActiveObj || ActiveObj == SceneCollection) return;
    const std::string prev = (ActiveObj->clipsHier) ? ActiveObj->clipsHier->animset : std::string();
    if (id == 0 && prev.empty()) return;   // (ya no tenia: nada que deshacer)
    if (id >= 2 && id - 2 < (int)gHierLibMenu.size() && gHierLibMenu[(size_t)(id - 2)] == prev && W3dHierResource(ActiveObj)) return;
    if (id >= 2 && id - 2 >= (int)gHierLibMenu.size()) return;
    // la biblioteca elegida se LEE antes de tocar nada: si su entrada no se puede leer, el objeto sigue con la que
    // tenia (sin paso de undo). Asignarla igual lo dejaba sin biblioteca y con el guardado de TODO el proyecto
    // frenado ("no se pudieron leer al abrir", que ademas no era lo que paso) hasta un Ctrl+Z.
    W3dResource* picked = NULL;
    if (id >= 2) {
        std::string reason;
        picked = W3dHierLibraryTake(gHierLibMenu[(size_t)(id - 2)], ActiveObj->name.c_str(), &reason);
        if (!picked) {
            w3dLogfE("[W3D] clips de '%s': la biblioteca '%s' no se pudo leer: %s", ActiveObj->name.c_str(),
                     gHierLibMenu[(size_t)(id - 2)].c_str(), reason.c_str());
            Notify(std::string(T("The clip library could not be read")) + ": \"" + gHierLibMenu[(size_t)(id - 2)] + "\"", true);
            return;
        }
    }
    // Ctrl+Z: la biblioteca que tenia (el paso la retiene: una nueva que quedo sin usuarios sigue viva)
    W3dClipsViewsSync();
    UndoCaptureHierLibrary(ActiveObj);
    if (id == 0) W3dHierRelease(ActiveObj);
    else if (id == 1) W3dHierNewLibrary(ActiveObj, ActiveObj->name);
    else {
        std::string reason;   // (ya esta en memoria: la toma de ahi)
        if (!W3dHierAssign(ActiveObj, gHierLibMenu[(size_t)(id - 2)], &reason))
            Notify(std::string(T("The clip library could not be read")) + ": \"" + gHierLibMenu[(size_t)(id - 2)] + "\"", true);
    }
    if (picked) W3dResourceRelease(picked, W3DREC_PERMANENT);   // (la referencia de la prueba: ya la tiene el objeto)
    W3dClipsActiveViewCheck();   // (la vista de un clip de la biblioteca que se fue ya no se edita)
    W3dResourcesViewInvalidate();
    PropertiesLayoutDirty = true;
    g_redraw = true;
}
// el desplegable desde afuera (el harness: elige por texto como el click en el menu)
bool PropsHierLibPick(const std::string& text){
    if (!ActiveObj || ActiveObj == SceneCollection) return false;
    if (text == "(none)" || text == T("(none)")) { ActionHierPickedLib(0); return true; }
    if (text == "New Library" || text == T("New Library")) { ActionHierPickedLib(1); return true; }
    gHierLibMenu.clear();
    const std::vector<W3dAnimSetRow>& reg = W3dAnimSetsRegistry();
    for (size_t i = 0; i < reg.size(); i++) gHierLibMenu.push_back(reg[i].name);
    std::vector<W3dResource*> all;
    W3dResourcesList(W3DREC_ANIMSET, all);
    for (size_t i = 0; i < all.size(); i++) {
        if (!all[i] || all[i]->state != W3DREC_READY || !all[i]->data) continue;
        const std::string& n = ((const W3dAnimSet*)all[i]->data)->name;
        if (n.empty() || std::find(gHierLibMenu.begin(), gHierLibMenu.end(), n) != gHierLibMenu.end()) continue;
        gHierLibMenu.push_back(n);
    }
    for (size_t i = 0; i < gHierLibMenu.size(); i++) if (gHierLibMenu[i] == text) { ActionHierPickedLib((int)i + 2); return true; }
    return false;
}

// ---- el RETARGET PROPIO del objeto activo (tarjeta Animacion, pestania Objeto) ----
static PopupMenu* MenuObjRetarget = NULL;
static int OwnRetarget(Object* o){
    if (!o) return -1;
    if (o->getType() == ObjectType::armature) return ((Armature*)o)->retarget;
    return o->clipsHier ? o->clipsHier->retarget : -1;
}
static void ActionPickedObjRetarget(int id){
    Object* o = ActiveObj;
    if (!o || o == SceneCollection) return;
    const bool arm = (o->getType() == ObjectType::armature);
    // ids: 0 = el de cada clip (solo raices de jerarquia), 1 = completo, 2 = rotaciones
    const int mode = (id == 2) ? W3D_RETARGET_ROTATIONS : (id == 1 || arm) ? W3D_RETARGET_COMPLETE : -1;
    if (mode == OwnRetarget(o)) return;
    UndoCaptureRetarget(o);
    if (arm) { W3dArmatureRetarget((Armature*)o, mode); InvalidateSkinScene(); }
    else W3dAnimObjectRetarget(o, mode);
    PropertiesLayoutDirty = true;
    g_redraw = true;
}
static void ActionMenuObjRetarget(){
    if (!PropsActive || !PropsActive->propObjRetarget || !ActiveObj || ActiveObj == SceneCollection) return;
    if (!MenuObjRetarget){ MenuObjRetarget = new PopupMenu(); MenuObjRetarget->action = ActionPickedObjRetarget; }
    MenuObjRetarget->Clear();
    if (ActiveObj->getType() != ObjectType::armature) MenuObjRetarget->Add(T("Clip default"), 0, -1);
    MenuObjRetarget->Add(T("Complete"), 1, -1);
    MenuObjRetarget->Add(T("Rotations only"), 2, -1);
    OpenMenuUnderButton(MenuObjRetarget, PropsActive->propObjRetarget->button);
}
// idem desde afuera (el harness): "Clip default" / "Complete" / "Rotations only"
bool PropsObjRetargetPick(const std::string& text){
    if (text == "Clip default" || text == T("Clip default")) { ActionPickedObjRetarget(0); return true; }
    if (text == "Complete" || text == T("Complete")) { ActionPickedObjRetarget(1); return true; }
    if (text == "Rotations only" || text == T("Rotations only")) { ActionPickedObjRetarget(2); return true; }
    return false;
}
static void ActionMenuHierLib(){
    if (!PropsActive || !PropsActive->propHierLib || !ActiveObj || ActiveObj == SceneCollection) return;
    if (!MenuHierLib){ MenuHierLib = new PopupMenu(); MenuHierLib->action = ActionHierPickedLib; }
    // las del registro del proyecto y las que viven en memoria (todavia sin guardar), sin repetir
    gHierLibMenu.clear();
    const std::vector<W3dAnimSetRow>& reg = W3dAnimSetsRegistry();
    for (size_t i = 0; i < reg.size(); i++) gHierLibMenu.push_back(reg[i].name);
    std::vector<W3dResource*> all;
    W3dResourcesList(W3DREC_ANIMSET, all);
    for (size_t i = 0; i < all.size(); i++) {
        if (!all[i] || all[i]->state != W3DREC_READY || !all[i]->data) continue;
        const std::string& n = ((const W3dAnimSet*)all[i]->data)->name;
        if (n.empty() || std::find(gHierLibMenu.begin(), gHierLibMenu.end(), n) != gHierLibMenu.end()) continue;
        gHierLibMenu.push_back(n);
    }
    MenuHierLib->Clear();
    MenuHierLib->Add(T("(none)"), 0, IconType::empty);
    MenuHierLib->Add(T("New Library"), 1, IconType::plus);
    for (size_t i = 0; i < gHierLibMenu.size(); i++) MenuHierLib->Add(gHierLibMenu[i], (int)i + 2, IconType::animation);
    OpenMenuUnderButton(MenuHierLib, PropsActive->propHierLib->button);
}

