static PopupMenu* MenuClipRetarget = NULL;
static void ActionPickedClipRetarget(int id){
    if (!W3dClipViewLive(ActiveSceneAnim)) return;
    SceneAnimation* v = SceneAnimations[(size_t)ActiveSceneAnim];
    W3dClipHier* c = v->clipHier;
    const int mode = (id == 1) ? W3D_RETARGET_ROTATIONS : W3D_RETARGET_COMPLETE;
    if (c->retarget != mode) {
        W3dClipsViewsSync();
        UndoCaptureClipHier(W3dHierResource(v->owner), c);   // Ctrl+Z: el modo que tenia
        c->retarget = mode; c->version++; v->versionView = c->version;
    }
    g_redraw = true;
}
