    GroupProperties.push_back(propPalette);  // la gestion de paletas del proyecto (pestania 0)
    GroupProperties.push_back(propControl);  // el Control y sus scripts, al final
    for (int i = 0; i < kMaxScriptCards; i++)
        GroupProperties.push_back(propScriptCards[i]);

    // ===== card "Edicion" (ARRIBA de Mesh Parts, pedido del dueno): el interruptor de
    // EDICION de la malla. Una malla "no editable" (escenario) no tiene posRep/edges/
    // bordersBuf ni entra a Edit Mode -> ahorra memoria y carga. El boton alterna:
    // borra los datos de edicion o los recalcula (ComputeBorders).
    // ===== Tarjeta "3D Mesh" (la PRIMERA de la pestania "Malla 3D"): que malla 3D -un RECURSO de la
    // biblioteca- usa el objeto. SOLO se elige (selector + usuarios + Make Single User): el nombre y la
    // carpeta del recurso se editan en la biblioteca del outliner =====
    propMesh3D = new GroupPropertie(T("3D Mesh"));
    propMesh3D->valueWidth = 0.30f;
    propMesh3D->icon = (int)IconType::mesh;
    propBtnMeshSel = new PropButton("", IconType::mesh);
    propBtnMeshSel->button->dropdown = true;
    propBtnMeshSel->action = ActionMenuMeshes3D;
    propMesh3D->properties.push_back(propBtnMeshSel);
    propLblMeshUses = new PropLabel(std::string(T("Users")) + ": 1");
    propMesh3D->properties.push_back(propLblMeshUses);
    propBtnMeshUnique = new PropButton(T("Make Single User"), IconType::mesh);
    propBtnMeshUnique->action = ActionMeshMakeUnique;
    propMesh3D->properties.push_back(propBtnMeshUnique);
    // (una malla de una LIBRERIA externa, o lo que genera un proxy: de solo lectura; se ve solo entonces)
    propLblMeshLib = new PropLabel(T("It belongs to a library (read-only): open the library to edit it"), true /*wrap*/);
    propLblMeshLib->hidden = true;
    propMesh3D->properties.push_back(propLblMeshLib);
    GroupProperties.push_back(propMesh3D);

    propMeshEdit = new GroupPropertie(T("Editing"));
    propBtnMeshEditable = new PropButton(T("Delete editing data"), IconType::trash);
    propBtnMeshEditable->action = ActionMeshEditableToggle;
    propMeshEdit->properties.push_back(propBtnMeshEditable);
    // BLOQUEAR NORMALES: en el Modo Edicion, al confirmar un movimiento no se recalculan las normales de ESTA malla
    // (estaba en el menu del pivote, como opcion global: no tenia nada que ver con el pivote)
    propMeshLockNormals = new PropBool(T("Lock Normals"));
    propMeshEdit->properties.push_back(propMeshLockNormals);
    GroupProperties.push_back(propMeshEdit);

    // ===== Tarjeta "Mesh Parts": selector (lista) + gestion de la PARTE (sin material) =====
    propMeshParts = new GroupPropertie(T("Mesh Parts"));
    propMeshParts->valueWidth = 0.30f;
    { PropListMeshParts* lp = new PropListMeshParts(T("Mesh Parts"));
      // (la fila: el tacho -con mas de una parte-, doble click = renombrar, arrastrar = reordenar, click derecho = menu;
      //  asignar / seleccionar / deseleccionar, solo en Edicion)
      lp->opDelete = ActionDeleteMeshPart; lp->opRename = ActionRenameMeshPart;
      lp->opUpload = ActionMeshPartUp; lp->opLower = ActionMeshPartDown; lp->minItems = 1;
      lp->rowsMax = 3; lp->minRows = 3; lp->buttonsSide = true;   // (3 renglones y, a la derecha, subir / bajar / opciones)
      lp->AddExtra("Assign", ActionAssignMeshPart, (int)IconType::mesh, true);
      lp->AddExtra("Select", ActionSelectMeshPart, (int)IconType::selection, true);
      lp->AddExtra("Deselect", ActionDeselectMeshPart, (int)IconType::selection, true);
      propMeshParts->properties.push_back(lp); } // [0] selector (lo lee Rebind)
    propMeshParts->icon = (int)IconType::mesh;
    PropButton* pbNewPart = new PropButton(T("New Mesh Part"), IconType::plus);
    pbNewPart->action = ActionNewMeshPart;      propMeshParts->properties.push_back(pbNewPart);
    propBtnNewPart = pbNewPart;   // (se oculta con una malla de una libreria)
    // fila: Assign | Select | Deselect (sin icono, 33% c/u, auto-ancho con gap)
    propRowPartOps = new PropButtonRow();
    propRowPartOps->Add(T("Assign"),   ActionAssignMeshPart);
    propRowPartOps->Add(T("Select"),   ActionSelectMeshPart);
    propRowPartOps->Add(T("Deselect"), ActionDeselectMeshPart);
    propMeshParts->properties.push_back(propRowPartOps);
    // fila: Delete | Rename (sin icono, 50% c/u). Delete se oculta si hay 1 sola parte (no borrable).
    propRowDelRow = new PropButtonRow();
    propRowDelRow->Add(T("Delete"), ActionDeleteMeshPart);
    propRowDelRow->Add(T("Rename"), ActionRenameMeshPart); // el boton Rename se vuelve input al apretarlo
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propMeshParts->properties.push_back(propRowDelRow);
#endif

    // fila: Move Up | Move Down (oculta si hay 1 sola parte). El ORDEN del mesh part = ORDEN DE DIBUJADO
    // (dibujar los solidos primero y los transparentes al final).
    propRowPartMove = new PropButtonRow();
    propRowPartMove->Add(T("Move Up"),   ActionMeshPartUp);
    propRowPartMove->Add(T("Move Down"), ActionMeshPartDown);
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propMeshParts->properties.push_back(propRowPartMove);
#endif

    GroupProperties.push_back(propMeshParts);

    // ===== Tarjeta APARTE "Material". Orden: New Material + Rename Material (las opciones
    // del material), LINEA separadora, y abajo la textura + sus opciones. Los props se guardan en arrays
    // (propMatChk) -> Rebind los setea por nombre, NO por indice (reordenar = libre).
    // ===== Tarjeta "Resource" (pestania "Malla 3D", la 3): el recurso elegido en la BIBLIOTECA del outliner.
    // Va ANTES de la tarjeta Material: con un material elegido, la de abajo es su tarjeta Material.
    propResource = new GroupPropertie(T("Resource"));
    propResource->valueWidth = 0.56f;   // (los datos van en cajas: la columna del valor ancha; las etiquetas -Triangulos- enteras)
    propResource->icon = (int)IconType::folder;
    // LA VISTA PREVIA arriba de todo (una textura), debajo del titulo
    propRecPreview = new PropImage(T("Preview"));
    propResource->properties.push_back(propRecPreview);
    propRecName = new PropText(T("Name"));
    propResource->properties.push_back(propRecName);
    propRecFolder = new PropText(T("Folder"));
    propResource->properties.push_back(propRecFolder);
    propRecType = NULL;   // (antes una linea con todo junto: ahora cada dato en su caja)
    // USUARIOS (0 en rojo: nadie lo usa), TIPO y GUARDADO: cajas de solo lectura como las de un valor
    propRecUsers = new PropText(T("Users"));
    propRecUsers->field.readOnly = true;
    propResource->properties.push_back(propRecUsers);
    propRecBoxType = new PropText(T("Type"));
    propRecBoxType->field.readOnly = true;
    propResource->properties.push_back(propRecBoxType);
    propRecSaved = new PropText(T("Saved"));
    propRecSaved->field.readOnly = true;
    propResource->properties.push_back(propRecSaved);
    // (con cambios sin guardar: en el lugar de la caja, el boton Guardar)
    propRecSave = new PropButton(T("Saved"), IconType::save);
    propRecSave->withLabel = true;
    propRecSave->inColumn = true;
    propRecSave->button->text = T("Save");
    propRecSave->action = ActionRecSave;
    propRecSave->hidden = true;
    propResource->properties.push_back(propRecSave);
    // DONDE VIVE (solo los que tienen archivo propio: texturas, sonidos, scripts...): un desplegable con donde esta y lo
    // que se puede hacer: "Extraer..." (de adentro del .w3d a un archivo de afuera) o "Importar..." (al reves)
    propRecLocation = new PropButton(T("Storage"), IconType::archive);
    propRecLocation->withLabel = true;
    propRecLocation->inColumn = true;
    propRecLocation->button->text = T("Inside the .w3d");
    propRecLocation->button->dropdown = true;
    propRecLocation->action = ActionMenuRecLocation;
    propRecLocation->hidden = true;
    propResource->properties.push_back(propRecLocation);
    // LA ENTRADA y LOS DATOS POR TIPO: cada uno una caja como las de un valor (de solo lectura: se puede seleccionar y
    // copiar). Una fila cada uno; las que sobran se ocultan
    propRecEntry = new PropText(T("Entry"));
    propRecEntry->field.readOnly = true;
    propRecEntry->hidden = true;
    propResource->properties.push_back(propRecEntry);
    for (int k = 0; k < 14; k++) {
        PropText* l = new PropText("");
        l->field.readOnly = true;
        l->hidden = true;
        propRecData.push_back(l);
        propResource->properties.push_back(l);
    }
    // (MALLA 3D) en que formato se guarda: tildado = texto (.w3dm, legible: diffs), destildado = binario (.w3db, el
    // default: abrir es leer y copiar). Antes era una opcion de todo el proyecto en la tarjeta Archivo
    propRecMeshText = new PropBool(T("Mesh as text"));
    propRecMeshText->value = NULL;   // (un PropBool sin valor no ocupa fila: se le da al elegir una malla)
    propRecMeshText->onChange = ActionRecMeshText;
    propResource->properties.push_back(propRecMeshText);
    // GUARDAR COMO: una COPIA de su archivo afuera, eligiendo carpeta y nombre. El recurso sigue donde estaba
    propRecSaveAs = new PropButton(T("Save As..."), IconType::save);
    propRecSaveAs->action = ActionRecSaveAs;
    propRecSaveAs->hidden = true;
    propResource->properties.push_back(propRecSaveAs);
    propRecExtract = NULL;   // (era una copia afuera: lo mismo que Guardar como)
    // lo del tipo: escuchar/parar un sonido, abrir una escena/prefab, abrir un script en el IDE
    propRecActions2 = new PropButtonRow();
    propRecActions2->Add(T("Play"), ActionRecActionType);
    propRecActions2->Add(T("Stop"), ActionRecStop);
    propResource->properties.push_back(propRecActions2);
    // abajo de todo: SELECCIONAR USUARIOS (el icono de los usuarios) y BORRAR (el tacho), una fila cada uno
    propRecActions = NULL;
    propRecSelUsers = new PropButton(T("Select Users"), IconType::users);
    propRecSelUsers->action = ActionRecSelectUsers;
    propResource->properties.push_back(propRecSelUsers);
    propRecDelete = new PropButton(T("Delete"), IconType::trash);
    propRecDelete->action = ActionRecDelete;
    propResource->properties.push_back(propRecDelete);
    propResource->visible = false;
    GroupProperties.push_back(propResource);

    propMaterial = new GroupPropertie(T("Material"));
    propMaterial->icon = (int)IconType::material;   // (el icono a la izquierda del titulo)
    propMaterial->valueWidth = 0.30f;
    // LAS CAPAS DE MATERIAL del mesh part: una lista con el material ADENTRO (la capa 1 arranca en el por defecto y
    // siempre queda una). Cada fila: doble click = renombrar el material, la FLECHA = cambiarlo por otro, el TACHO =
    // borrar la capa. A la derecha subir / bajar / opciones. Abajo "Nuevo material". Lo de mas abajo en la tarjeta
    // edita el material de la capa elegida
    propListLayersMat = new PropListMeshParts(T("Material")); propListLayersMat->mode = 18;
    propListLayersMat->rowsMax  = 3; propListLayersMat->minRows = 3; propListLayersMat->buttonsSide = true;
    propListLayersMat->minItems = 1;
    propListLayersMat->opDelete = ActionLayerMatDelete; propListLayersMat->opRename = ActionRenameMaterial;
    propListLayersMat->opUpload = ActionLayerMatUpload; propListLayersMat->opLower = ActionLayerMatLower;
    propListLayersMat->opChange = ActionChangeMaterialLayer;
    propMaterial->properties.push_back(propListLayersMat);
    propLayerMatAdd = new PropButton(T("New Material"), IconType::plus);
    propLayerMatAdd->action = ActionLayerNewMat;
    propMaterial->properties.push_back(propLayerMatAdd);
    propLayerMatChange = new PropButton(T("Change Material"), IconType::material);   // (el de la capa elegida)
    propLayerMatChange->button->dropdown = true;
    propLayerMatChange->action = ActionButtonChangeMaterial;
    propMaterial->properties.push_back(propLayerMatChange);
    propBtnRenameMat = new PropButton(T("Rename Material"), -1); // ANTES de la textura, SIN icono
    propBtnRenameMat->action = ActionRenameMaterial; // se vuelve input al apretarlo; oculto si es el default
#ifdef W3D_SYMBIAN
    // (el selector viejo ya NO va: mostraba "Material por defecto" y hacia lo mismo que "Cambiar material", que con
    // el teclado tambien se abre con OK. Queda solo para refrescar su texto)
    propMaterial->properties.push_back(propBtnRenameMat);
#endif
    // aviso cuando el mesh part usa el material POR DEFECTO (oculto si tiene uno propio). 1 label WRAP: se
    // adapta al ancho (salto de linea en los espacios) -> se lee entero aunque se achique el panel.
    propMsgDefault = new PropLabel(T("The default material can not be edited. Create a new material."), true /*wrap*/);
    propMaterial->properties.push_back(propMsgDefault);
    // LINEA: separa las opciones del material (arriba) de la textura + sus opciones (abajo). Se OCULTA con el
    // material por defecto (sino queda una linea huerfana molesta debajo del aviso).
    propSepMat = new PropSeparator();
    propMaterial->properties.push_back(propSepMat);
    // LOS MAPAS DEL MATERIAL, uno por fila: [nombre corto] [el valor: la textura, el color o el numero] [numero /
    // textura] [la capa UV]. Los botones chicos van a la DERECHA y la UV en el mismo lugar en todas (alineadas). Orden:
    // Color, Metalico, Rugosidad, Emision, Normal, Alfa (+ su recorte) e IOR. De estos valores el motor arma lo que
    // cada backend puede dibujar (el brillo de GL sale de la rugosidad y el metalico; ver Mesh::ApplyMaterial)
    propBtnTexture = new PropButton(T("Color"));
    propBtnTexture->withLabel = true;
    propBtnTexture->button->dropdown = true;
    // el COLOR base va en el lugar de la derecha que en las otras filas es el de numero / textura (la textura usa todo
    // el ancho que queda)
    propBtnTexture->AddExtra(-1, ActionColorBase, "Base Color");
    propBtnTexture->AddExtra(IconType::mesh, ActionMapUV0, "UV Map");
    propBtnTexture->action = ActionMenuTextures;
    propBtnNormalTex = new PropButton(T("Normal"));
    propBtnNormalTex->withLabel = true;
    propBtnNormalTex->button->dropdown = true;
    propBtnNormalTex->AddExtra(IconType::mesh, ActionMapUV1, "UV Map");
    propBtnNormalTex->action = ActionMenuTexturesNormal;
    {
        static const char* const kName[W3D_MAPS] = { "", "", "Emission", "Roughness", "Metallic", "Alpha" };
        void (*kPri[W3D_MAPS])() = { 0, 0, ActionMainMap2, ActionMainMap3, ActionMainMap4, ActionMainMap5 };
        void (*kMod[W3D_MAPS])() = { 0, 0, ActionMapMode2, ActionMapMode3, ActionMapMode4, ActionMapMode5 };
        void (*kUV[W3D_MAPS])() = { 0, 0, ActionMapUV2, ActionMapUV3, ActionMapUV4, ActionMapUV5 };
        propMap[0] = propMap[1] = NULL;
        for (int k = W3D_MAP_EMISSION; k < W3D_MAPS; k++) {
            PropButton* b = new PropButton(T(kName[k]));
            b->withLabel = true;
            b->button->dropdown = true;
            b->AddExtra(IconType::number, kMod[k], "Number / Texture");
            b->AddExtra(IconType::mesh, kUV[k], "UV Map");
            b->action = kPri[k];
            b->hidden = true;
            propMap[k] = b;
        }
        for (int k = W3D_MAPS; k < 8; k++) propMap[k] = NULL;
        // la columna del NOMBRE igual en todas (las filas quedan alineadas) y los dos lugares de la derecha reservados
        PropButton* rows[6] = { propBtnTexture, propMap[W3D_MAP_METALLIC], propMap[W3D_MAP_ROUGHNESS],
                                 propMap[W3D_MAP_EMISSION], propBtnNormalTex, propMap[W3D_MAP_ALPHA] };
        int length = 0;
        for (int f = 0; f < 6; f++) {
            int c = 0; const std::string& n = rows[f]->name;
            for (size_t q = 0; q < n.size(); q++) if (((unsigned char)n[q] & 0xC0) != 0x80) c++;
            if (c > length) length = c;
        }
        for (int f = 0; f < 6; f++) { rows[f]->labelChars = length; rows[f]->slotsExtras = 2; propMaterial->properties.push_back(rows[f]); }
        propMatIOR = new PropFloat(T("IOR")); propMatIOR->SetRange(1.0f, 3.0f);
        propMatIOR->fineStep = 0.01f; propMatIOR->thickStep = 0.1f; propMatIOR->dragStep = 0.01f;
        propMatIOR->onChange = ActionRTValues;
        // TRANSMISION: cuanto de la superficie es vidrio (la luz pasa doblada por el IOR); va arriba del IOR
        propMatTrans = new PropFloat(T("Transmission")); propMatTrans->SetRange(0.0f, 1.0f);
        propMatTrans->fineStep = 0.05f; propMatTrans->thickStep = 0.1f; propMatTrans->dragStep = 0.01f;
        propMatTrans->onChange = ActionMatTransmission;
        propMaterial->properties.push_back(propMatTrans);
        propMaterial->properties.push_back(propMatIOR);
        // REFLEJOS EN PANTALLA: lo dibujado se refleja (segun la rugosidad, el metalico y el angulo). Con shaders
        propMatSSR = new PropBool(T("Screen Space Reflections"));
        propMatSSR->onChange = ActionRTValues;
        propMaterial->properties.push_back(propMatSSR);
    }
    // Se CONSTRUYE todo primero (el bind es por member, no importa el orden de construccion); el PUSH define el
    // orden VISUAL, que se reorganizo: Lighting arriba de todo, Vertex Color sobre Base Color, y los
    // "pro" (Culling / Depth Test) abajo de todo.
    // [8]="Reflection"; [9] SIN uso (lo reemplaza el dropdown de modo -> oculto en Rebind); [10]="Normal Mapping".
    const char* namesChk[11] = { "Filtering","Transparent","Vertex Color","Lighting","Repeat","Culling","Depth Test","Smooth Shading","Reflection","(reflect mode)","Normal Mapping" };
    for (int i = 0; i < 11; i++) {
        propMatChk[i] = new PropBool(T(namesChk[i]));
        // onChange = re-Rebind: togglear CUALQUIER checkbox re-arma la tarjeta -> aparecen/desaparecen al instante los
        // que dependen de otro (Base Color si Vertex Color; Shininess/Emission/Specular si Lighting; etc).
        propMatChk[i]->onChange = RebindMaterialMeshPart;
    }
    propBtnShading = new PropButton(T("Shading"));   // [Sombreado] [Por vertice / Por pixel]
    propBtnShading->withLabel = true;
    propBtnShading->button->dropdown = true;
    propBtnShading->action = ActionMenuShading;
    propBtnReflectMode = new PropButton(T("Matcap (hardware)"), IconType::material);
    propBtnReflectMode->button->dropdown = true;
    propBtnReflectMode->action = ActionMenuReflectMode;
    // --- calcomanias / mezcla / profundidad (ver el bloque de arriba) ---
    propBtnMix = new PropButton(T("Alpha (normal)"), IconType::material);
    propBtnMix->button->dropdown = true;
    propBtnMix->action = ActionMenuMix;
    propBtnDepth = new PropButton(T("Test"));   // [Test] [Test + escritura (opaco) / ... / Apagado]
    propBtnDepth->withLabel = true;
    propBtnDepth->button->dropdown = true;
    propBtnDepth->action = ActionMenuDepth;
    propMatBias = new PropFloat(T("Depth Bias"));
    propMatBias->SetRange(-64.0f, 64.0f);
    propMatBias->fineStep = 1.0f; propMatBias->thickStep = 4.0f; propMatBias->dragStep = 0.5f;
    propMatBias->onChange = OnMatBiasChange;
    // el sesgo de profundidad en METROS (pesa lo mismo cerca y lejos): + aleja la malla para el z-buffer, - la acerca
    propMatBiasM = new PropFloat(T("Depth Bias (m)"));
    propMatBiasM->SetRange(-2.0f, 2.0f);
    propMatBiasM->fineStep = 0.01f; propMatBiasM->thickStep = 0.05f; propMatBiasM->dragStep = 0.005f;
    propMatBiasM->onChange = OnMatBiasMChange;
    propMatOrder = new PropButton(T("Pass"));   // (desplegable: pase de opacos / calcomanias / transparentes)
    propMatOrder->withLabel = true;
    propMatOrder->button->dropdown = true;
    propMatOrder->action = ActionMenuPass;
    // --- LINEAS: aristas de la malla con este material + grosor en px ---
    propMatLines = new PropBool(T("Lines"));
    propMatLines->onChange = OnMatLinesChange;
    propMatThicknessLine = new PropFloat(T("Line Width"));
    propMatThicknessLine->SetRange(1.0f, 64.0f);
    propMatThicknessLine->fineStep = 1.0f; propMatThicknessLine->thickStep = 2.0f; propMatThicknessLine->dragStep = 0.5f;
    propMatThicknessLine->onChange = OnMatThicknessLineChange;
    // --- ALPHA TEST: recorte por alfa 0..1 (0 = apagado), ver OnMatAlphaChange ---
    propMatAlpha = new PropFloat(T("Alpha Test"));
    propMatAlpha->SetRange(0.0f, 1.0f);
    propMatAlpha->fineStep = 0.05f; propMatAlpha->thickStep = 0.1f; propMatAlpha->dragStep = 0.005f;
    propMatAlpha->onChange = OnMatAlphaChange;
    { std::vector<PropertieBase*>& v = propMaterial->properties;   // (debajo de la fila Alfa)
      for (size_t q = 0; q < v.size(); q++) if (v[q] == propMap[W3D_MAP_ALPHA]) { v.insert(v.begin() + (long)q + 1, propMatAlpha); break; } }
    // --- MEZCLA DE TEXTURAS (una pasada, multitextura): la textura B y cuanto de ella (0 = solo la base), ver
    //     Material::textureB / mixB. La fila del numero apunta DIRECTO al campo, como Alpha Test (mismo undo) ---
    propBtnTexB = new PropButton(T("No Texture B"), IconType::texture);
    propBtnTexB->button->dropdown = true;
    propBtnTexB->action = ActionMenuTexturesB;
    propMatMixB = new PropFloat(T("Texture mix"));
    propMatMixB->SetRange(0.0f, 1.0f);
    propMatMixB->fineStep = 0.05f; propMatMixB->thickStep = 0.1f; propMatMixB->dragStep = 0.005f;
    propMatMixB->onChange = OnMatAlphaChange;   // (redibujar: el valor ya esta en el material)
    // --- ORDEN VISUAL ---
    propMaterial->properties.push_back(propMatChk[3]);  // Lighting  (ARRIBA DE TODO)
    propMaterial->properties.push_back(propBtnShading); // por vertice / por pixel (solo con shaders y Lighting ON)
    // LUZ INDIRECTA POR VERTICE (Material::lightIndirect): con una sonda de luz, en el pipeline fijo (el N95) la CPU calcula
    // la luz de cada vertice. Con la luz por pixel no hace falta (la sonda ya entra)
    propMatLightInd = new PropBool(T("Indirect light"));
    propMatLightInd->onChange = RebindMaterialMeshPart;
    propMaterial->properties.push_back(propMatLightInd);
    // SHADER ESCRITO (al FINAL de la tarjeta: es lo avanzado): el tilde; con el, el archivo (su boton chico lo abre en el
    // IDE), "Compile" y lo que dijo el compilador
    propMatShaderOn = new PropBool(T("Advanced: custom shader"));
    propMatShaderOn->onChange = OnMatShaderOn;
    propBtnShader = new PropButton(T("Shader"));
    propBtnShader->withLabel = true;
    propBtnShader->button->dropdown = true;
    propBtnShader->action = ActionMenuShader;
    propBtnShader->AddExtra(IconType::script, ActionShaderEdit, "Edit in the IDE");   // (el lapiz: al IDE)
    propBtnShaderComp = new PropButton(T("Compile"), IconType::notifOk);
    propBtnShaderComp->action = ActionShaderCompile;
    propMatShaderMsg = new PropLabel("", true /*wrap*/);
    propMaterial->properties.push_back(propMatChk[2]);  // Vertex Color (sobre Base Color)
    propMaterial->properties.push_back(propMatChk[0]);  // Filtering
    propMaterial->properties.push_back(propMatChk[4]);  // Repeat
    // (el NORMAL MAP va debajo del color base: ver arriba)
    propMaterial->properties.push_back(propMatChk[8]);  // Reflection
    propMaterial->properties.push_back(propMatChk[9]);  // (oculto: reemplazado por el dropdown)
    propMaterial->properties.push_back(propBtnReflectMode);
    propMaterial->properties.push_back(propBtnMix);  // modo de mezcla (visible si Transparent ON)
    propMaterial->properties.push_back(propBtnTexB); // Texture B (mezcla de texturas en una pasada)
    propMaterial->properties.push_back(propMatMixB); // Texture mix (cuanto de B; visible con una textura B)
    // (LINEAS, CULLING y lo de la PROFUNDIDAD -test, los dos sesgos, el orden de pase- arriba de las capas de textura)
    propMaterial->properties.push_back(propMatLines);         // Lines (aristas por material)
    propMaterial->properties.push_back(propMatThicknessLine); // Line Width (visible con Lines ON)
    propMaterial->properties.push_back(propMatChk[5]);  // Culling
    propMaterial->properties.push_back(propBtnDepth); // Depth Test/Write (desplegable)
    propMaterial->properties.push_back(propMatBias);  // Depth Bias
    propMaterial->properties.push_back(propMatBiasM); // Depth Bias (m) (se armaba y se enlazaba, pero nunca entro a la tarjeta)
    // (el sesgo EN METROS ya no esta en la tarjeta: un solo sesgo, el del z-buffer. Un proyecto que lo traia lo sigue
    //  aplicando: Material::bias_meters se lee y se guarda igual)
    propMaterial->properties.push_back(propMatOrder);       // el pase (opacos / calcomanias / transparentes)
    // --- CAPAS DE TEXTURA: titulo + hasta 4 filas [textura | UV | mezcla | on] (ver el bloque de arriba) ---
    propLayersTitle = new PropLabel(T("Texture Layers"));
    propMaterial->properties.push_back(propLayersTitle);
    // (la lista: una fila por capa, con su tacho; se arrastran para reordenar. Abajo, "Add Layer" y lo de la elegida)
    propListLayers = new PropListMeshParts(T("Texture Layers")); propListLayers->mode = 17;
    propListLayers->rowsMax = 3; propListLayers->minRows = 3; propListLayers->showEmpty = true;   // (3 renglones, siempre)
    propListLayers->buttonsSide = true;                                                                // subir / bajar / opciones
    propListLayers->opDelete = ActionLayerDelete; propListLayers->opUpload = ActionLayerUpload; propListLayers->opLower = ActionLayerLower;
    propMaterial->properties.push_back(propListLayers);
    propLayerAdd = new PropButton(T("Add Layer"), IconType::plus);
    propLayerAdd->button->dropdown = true;
    propLayerAdd->action = ActionLayerAdd;
    propMaterial->properties.push_back(propLayerAdd);
    for (int i = 0; i < kLayersUI; i++) {
        propLayerTex[i] = new PropButton(T("Texture"), IconType::texture);
        propLayerTex[i]->withLabel = true;
        propLayerTex[i]->button->dropdown = true;
        propLayerTex[i]->action = kActionLayerTex[i];
        propLayerUV[i] = new PropButton("UV 1", IconType::material);
        propLayerUV[i]->withLabel = true;
        propLayerUV[i]->button->dropdown = true;
        propLayerUV[i]->action = kActionLayerUV[i];
        propLayerMix[i] = new PropButton(T("Mix"), IconType::material);
        propLayerMix[i]->withLabel = true;
        propLayerMix[i]->button->dropdown = true;
        propLayerMix[i]->action = kActionLayerMz[i];
        propLayerForce[i] = new PropFloat(T("Factor"), "%");   // (el % de la capa: TexLayer::fuerza va de 0 a 1)
        propLayerForce[i]->SetRange(0.0f, 100.0f);
        propLayerForce[i]->integer = true;   // ("50%", no "50.0000%")
        propLayerForce[i]->fineStep = 1.0f; propLayerForce[i]->thickStep = 10.0f; propLayerForce[i]->dragStep = 0.5f;
        propLayerForce[i]->onChange = OnLayerForce;
        propLayerOn[i] = new PropBool(T("Layer On"));
        propLayerOn[i]->onChange = RebindMaterialMeshPart;
        propMaterial->properties.push_back(propLayerTex[i]);
        propMaterial->properties.push_back(propLayerUV[i]);
        propMaterial->properties.push_back(propLayerMix[i]);
        propMaterial->properties.push_back(propLayerForce[i]);
        propMaterial->properties.push_back(propLayerOn[i]);
    }
    // (Lineas, Culling, la profundidad, los sesgos y el orden de pase van arriba de las capas de textura: ver mas arriba)
    // el viejo checkbox "Depth Test" queda OCULTO: lo reemplaza el desplegable de arriba,
    // que ademas expone la escritura de z (la mitad que faltaba).
    propMaterial->properties.push_back(propMatChk[6]);
    propMaterial->properties.push_back(propMatShaderOn);    // Avanzado: shader personalizado (ABAJO DE TODO)
    propMaterial->properties.push_back(propBtnShader);
    propMaterial->properties.push_back(propBtnShaderComp);
    propMaterial->properties.push_back(propMatShaderMsg);
    GroupProperties.push_back(propMaterial);
    PropsBakeBuild(this);   // PRECALCULAR LA ILUMINACION, debajo de la tarjeta Material (PropsBake.cpp)

    // pestania de LUZ: TODAS las propiedades editables de la luz de OpenGL. Se ve solo si el
    // objeto activo es una luz. OpenGL = UN tipo de luz configurable: Direccional / Puntual / Spot (ver Light.h).
    propLight = new GroupPropertie(T("Light"));
    propLight->reserveKeyBtn = true;   // columna del rombo (el color diffuse es animable)
    // "Ignorar orden" (del arbol): prendido (default) la luz alumbra TODO; apagado solo lo que sigue en el arbol
    propLightIgnOrder = new PropBool(T("Ignore order"));
    propLight->properties.push_back(propLightIgnOrder);
    // EL TIPO: Punto (alumbra para todos lados), Sol (direccional: rayos paralelos) o Foco (un cono)
    propLightType = new PropButton(T("Type"));
    propLightType->withLabel = true;
    propLightType->button->dropdown = true;
    propLightType->action = ActionMenuLightType;
    // animable (escalon): el rombo guarda si es un Sol (direccional) o no
    propLightType->animProp = AnimLightMisc; propLightType->animComp = AnimY;
    propLight->properties.push_back(propLightType);
    propLightGL = new PropFloat(T("GL Light"));                    // numero de GL light (0..7), entero editable
    propLightGL->SetRange(0.0f, 7.0f); propLightGL->integer = true;
    propLightGL->fineStep = 1.0f; propLightGL->thickStep = 1.0f; propLightGL->dragStep = 1.0f;
    propLightGL->onChange = OnLightGLChange;
    propLightGL->animProp = AnimLightMisc; propLightGL->animComp = AnimX;     // animable (escalon)
    propLight->properties.push_back(propLightGL);
    propLightDiffuse = new PropColor(T("Diffuse"));  propLight->properties.push_back(propLightDiffuse);
    // la INTENSIDAD (el color queda en 0..1; esto la hace mas fuerte). Animable
    propLightIntens = new PropFloat(T("Intensity")); propLightIntens->SetRange(0.0f, 1000.0f);
    propLightIntens->fineStep = 0.1f; propLightIntens->thickStep = 1.0f; propLightIntens->dragStep = 0.02f;
    propLightIntens->animProp = AnimLightIntens; propLightIntens->animComp = AnimX;
    propLightIntens->onChange = ActionRTValues;
    propLight->properties.push_back(propLightIntens);
    propLightDiffuse->animProp = AnimColor; propLightDiffuse->animComp = AnimX; // rombo -> anima el color (RGB)
    propLightAmbient = new PropColor(T("Ambient"));  propLight->properties.push_back(propLightAmbient);
    propLightAmbient->animProp = AnimAmbient; propLightAmbient->animComp = AnimX;
    propLightSpecular = new PropColor(T("Specular")); propLight->properties.push_back(propLightSpecular);
    propLightSpecular->animProp = AnimSpecular; propLightSpecular->animComp = AnimX;
    // atenuacion 1/(C + L*d + Q*d^2) (afecta a la puntual/spot)
    propLightAttC = new PropFloat(T("Att Constant")); propLightAttC->SetRange(0.0f, 5.0f);
    propLightAttC->fineStep = 0.02f; propLightAttC->thickStep = 0.1f; propLightAttC->dragStep = 0.01f;
    propLightAttC->animProp = AnimAtten; propLightAttC->animComp = AnimX;
    propLight->properties.push_back(propLightAttC);
    propLightAttL = new PropFloat(T("Att Linear")); propLightAttL->SetRange(0.0f, 2.0f);
    propLightAttL->fineStep = 0.01f; propLightAttL->thickStep = 0.05f; propLightAttL->dragStep = 0.005f;
    propLightAttL->animProp = AnimAtten; propLightAttL->animComp = AnimY;
    propLight->properties.push_back(propLightAttL);
    propLightAttQ = new PropFloat(T("Att Quadratic")); propLightAttQ->SetRange(0.0f, 1.0f);
    propLightAttQ->fineStep = 0.005f; propLightAttQ->thickStep = 0.02f; propLightAttQ->dragStep = 0.002f;
    propLightAttQ->animProp = AnimAtten; propLightAttQ->animComp = AnimZ;
    propLight->properties.push_back(propLightAttQ);
    // spotlight: cono (grados) + concentracion del haz
    propLightSpotCut = new PropFloat(T("Spot Cutoff")); propLightSpotCut->SetRange(1.0f, 180.0f); propLightSpotCut->integer = true;
    propLightSpotCut->fineStep = 1.0f; propLightSpotCut->thickStep = 5.0f; propLightSpotCut->dragStep = 1.0f;
    propLightSpotCut->animProp = AnimSpot; propLightSpotCut->animComp = AnimX;
    propLight->properties.push_back(propLightSpotCut);
    propLightSpotExp = new PropFloat(T("Spot Exponent")); propLightSpotExp->SetRange(0.0f, 128.0f); propLightSpotExp->integer = true;
    propLightSpotExp->fineStep = 1.0f; propLightSpotExp->thickStep = 8.0f; propLightSpotExp->dragStep = 1.0f;
    propLightSpotExp->animProp = AnimSpot; propLightSpotExp->animComp = AnimY;
    propLight->properties.push_back(propLightSpotExp);
    // DISTANCIA (m): hasta donde alumbra la puntual/foco = el largo del cono. 0 = sin limite
    propLightDist = new PropFloat(T("Distance"), "m"); propLightDist->SetRange(0.0f, 1000.0f);
    propLightDist->fineStep = 0.1f; propLightDist->thickStep = 1.0f; propLightDist->dragStep = 0.05f;
    propLightDist->onChange = ActionRTValues;
    propLight->properties.push_back(propLightDist);
    // TRAZADO DE RAYOS: tamano de la lampara (0 = puntual -> sombra dura; mas = penumbra) y rayos de sombra (0 = global)
    propLightRTRadius = new PropFloat(T("Radius")); propLightRTRadius->SetRange(0.0f, 100.0f);
    propLightRTRadius->fineStep = 0.05f; propLightRTRadius->thickStep = 0.5f; propLightRTRadius->dragStep = 0.02f;
    propLightRTRadius->onChange = ActionRTValues;
    propLight->properties.push_back(propLightRTRadius);
    propLightRTRays = new PropFloat(T("Rays")); propLightRTRays->SetRange(0.0f, 256.0f); propLightRTRays->integer = true;
    propLightRTRays->fineStep = 1.0f; propLightRTRays->thickStep = 4.0f; propLightRTRays->dragStep = 1.0f;
    propLightRTRays->onChange = ActionRTValues;
    propLight->properties.push_back(propLightRTRays);
    GroupProperties.push_back(propLight);

    // pestania de CAMARA: lente (ortografica/perspectiva + fov) + target (look-at)
    propCamera = new GroupPropertie(T("Camera"));
    propCamera->reserveKeyBtn = true;   // columna del rombo de keyframe (el fov es animable)
    // CAMARA ACTIVA (animable: el rombo keya el corte de la pista "Camara activa" con ESTA camara; animComp = AnimY dice
    // "esta camara", la tarjeta de la animacion usa AnimX = "la activa")
    propActiveCamChk = new PropBool(T("Active camera"));
    propActiveCamChk->value = &g_camIsActive;
    propActiveCamChk->onChange = ActionActiveCamChk;
    propActiveCamChk->animProp = AnimCamActive; propActiveCamChk->animComp = AnimY;
    propCamera->properties.push_back(propActiveCamChk);
    propCamOrtho = new PropBool(T("Orthographic"));
    propCamera->properties.push_back(propCamOrtho);
    propCamFov = new PropFloat(T("FOV"));
    propCamFov->SetRange(1.0f, 179.0f); propCamFov->integer = false;
    propCamFov->fineStep = 0.5f; propCamFov->thickStep = 5.0f; propCamFov->dragStep = 0.5f;
    propCamFov->animProp = AnimFov; propCamFov->animComp = AnimX;   // rombo de keyframe -> anima el FOV
    propCamera->properties.push_back(propCamFov);
    // distancia MINIMA / MAXIMA de dibujado (near/far), animables (canal AnimClip)
    propCamNear = new PropFloat(T("Near"));
    propCamNear->SetRange(0.001f, 100.0f); propCamNear->fineStep = 0.01f; propCamNear->thickStep = 0.1f; propCamNear->dragStep = 0.005f;
    propCamNear->animProp = AnimClip; propCamNear->animComp = AnimX;
    propCamera->properties.push_back(propCamNear);
    propCamFar = new PropFloat(T("Far"));
    propCamFar->SetRange(1.0f, 100000.0f); propCamFar->fineStep = 5.0f; propCamFar->thickStep = 50.0f; propCamFar->dragStep = 2.0f;
    propCamFar->animProp = AnimClip; propCamFar->animComp = AnimY;
    propCamera->properties.push_back(propCamFar);
    // PROFUNDIDAD DE CAMPO: la hace el trazado de rayos (desde la lente); el desenfoque de campo del postprocesado
    // puede usar el mismo foco. La linea y la cruz del gizmo marcan donde esta enfocado
    propCamDof = new PropBool(T("Depth of field")); propCamDof->onChange = ActionCamDofOn;
    propCamera->properties.push_back(propCamDof);
    propCamFStop = new PropFloat(T("F-stop")); propCamFStop->SetRange(0.1f, 64.0f);   // (como el .w3d: hasta f/0.1)
    propCamFStop->fineStep = 0.1f; propCamFStop->thickStep = 1.0f; propCamFStop->dragStep = 0.05f; propCamFStop->onChange = ActionCamDof;
    propCamera->properties.push_back(propCamFStop);
    propCamFocus = new PropFloat(T("Focus distance"), "m"); propCamFocus->SetRange(0.01f, 10000.0f);
    propCamFocus->fineStep = 0.1f; propCamFocus->thickStep = 1.0f; propCamFocus->dragStep = 0.05f; propCamFocus->onChange = ActionCamDof;
    propCamFocus->animProp = AnimCamFocus; propCamFocus->animComp = AnimX;   // rombo de keyframe -> anima el foco
    propCamera->properties.push_back(propCamFocus);
    propBtnCamFocusObj = new PropButton(T("Focus object"), IconType::object);
    propBtnCamFocusObj->withLabel = true;
    propBtnCamFocusObj->button->dropdown = true;
    propBtnCamFocusObj->action = ActionMenuFocusObj;
    propCamera->properties.push_back(propBtnCamFocusObj);
    propBtnCamTarget = new PropButton(T("Target"), IconType::object);
    propBtnCamTarget->button->dropdown = true;
    propBtnCamTarget->action = ActionMenuTarget;
    propCamera->properties.push_back(propBtnCamTarget);
    GroupProperties.push_back(propCamera);

    // pestania de los objetos especiales (Duplicate Linked / Array / Mirror):
    // el objeto al que apuntan (target)
    propInstance = new GroupPropertie(T("Linked"));
    propBtnInstTarget = new PropButton(T("Target"), IconType::object);
    propBtnInstTarget->button->dropdown = true;
    propBtnInstTarget->action = ActionMenuTarget;
    propInstance->properties.push_back(propBtnInstTarget);
    // las COPIAS de un Array (una instancia comun es un Array de 1). Se sincroniza por frame: SyncInstCopies
    propInstCopies = new PropFloat(T("Count"));
    propInstCopies->SetRange(1.0f, 1000.0f); propInstCopies->integer = true;
    propInstance->properties.push_back(propInstCopies);
    GroupProperties.push_back(propInstance);

    // pestania del objeto LOD: los umbrales de distancia, como texto "20, 45, 90"
    // (umbral i = hasta donde llega el hijo i; mas alla del ultimo, el ultimo hijo).
    // El commit lo hace SyncLodDist por frame (patron del texto 2D).
    propLOD = new GroupPropertie(T("LOD"));
    propLOD->valueWidth = 0.62f;   // columna de valor ancha (la lista de numeros)
    propLodDist = new PropText(T("Distances"), "");
    propLOD->properties.push_back(propLodDist);
    // MISMO flag que el Culling: sin el, LOD y Culling previsualizan con camaras
    // distintas (el LOD leia la vista del ultimo viewport dibujado).
    propLodOnlyCam = new PropBool(T("Only active camera"));
    propLOD->properties.push_back(propLodOnlyCam);
    GroupProperties.push_back(propLOD);

    // pestania del objeto Culling UNIFICADO: un solo objeto con SELECTOR de metodo (Frustum/Grid/Triangulo/BSP)
    // + boton "Recalcular". Los campos de grilla (Cell size / 3D grid) solo aparecen con metodo=Grid.
    propCulling = new GroupPropertie(T("Culling"));
    // SELECTOR de metodo (dropdown), primero de la lista.
    propCullMethod = new PropButton(T("Frustum (AABB)"), IconType::visible);
    propCullMethod->button->dropdown = true;
    propCullMethod->action = ActionMenuCullMethod;
    propCulling->properties.push_back(propCullMethod);
    // INTERRUPTOR del recorte (demo A/B: apagar y ver TODO el escenario, prender y ver desaparecer lo de afuera).
    propCullActive = new PropBool(T("Active"));
    propCulling->properties.push_back(propCullActive);
    // "solo camara activa": calcula UNA vez desde la camara del juego (para TODAS las vistas); OFF = cada
    // vista/camara recalcula por su cuenta.
    propCullOnlyCam = new PropBool(T("Only active camera"));
    propCulling->properties.push_back(propCullOnlyCam);
    // culling por DISTANCIA (0 = sin limite): el corte que el frustum no hace en un nivel "pasillo".
    propCullDistMax = new PropFloat(T("Max distance"), "m");
    propCullDistMax->SetRange(0.0f, 100000.0f);
    propCulling->properties.push_back(propCullDistMax);
    // translucido: ordena back->forward (alpha) en vez de por material.
    propCullOrderAlpha = new PropBool(T("Alpha order"));
    propCulling->properties.push_back(propCullOrderAlpha);
    // opaco: forward->back puro (el mas cercano primero), sin agrupar por material
    propCullOrderNear = new PropBool(T("Front to back"));
    propCulling->properties.push_back(propCullOrderNear);
    // --- campos del metodo Grid (se ocultan con value=NULL cuando el metodo no es Grid) ---
    propCullCellSize = new PropFloat(T("Cell size"), "m");
    propCullCellSize->SetRange(0.5f, 100000.0f);
    propCullCellSize->onChange = ActionCullRecalculate;   // cambiar la celda rearma el reparto
    propCulling->properties.push_back(propCullCellSize);
    propCullMode3D = new PropBool(T("3D grid"));
    propCullMode3D->onChange = ActionCullRecalculate;     // 2D<->3D cambia la particion -> rearmar
    propCulling->properties.push_back(propCullMode3D);
    propCullRecalc = new PropButton(T("Recalculate"), IconType::grid);
    propCullRecalc->action = ActionCullRecalculate;
    propCulling->properties.push_back(propCullRecalc);
    GroupProperties.push_back(propCulling);

    // pestania del objeto NIEBLA: la llamada glFog puesta en el arbol (de ahi en adelante, solo en Render)
    // SONIDO: el parlante de la escena
    propSound = new GroupPropertie(T("Sound"));
    propSound->reserveKeyBtn = true;   // columna del rombo (volumen / tono / reverb se animan)
    propSoundFile = new PropButton(T("Sound"), IconType::sound);
    propSoundFile->withLabel = true;
    propSoundFile->button->dropdown = true;
    propSoundFile->action = ActionMenuSoundFile;
    propSound->properties.push_back(propSoundFile);
    propSoundActive = new PropBool(T("Active"));                 propSound->properties.push_back(propSoundActive);
    propSoundVol = new PropFloat(T("Volume")); propSoundVol->SetRange(0.0f, 2.0f);
    propSoundVol->fineStep = 0.05f; propSoundVol->thickStep = 0.1f; propSoundVol->dragStep = 0.01f;
    propSoundVol->animProp = AnimSound; propSoundVol->animComp = AnimX;
    propSound->properties.push_back(propSoundVol);
    propSoundTone = new PropFloat(T("Pitch")); propSoundTone->SetRange(0.25f, 4.0f);
    propSoundTone->fineStep = 0.01f; propSoundTone->thickStep = 0.1f; propSoundTone->dragStep = 0.005f;
    propSoundTone->animProp = AnimSound; propSoundTone->animComp = AnimY;
    propSound->properties.push_back(propSoundTone);
    propSoundReverb = new PropFloat(T("Reverb")); propSoundReverb->SetRange(0.0f, 1.0f);
    propSoundReverb->fineStep = 0.05f; propSoundReverb->thickStep = 0.1f; propSoundReverb->dragStep = 0.01f;
    propSoundReverb->animProp = AnimSound; propSoundReverb->animComp = AnimZ;
    propSound->properties.push_back(propSoundReverb);
    propSoundPan = new PropFloat(T("Pan")); propSoundPan->SetRange(-1.0f, 1.0f);
    propSoundPan->fineStep = 0.05f; propSoundPan->thickStep = 0.25f; propSoundPan->dragStep = 0.01f;
    propSound->properties.push_back(propSoundPan);
    // los TIEMPOS van en SEGUNDOS (no en frames): cambiar los fps de la escena no corre ningun audio
    propSoundStart = new PropFloat(T("Start time"), "s"); propSoundStart->SetRange(-100000.0f, 100000.0f);
    propSoundStart->fineStep = 0.01f; propSoundStart->thickStep = 1.0f; propSoundStart->dragStep = 0.01f;
    propSound->properties.push_back(propSoundStart);
    propSoundRecStart = new PropFloat(T("Trim start"), "s"); propSoundRecStart->SetRange(0.0f, 100000.0f);
    propSoundRecStart->fineStep = 0.01f; propSoundRecStart->thickStep = 0.5f; propSoundRecStart->dragStep = 0.01f;
    propSound->properties.push_back(propSoundRecStart);
    propSoundRecEnd = new PropFloat(T("Trim end"), "s"); propSoundRecEnd->SetRange(0.0f, 100000.0f);
    propSoundRecEnd->fineStep = 0.01f; propSoundRecEnd->thickStep = 0.5f; propSoundRecEnd->dragStep = 0.01f;
    propSound->properties.push_back(propSoundRecEnd);
    propSoundLoop = new PropBool(T("Loop forever"));            propSound->properties.push_back(propSoundLoop);
    propSoundPos = new PropBool(T("Positional (3D)"));           propSound->properties.push_back(propSoundPos);
    propSoundPos->onChange = ActionPositionalSound;   // (las filas del 3D aparecen / se van al tildarlo)
    propSoundRadius = new PropFloat(T("Full volume radius"), "m"); propSoundRadius->SetRange(0.0f, 100000.0f);
    propSoundRadius->fineStep = 0.1f; propSoundRadius->thickStep = 1.0f; propSoundRadius->dragStep = 0.05f;
    propSound->properties.push_back(propSoundRadius);
    propSoundRange = new PropFloat(T("Audible range"), "m"); propSoundRange->SetRange(0.0f, 100000.0f);
    propSoundRange->fineStep = 0.5f; propSoundRange->thickStep = 5.0f; propSoundRange->dragStep = 0.1f;
    propSound->properties.push_back(propSoundRange);
    GroupProperties.push_back(propSound);

    // VACIO: como se dibuja. Es solo la vista: no cambia el objeto, ni su transformacion, ni a sus hijos


    // LIMPIAR Z y RECORTE: composicion de la pantalla puesta en el arbol
    propClip = new GroupPropertie(T("Screen Rect"));
    propRcActive = new PropBool(T("Active"));
    propClip->properties.push_back(propRcActive);
    propRcX = new PropFloat("X"); propRcX->SetRange(-1.0f, 1.0f); propRcX->fineStep = 0.01f; propRcX->dragStep = 0.002f;
    propClip->properties.push_back(propRcX);
    propRcY = new PropFloat("Y"); propRcY->SetRange(-1.0f, 1.0f); propRcY->fineStep = 0.01f; propRcY->dragStep = 0.002f;
    propClip->properties.push_back(propRcY);
    propRcWidth = new PropFloat(T("Width")); propRcWidth->SetRange(0.0f, 1.0f); propRcWidth->fineStep = 0.01f; propRcWidth->dragStep = 0.002f;
    propClip->properties.push_back(propRcWidth);
    propRcHeight = new PropFloat(T("Height")); propRcHeight->SetRange(0.0f, 1.0f); propRcHeight->fineStep = 0.01f; propRcHeight->dragStep = 0.002f;
    propClip->properties.push_back(propRcHeight);
    propRcCamera = new PropButton(T("(none)"), IconType::camera);
    propRcCamera->button->dropdown = true;
    propRcCamera->action = ActionMenuRcCamera;
    propClip->properties.push_back(propRcCamera);
    propRcClearZ = new PropBool(T("Clear depth"));
    propClip->properties.push_back(propRcClearZ);
    propRcBackground = new PropBool(T("Fill"));
    propClip->properties.push_back(propRcBackground);
    propRcColor = new PropColor(T("Color"));
    propClip->properties.push_back(propRcColor);
    GroupProperties.push_back(propClip);
    // HITBOX: caja de deteccion (la tarjeta entera vive en PropsHitbox.cpp)
    PropsHitboxBuild(this);
    PropsLightProbeBuild(this);   // LA SONDA DE LUZ (PropsLightProbe.cpp)
    PropsReflectionProbeBuild(this);   // LA SONDA DE REFLEJO (PropsReflectionProbe.cpp)
    PropsRoutineBuild(this);
    PropsPrefabBuild(this);   // la tarjeta de una instancia de prefab (y de lo que genera)

    // pestania del objeto MIRROR (pedido del dueno: "el mirror no tiene propiedades"):
    // a quien espeja (por nombre, commit en vivo) + en que ejes + el rectangulo del
    // plano (los limites que ademas usa el autocull del espejo).
    propMirror = new GroupPropertie(T("Mirror"));
    propMirrorTarget = new PropText(T("Target"), "");
    propMirror->properties.push_back(propMirrorTarget);
    propMirrorX = new PropBool(T("Mirror X"));
    propMirror->properties.push_back(propMirrorX);
