    propRenderStart = new PropFloat(T("Start"));
    propRenderStart->SetRange(0.0f, 100000.0f); propRenderStart->integer = true; propRenderStart->value = &g_renderStartF;
    propRenderStart->fineStep = 1; propRenderStart->thickStep = 10; propRenderStart->dragStep = 1; propRenderStart->onChange = ActionRenderStart;
    propRender->properties.push_back(propRenderStart);
    propRenderEnd = new PropFloat(T("End"));
    propRenderEnd->SetRange(1.0f, 100000.0f); propRenderEnd->integer = true; propRenderEnd->value = &g_renderEndF;
    propRenderEnd->fineStep = 1; propRenderEnd->thickStep = 10; propRenderEnd->dragStep = 1; propRenderEnd->onChange = ActionRenderEnd;
    propRender->properties.push_back(propRenderEnd);
    propRenderFps = new PropFloat(T("FPS"));
    propRenderFps->SetRange(1.0f, 120.0f); propRenderFps->integer = true; propRenderFps->value = &g_renderFpsF;
    propRenderFps->fineStep = 1; propRenderFps->thickStep = 5; propRenderFps->dragStep = 1; propRenderFps->onChange = ActionRenderFps;
    propRender->properties.push_back(propRenderFps);
    GroupProperties.push_back(propRender);
    PropsShadowsBuild(this);   // LAS SOMBRAS EN TIEMPO REAL, debajo de la tarjeta Render (PropsShadows.cpp)

    // tarjeta "Post Processing" (debajo de Render): la pila de efectos de la vista Rendered y del render a archivo
