    propListPost->rowsMax  = 3; propListPost->minRows = 3; propListPost->buttonsSide = true;
    propListPost->minItems = 0;
    propListPost->opDelete = ActionRemovePost;
    propListPost->opUpload = ActionPostUpload; propListPost->opLower = ActionPostLower;
    propPost->properties.push_back(propListPost);
    propRowPost = new PropButtonRow();
    { Button* b = propRowPost->Add(T("Add"), ActionMenuAddPost); if (b) b->dropdown = true; }
    propPost->properties.push_back(propRowPost);
    propRowPostMove = NULL;
    propPostActive = new PropBool(T("Enabled")); propPostActive->onChange = ActionPostChange;
    propPost->properties.push_back(propPostActive);
    // GRANO
    propPostGrainInt = new PropFloat(T("Intensity")); propPostGrainInt->SetRange(0.0f, 1.0f);
    propPostGrainInt->fineStep = 0.01f; propPostGrainInt->thickStep = 0.1f; propPostGrainInt->dragStep = 0.005f;
    propPost->properties.push_back(propPostGrainInt);
    propPostGrainSize = new PropFloat(T("Grain size")); propPostGrainSize->SetRange(1.0f, 8.0f); propPostGrainSize->integer = true;
    propPostGrainSize->fineStep = 1.0f; propPostGrainSize->thickStep = 1.0f; propPostGrainSize->dragStep = 1.0f;
    propPost->properties.push_back(propPostGrainSize);
    propPostGrainColor = new PropBool(T("Colored grain"));
    propPost->properties.push_back(propPostGrainColor);
    // DESENFOQUE DE CAMPO
    propPostFocusCam = new PropBool(T("Use camera focus")); propPostFocusCam->onChange = ActionPostChange;
    propPost->properties.push_back(propPostFocusCam);
    propPostFocusDist = new PropFloat(T("Focus distance")); propPostFocusDist->SetRange(0.01f, 10000.0f);
    propPostFocusDist->fineStep = 0.1f; propPostFocusDist->thickStep = 1.0f; propPostFocusDist->dragStep = 0.05f; propPostFocusDist->unit = "m";
    propPost->properties.push_back(propPostFocusDist);
    propPostFocusRange = new PropFloat(T("Sharp range")); propPostFocusRange->SetRange(0.01f, 1000.0f);
    propPostFocusRange->fineStep = 0.1f; propPostFocusRange->thickStep = 1.0f; propPostFocusRange->dragStep = 0.05f; propPostFocusRange->unit = "m";
    propPost->properties.push_back(propPostFocusRange);
    propPostFocusBlur = new PropFloat(T("Blur")); propPostFocusBlur->SetRange(0.0f, 10.0f);
    propPostFocusBlur->fineStep = 0.1f; propPostFocusBlur->thickStep = 1.0f; propPostFocusBlur->dragStep = 0.05f; propPostFocusBlur->unit = "%";
    propPost->properties.push_back(propPostFocusBlur);
    // DESENFOQUE DE MOVIMIENTO
    propPostMovObt = new PropFloat(T("Shutter")); propPostMovObt->SetRange(0.0f, 1.0f);
    propPostMovObt->fineStep = 0.05f; propPostMovObt->thickStep = 0.25f; propPostMovObt->dragStep = 0.01f;
    propPost->properties.push_back(propPostMovObt);
    // BLOOM: intensidad, umbral, rodilla suave, tope, difusion, relacion anamorfica + el tinte + el modo rapido
    {
        struct Row { const char* name; float mn, mx, fine, thick, drag; };
        static const Row kF[6] = {
            { "Intensity",        0.0f, 10.0f, 0.05f, 0.5f, 0.01f },
            { "Threshold",        0.0f,  1.0f, 0.01f, 0.1f, 0.005f },
            { "Soft Knee",        0.0f,  1.0f, 0.01f, 0.1f, 0.005f },
            { "Clamp",            0.0f,  1.0f, 0.01f, 0.1f, 0.005f },
            { "Diffusion",        1.0f, 10.0f, 0.1f,  1.0f, 0.05f },
            { "Anamorphic Ratio", -1.0f, 1.0f, 0.01f, 0.1f, 0.005f } };
        for (int k = 0; k < 6; k++) {
            propPostBloom[k] = new PropFloat(T(kF[k].name)); propPostBloom[k]->SetRange(kF[k].mn, kF[k].mx);
            propPostBloom[k]->fineStep = kF[k].fine; propPostBloom[k]->thickStep = kF[k].thick; propPostBloom[k]->dragStep = kF[k].drag;
            propPostBloom[k]->value = NULL;
            propPost->properties.push_back(propPostBloom[k]);
        }
        propPostBloomColor = new PropColor(T("Color")); propPostBloomColor->value = NULL;
        propPost->properties.push_back(propPostBloomColor);
        propPostFastBloom = new PropBool(T("Fast Mode"));
        propPost->properties.push_back(propPostFastBloom);
    }
    GroupProperties.push_back(propPost);
    PostRowsPanel(this);

    // tarjeta "Animation" (pestania Render): selector de la animacion ACTIVA (Scene(s) / clips del armature) + Start/End/
