    {
        propFlipAtlas = new PropButton(T("Atlas"), IconType::texture);
        propFlipAtlas->button->dropdown = true;
        propFlipAtlas->action = ActionMenuFlipAtlas;
        propFlipAtlas->hidden = true;
        propAnimation->properties.push_back(propFlipAtlas);
        // los PropFloat se OCULTAN con value=NULL (no tienen 'oculto'); el sync los bindea con flipbook activo
        propFlipFrames = new PropFloat(T("Frames"));
        propFlipFrames->SetRange(1.0f, 4096.0f); propFlipFrames->integer = true;
        propFlipFrames->fineStep = 1.0f; propFlipFrames->dragStep = 1.0f;
        propFlipFrames->value = NULL; propFlipFrames->onChange = ActionFlipConfig;
        propAnimation->properties.push_back(propFlipFrames);
        propFlipCols = new PropFloat(T("Columns"));
        propFlipCols->SetRange(1.0f, 256.0f); propFlipCols->integer = true;
        propFlipCols->fineStep = 1.0f; propFlipCols->dragStep = 1.0f;
        propFlipCols->value = NULL; propFlipCols->onChange = ActionFlipConfig;
        propAnimation->properties.push_back(propFlipCols);
        propFlipRows = new PropFloat(T("Rows"));
        propFlipRows->SetRange(1.0f, 256.0f); propFlipRows->integer = true;
        propFlipRows->fineStep = 1.0f; propFlipRows->dragStep = 1.0f;
        propFlipRows->value = NULL; propFlipRows->onChange = ActionFlipConfig;
        propAnimation->properties.push_back(propFlipRows);
        propFlipFps = new PropFloat(T("Speed"), "fps");
        propFlipFps->SetRange(0.0f, 120.0f);
        propFlipFps->value = NULL; propFlipFps->onChange = ActionFlipConfig;
        propAnimation->properties.push_back(propFlipFps);
    }
    propAnimation->valueWidth = 0.55f; // Start/End/FPS son campos numericos: mas lugar al valor
    propBtnAnimSel = new PropButton(T("Scene"), IconType::camera); // dropdown: animacion activa (Scene por defecto)
    propBtnAnimSel->button->dropdown = true;
    propBtnAnimSel->button->caretMenu = true; // aca SI conviene la flechita (no es obvio que es un selector)
    propBtnAnimSel->action = ActionMenuAnimSel;
    propAnimation->properties.push_back(propBtnAnimSel);
    // Start / End / FPS de la animacion (espejos float de los int StartFrame/EndFrame/AnimFPS)
    { PropFloat* pS = new PropFloat(T("Start"));
      pS->SetRange(0.0f, 100000.0f); pS->integer = true; pS->fineStep = 1.0f; pS->thickStep = 10.0f; pS->dragStep = 1.0f;
      g_animStartF = (float)StartFrame; pS->value = &g_animStartF; pS->onChange = ActionAnimStart; gPropAnimStart = pS;
      propAnimation->properties.push_back(pS); }
    { PropFloat* pE = new PropFloat(T("End"));
      pE->SetRange(1.0f, 100000.0f); pE->integer = true; pE->fineStep = 1.0f; pE->thickStep = 10.0f; pE->dragStep = 1.0f;
      g_animEndF = (float)EndFrame; pE->value = &g_animEndF; pE->onChange = ActionAnimEnd; gPropAnimEnd = pE;
      propAnimation->properties.push_back(pE); }

    { PropFloat* pF = new PropFloat(T("FPS"));
      pF->SetRange(1.0f, 120.0f); pF->integer = true; pF->fineStep = 1.0f; pF->thickStep = 5.0f; pF->dragStep = 1.0f;
      g_animFpsF = (float)AnimFPS; pF->value = &g_animFpsF; pF->onChange = ActionAnimFps; gPropAnimFps = pF;
      propAnimation->properties.push_back(pF); }
    { PropFloat* pV = new PropFloat(T("Speed"));
      pV->SetRange(0.01f, 20.0f); pV->fineStep = 0.05f; pV->thickStep = 0.25f; pV->dragStep = 0.05f;
      pV->value = NULL;   // solo visible con una VERTEX ANIM activa (kind 3); lo maneja SyncAnimFps
      pV->onChange = ActionVertVel; gPropVertVel = pV;
      propAnimation->properties.push_back(pV); }
    // New | Delete en UNA fila
    propRowAnimNewDel = new PropButtonRow();
    propRowAnimNewDel->Add(T("New"), ActionAnimNewCard, IconType::armature);
    propRowAnimNewDel->Add(T("Duplicate"), ActionAnimDupCard); // duplica el clip activo (se oculta sin clips)
    propRowAnimNewDel->Add(T("Delete"), ActionCardAnim, IconType::trash);
    propAnimation->properties.push_back(propRowAnimNewDel);
    // Rename de la animacion activa (escena o clip): el boton se vuelve input in-place
