    propClipRetarget->button->dropdown = true;
    propClipRetarget->withLabel = true;
    propClipRetarget->action = ActionMenuClipRetarget;
    propClipRetarget->hidden = true;
    propAnimation->properties.push_back(propClipRetarget);
