    propLayer->properties.push_back(propLayerAnim);
    propLayerVisible = new PropBool(T("Visible")); propLayerVisible->onChange = ActionLayerChange;
    propLayer->properties.push_back(propLayerVisible);
    propLayerInfl = new PropFloat(T("Influence"), "%"); propLayerInfl->SetRange(0.0f, 200.0f); propLayerInfl->onChange = ActionLayerChange;
    propLayer->properties.push_back(propLayerInfl);
