    propLayer->properties.push_back(propLayerFrom);
    propLayerVel = new PropFloat(T("Speed")); propLayerVel->SetRange(0.0f, 20.0f); propLayerVel->onChange = ActionLayerChange;
    propLayer->properties.push_back(propLayerVel);
