    propGamePlat = new PropButton(T("Platform"));
    propGamePlat->withLabel = true;
    propGamePlat->button->dropdown = true;
    propGamePlat->button->text = PlatName(g_projCompile.platform);
    propGamePlat->action = ActionMenuPlat;
    propGame->properties.push_back(propGamePlat);
    propGameBackend = new PropButton(T("Graphics backend"));
    propGameBackend->withLabel = true;
    propGameBackend->button->dropdown = true;
    propGameBackend->button->text = BackendNameGame();
    propGameBackend->action = ActionMenuBackendGame;
    propGame->properties.push_back(propGameBackend);
    propGameVentMode = new PropButton(T("Window mode"));
    propGameVentMode->withLabel = true;
    propGameVentMode->button->dropdown = true;
    propGameVentMode->button->text = VentModeName(g_projCompile.windowMode);
