    propGame->properties.push_back(propGameVentMode);
    propGameOrient = new PropButton(T("Orientation"));
    propGameOrient->withLabel = true;
    propGameOrient->button->dropdown = true;
    propGameOrient->button->text = OrientationName(g_projCompile.orientation);
    propGameOrient->action = ActionMenuOrient;
    propGame->properties.push_back(propGameOrient);
