    propGameIcon = new PropButton(T("Icon"));
    propGameIcon->withLabel = true;
    propGameIcon->button->dropdown = true;   // (abre un menu: lleva la flechita)
    propGameIcon->button->text = IconNameGame();
    propGameIcon->action = ActionMenuIcon;
    propGame->properties.push_back(propGameIcon);
    // assets del juego compilado: sueltos (editables, como siempre) o empaquetados
