    propGameAssets = new PropButton(T("Assets"));
    propGameAssets->withLabel = true;
    propGameAssets->button->dropdown = true;
    propGameAssets->button->text = AssetNameMode(g_projCompile.assetsMode);
    propGameAssets->action = ActionMenuAssets;
    propGame->properties.push_back(propGameAssets);
    // UID de Symbian del juego: cada juego es su PROPIA app (no pisa el editor). El boton
    // GENERA un UID random (rango self-signed) que se guarda en el .w3d. Solo lo usa el target Symbian.
    propGameUID = new PropButton("UID Symbian");
    propGameUID->withLabel = true;
    propGameUID->button->text = UIDName();
    propGameUID->action = ActionGenerateUID;
    propGameUID->hidden = (g_projCompile.platform != 5);  // visible solo con Symbian
    propGame->properties.push_back(propGameUID);
    // subsistemas opcionales: destildado = el juego compilado sale SIN ese modulo
    propGamePhysics = new PropBool(T("Use physics engine"));
