    propProjNet = new PropBool(T("Network access"));
    NetRefresh();
    propProjNet->value = &g_projNet;
    propProjNet->onChange = ActionProjNet;
    propGame->properties.push_back(propProjNet);
    // volumen del gameplay 0..100 (audio del juego): baja/sube en vivo (onChange aplica la ganancia al mixer).
