    propGame->properties.push_back(propGameCompile);
    // EDITOR WEB: compilar un juego necesita cmake / emcc / gradle EN LA MAQUINA, y el navegador no los tiene ni puede
    // correr programas: el boton fallaba siempre. Quedan las dos filas que tambien valen jugando adentro del editor
    // (con que escena arranca y el volumen); la configuracion de compilar viaja igual con el proyecto
    if (GameNoCompiler()) {
        PropButton* onlyCompile[] = { propGamePlat, propGameBackend, propGameVentMode, propGameOrient, propGameIcon,
                                       propGameAssets, propGameUID, propGameCompile };
        for (size_t k = 0; k < sizeof(onlyCompile) / sizeof(onlyCompile[0]); k++) onlyCompile[k]->hidden = true;
        // (las casillas sin valor no ocupan fila)
        propGamePhysics->value = NULL; propGameSound->value = NULL; propGameDebug->value = NULL;
    }
    GroupProperties.push_back(propGame);

    // ===== Tarjeta "Curva": las curvas elegidas en el timeline (pestania Animacion, entre Animacion y Keyframe) =====
    propCurve = new GroupPropertie(T("Curve"));
    propCurve->icon = (int)IconType::interp_bezier;
    propCurve->valueWidth = 0.55f;
    gCuInterp = new PropButton(T("Interpolation"));
    gCuInterp->button->dropdown = true; gCuInterp->button->caretMenu = true;
    gCuInterp->action = ActionCuBtnInterp;
    propCurve->properties.push_back(gCuInterp);
    gCuHandle = new PropButton(T("Handle Type"));
    gCuHandle->button->dropdown = true; gCuHandle->button->caretMenu = true;
    gCuHandle->action = ActionCuBtnHandle;
    propCurve->properties.push_back(gCuHandle);
    // (el Repetir antes / despues NO va aca: es un MODIFICADOR -Ciclos-, en la pestania Modificadores)
    GroupProperties.push_back(propCurve);

    // ===== Tarjeta "Keyframe": el keyframe elegido en el editor de curvas, con numeros exactos =====
    // Aparece SOLO cuando hay uno elegido. X = frame (entero), Y = valor. Los handles son puntos (offset desde el
    // keyframe) y solo se pueden tipear si el tipo los guarda (Free/Aligned); con los calculados quedan grises.
    // Con VARIOS elegidos: "N keyframes seleccionados", lo que no coincide se ve "-" y lo que se tipea va a todos.
    propKeyframe = new GroupPropertie(T("Keyframe"));
    propKeyframe->icon = (int)IconType::keyframe;   // el rombo, igual que el del timeline
    propKeyframe->valueWidth = 0.55f;
    { PropFloat* p1 = new PropFloat(T("Frame X"));
      p1->integer = true; p1->fineStep = 1.0f; p1->thickStep = 10.0f; p1->dragStep = 1.0f;
      p1->value = &g_kfFrame; p1->onChange = ActionKfFrame; gKfFrame = p1;
      propKeyframe->properties.push_back(p1); }
    { PropFloat* p1 = new PropFloat(T("Value Y"));
      p1->value = &g_kfValue; p1->onChange = ActionKfValue; gKfValue = p1;
      propKeyframe->properties.push_back(p1); }
    propKeyframe->properties.push_back(new PropGap(""));
    gKfInterp = new PropButton(T("Interpolation"));
    gKfInterp->button->dropdown = true; gKfInterp->button->caretMenu = true;
    gKfInterp->action = ActionKfBtnInterp;
    propKeyframe->properties.push_back(gKfInterp);
    gKfHandle = new PropButton(T("Handle Type"));
    gKfHandle->button->dropdown = true; gKfHandle->button->caretMenu = true;
    gKfHandle->action = ActionKfBtnHandle;
    propKeyframe->properties.push_back(gKfHandle);
    propKeyframe->properties.push_back(new PropGap(""));
    { PropFloat* p1 = new PropFloat(T("Left Handle X"));
      p1->value = &g_kfInDF; p1->onChange = ActionKfInDF; gKfInDF = p1;
      propKeyframe->properties.push_back(p1); }
    { PropFloat* p1 = new PropFloat("Y");
      p1->value = &g_kfInDV; p1->onChange = ActionKfInDV; gKfInDV = p1;
      propKeyframe->properties.push_back(p1); }
    { PropFloat* p1 = new PropFloat(T("Right Handle X"));
      p1->value = &g_kfOutDF; p1->onChange = ActionKfOutDF; gKfOutDF = p1;
      propKeyframe->properties.push_back(p1); }
    { PropFloat* p1 = new PropFloat("Y");
      p1->value = &g_kfOutDV; p1->onChange = ActionKfOutDV; gKfOutDV = p1;
      propKeyframe->properties.push_back(p1); }
    GroupProperties.push_back(propKeyframe);

    // tarjeta "Camara activa" (pestania Animacion): cual camara manda y los CORTES de la cinematica
    // [selector de camara] [rombo]: el rombo se pone VERDE al elegir otra camara (cambio sin guardar); un click
    // guarda el CORTE en el frame actual (mismo rombo y mismo idioma que las demas propiedades animables)
    propCamActive = new GroupPropertie(T("Active camera"));
    propCamActive->reserveKeyBtn = true;
    propActiveCamSel = new PropButton("", IconType::camera);
    propActiveCamSel->button->dropdown = true;
    propActiveCamSel->action = ActionActiveMenuCam;
    propActiveCamSel->animProp = AnimCamActive; propActiveCamSel->animComp = AnimX;
    propCamActive->properties.push_back(propActiveCamSel);
    propActiveCamKey = NULL;
    GroupProperties.push_back(propCamActive);

    propExport = new GroupPropertie(T("Export"));
    propExport->valueWidth = 0.62f;
    // dropdown de FORMATO (arriba de todo): OBJ / FBX / glTF / GLB. La etiqueta muestra el formato activo.
    propExportFormat = new PropButton(FormatName(exportFormat), IconType::mesh);
    propExportFormat->button->dropdown = true;
    propExportFormat->button->caretMenu = true; // flechita: es un selector de formato
    propExportFormat->action = ActionMenuExportFormat;
    propExport->properties.push_back(propExportFormat);
    PropBool* pbSel = new PropBool(T("Selected only"));
    pbSel->value = &exportSelectedOnly;
    propExport->properties.push_back(pbSel);
    PropBool* pbMods = new PropBool(T("Apply Modifiers")); // OBJ: ON = exporta la malla generada por los modificadores
    pbMods->value = &exportApplyModifiers;
    propExport->properties.push_back(pbMods);
    PropBool* pbXf = new PropBool(T("Apply Transforms")); // OBJ: ON = hornea el transform del objeto en el .obj (mundo)
    pbXf->value = &exportApplyTransforms;
    propExport->properties.push_back(pbXf);
    // salida partida en dos: Path (carpeta) + File name (nombre + extension del formato). Default: Descargas en Android.
    propExportPath = new PropText(T("Path"), w3dFileSystem::GetDefaultOutputDir());
    propExportPath->onClick = ActionBrowseExport; // el campo Path ES el "Browse folder": al clickear abre el explorador
    propExport->properties.push_back(propExportPath);
    propExportName = new PropText(T("File name"), std::string("model") + ExtOfFormat(exportFormat));
    propExport->properties.push_back(propExportName);
    PropButton* pbExp = new PropButton(T("Export"), IconType::save);
    pbExp->action = ActionExport;
    propExport->properties.push_back(pbExp);
    GroupProperties.push_back(propExport);

    // ===== tarjeta "Ajustes" (ABAJO DE TODO en la pestania Render): el config.start editable desde adentro =====
    propSettings = new GroupPropertie(T("Settings"));
    propSettings->valueWidth = 0.62f;
    // la VERSION (fecha + hora de compilacion): asi se sabe que build se esta usando (en la web, si el navegador
    // ya cargo la nueva)
    { extern const char* W3dVersionBuild();
      propSettings->properties.push_back(new PropLabel(std::string(T("Version")) + " " + W3dVersionBuild())); }

    propSettingsLanguage = new PropButton(T("Language"));   // label a la izquierda, el valor a la derecha
    propSettingsLanguage->withLabel = true;
    propSettingsLanguage->button->text = W3dLanguageName(g_language);
    propSettingsLanguage->button->dropdown = true;
    propSettingsLanguage->action = ActionMenuLanguage;
    propSettings->properties.push_back(propSettingsLanguage);

    propSettingsAntialias = new PropBool(T("Antialiasing"));
    propSettingsAntialias->value = &cfg.enableAntialiasing;
    propSettingsAntialias->onChange = ActionAntialias;
    propSettings->properties.push_back(propSettingsAntialias);

    { PropBool* pm = new PropBool(T("Mipmaps"));   // global del EDITOR (el proyecto puede pisarlo)
      pm->value = &cfg.mipmaps;
      pm->onChange = ActionMipmapsEditor;
      propSettings->properties.push_back(pm); }

    propSettingsBackend = new PropButton(T("Graphics"));
    propSettingsBackend->withLabel = true;
    propSettingsBackend->button->text = TextBackend();
    propSettingsBackend->button->dropdown = true;
    propSettingsBackend->action = ActionMenuBackend;
    propSettings->properties.push_back(propSettingsBackend);

    propSettingsSkin = new PropButton(T("Skin"));
    propSettingsSkin->withLabel = true;
    propSettingsSkin->button->text = cfg.SkinName;
    propSettingsSkin->button->dropdown = true;
    propSettingsSkin->action = ActionMenuSkin;
    propSettings->properties.push_back(propSettingsSkin);

    propSettingsLogs = new PropButton(T("Logs"));
    propSettingsLogs->withLabel = true;
    propSettingsLogs->button->text = T(LogsLabel(cfg.logs));
    propSettingsLogs->button->dropdown = true;
    propSettingsLogs->action = ActionMenuLogs;
    propSettings->properties.push_back(propSettingsLogs);

    // EL TECLADO EN PANTALLA: destildado = los de Whisk3D en todos lados (texto y numeros); tildado = el del sistema
    { PropBool* pk = new PropBool(T("Use system keyboard"));
      pk->value = &cfg.keyboardSystem;
      pk->onChange = ActionKeyboardSystem;
#ifdef W3D_SYMBIAN
      delete pk;   // (el N95 no tiene teclado del sistema en pantalla: la fila no va; PropBool no tiene 'oculto')
#else
      propSettings->properties.push_back(pk);
#endif
    }

    // RAIZ DEL REPO para Compilar: solo hace falta cuando el editor corre INSTALADO (sin el repo al lado).
    // El que compila juegos pega aca la ruta a la carpeta del repo (la que tiene libs/Whisk3DCore) y con
    // "Save Changes" queda guardada en el config. Vacio = el editor la busca sola subiendo de carpetas.
    propSettingsRepo = new PropText(T("Repo"), cfg.repoPath.c_str());
    propSettingsRepo->hidden = GameNoCompiler();   // en el navegador no se compila nada: no hay repo que buscar
    propSettings->properties.push_back(propSettingsRepo);

    // el NOMBRE de este dispositivo en la red: el que ven los demas al buscar partidas (por defecto, el del equipo).
    // Se guarda al tipearlo (network.txt, junto a los permisos de la red)
    propSettingsDevice = new PropText(T("Device name"), NetDevice().c_str());
#ifdef __EMSCRIPTEN__
    propSettingsDevice->hidden = true;   // el navegador no juega en red (W3dRed sin red): el nombre no lo ve nadie
#endif
    propSettings->properties.push_back(propSettingsDevice);

    // la ESCALA del editor, en vivo (x1 = N95, x3 = default PC)
    { PropFloat* pe = new PropFloat(T("Scale"), "x");
      g_settingsScale = (float)(cfg.scale > 0 ? cfg.scale : 3);
      pe->SetRange(1.0f, 6.0f); pe->integer = true;
      pe->value = &g_settingsScale;
      pe->onChange = ActionScaleEditor;
      propSettings->properties.push_back(pe); }

    // ATAJOS DE TECLADO: la ventana para reasignarlos (se guardan solos en shortcuts.start, no hace falta "Save Changes")
    { PropButton* pbAt = new PropButton(T("Keyboard Shortcuts..."));
      pbAt->action = OpenShortcutsPopup;
      propSettings->properties.push_back(pbAt); }

    { PropButton* pbSave = new PropButton(T("Save Changes"), IconType::save);
      pbSave->action = ActionSaveConfig;
      propSettings->properties.push_back(pbSave); }

    GroupProperties.push_back(propSettings);   // ULTIMA -> queda abajo de todo

    // pestana TRANSFORMAR (icono del modo de seleccion, tab 5): tarjeta "Transform Mesh" (posicion
    // X/Y/Z del centro de la seleccion, editable -> traslada rigido; antes vivia en la pestania
    // Vertices) + tarjeta "Transform UV" (centro X/Y de los UVs de ESA MISMA seleccion; editar
    // los campos mueve los UVs con el undo liviano de UV). Solo en Edit Mode con algo seleccionado.
    propEditItem = new GroupPropertie(T("Transform Mesh"));
    { PropFloat* px = new PropFloat("X"); px->value = &editPosX; px->onChange = ActionEditPos; propEditItem->properties.push_back(px);
      PropFloat* py = new PropFloat("Y"); py->value = &editPosY; py->onChange = ActionEditPos; propEditItem->properties.push_back(py);
      PropFloat* pz = new PropFloat("Z"); pz->value = &editPosZ; pz->onChange = ActionEditPos; propEditItem->properties.push_back(pz); }
    GroupProperties.push_back(propEditItem);
    propUVTransform = new GroupPropertie(T("Transform UV"));
    { PropFloat* pu = new PropFloat("X"); pu->value = &uvPosU; pu->onChange = ActionEditUV; propUVTransform->properties.push_back(pu);
      PropFloat* pv = new PropFloat("Y"); pv->value = &uvPosV; pv->onChange = ActionEditUV; propUVTransform->properties.push_back(pv); }
    GroupProperties.push_back(propUVTransform);

    // pestaña VERTICES (icono mesh): TARJETAS. Las listas REUSAN PropListMeshParts (con scroll, resize, etc., el
    // MISMO componente que el selector de mesh part) en modo 4 (vertex groups) / 1 (uvmaps) / 2 (colors).
    // "Vertex Groups" va PRIMERA: es la mas importante (huesos del rig, pesos para deformar la malla).
    propVertexGroups = new GroupPropertie(T("Vertex Groups"));
    propListVertGroups = new PropListMeshParts(T("Vertex Groups")); propListVertGroups->mode = 4;
    propListVertGroups->opDelete = ActionGroupVert; propListVertGroups->opRename = ActionRenameGroup;
    propListVertGroups->opUpload = ActionVertGroupUp; propListVertGroups->opLower = ActionVertGroupDown;
    propListVertGroups->AddExtra("Assign", ActionVertGroupAssign, (int)IconType::mesh, true);
    propListVertGroups->AddExtra("Remove", ActionVertGroupRemove, (int)IconType::mesh, true);
    propListVertGroups->AddExtra("Select", ActionVertGroupSelect, (int)IconType::selection, true);
    propListVertGroups->AddExtra("Deselect", ActionVertGroupDeselect, (int)IconType::selection, true);
    propVertexGroups->properties.push_back(propListVertGroups);
    PropButton* pbAddGrp = new PropButton(T("Add Vertex Group"), IconType::mesh);
    pbAddGrp->action = ActionVertAddGroup;
    propVertexGroups->properties.push_back(pbAddGrp);
    propBtnAddVG = pbAddGrp;
    propBtnRenameGroup = new PropButton(T("Rename"), -1); // renombra el grupo activo (nombre unico por malla)
    propBtnRenameGroup->action = ActionRenameGroup;
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propVertexGroups->properties.push_back(propBtnRenameGroup);
#endif

    // fila Delete | Move Up | Move Down (Delete si hay >=1; Move si hay >=2)
    // fila Assign | Remove: los VERTICES seleccionados en Edit Mode entran (peso 1) o salen del
    // grupo activo. Es LA operacion que faltaba para armar un vertex group sin pincel.
    propRowGroupAssign = new PropButtonRow();
    propRowGroupAssign->Add(T("Assign"), ActionVertGroupAssign);
    propRowGroupAssign->Add(T("Remove"), ActionVertGroupRemove);
    propVertexGroups->properties.push_back(propRowGroupAssign);
    // fila Select | Deselect: el camino inverso (ver que agarra el grupo)
    propRowGroupSel = new PropButtonRow();
    propRowGroupSel->Add(T("Select"),   ActionVertGroupSelect);
    propRowGroupSel->Add(T("Deselect"), ActionVertGroupDeselect);
    propVertexGroups->properties.push_back(propRowGroupSel);
    propRowGroupOps = new PropButtonRow();
    propRowGroupOps->Add(T("Delete"),    ActionGroupVert);
    propRowGroupOps->Add(T("Move Up"),   ActionVertGroupUp);
    propRowGroupOps->Add(T("Move Down"), ActionVertGroupDown);
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propVertexGroups->properties.push_back(propRowGroupOps);
#endif

    GroupProperties.push_back(propVertexGroups);

    // "UV Groups": la OTRA entidad de pesos (por CORNER; la pinta el editor UV y la bindea por
    // nombre el armature 2D). Va en la MISMA pestania Vertices, JUSTO DEBAJO de Vertex Groups:
    // es donde el usuario ya viene a administrar los datos de la malla (UV maps / color / grupos),
    // esta siempre disponible (la pestania del armature 2D solo existe editando huesos) y tenerlas
    // pegadas hace obvio que son dos cosas distintas. Mismo patron de tarjeta que Vertex Groups.
    propUVGroups = new GroupPropertie(T("UV Groups"));
    propListUVGroups = new PropListMeshParts(T("UV Groups")); propListUVGroups->mode = 9;
    propListUVGroups->opDelete = ActionGroupUV; propListUVGroups->opRename = ActionRenameUVGroup;
    propListUVGroups->opUpload = ActionUVGroupUp; propListUVGroups->opLower = ActionUVGroupDown;
    propUVGroups->properties.push_back(propListUVGroups);
    PropButton* pbAddUVGrp = new PropButton(T("Add UV Group"), IconType::mesh);
    pbAddUVGrp->action = ActionUVAddGroup;
    propUVGroups->properties.push_back(pbAddUVGrp);
    propBtnAddUVG = pbAddUVGrp;
    propBtnRenameUVGroup = new PropButton(T("Rename"), -1);
    propBtnRenameUVGroup->action = ActionRenameUVGroup;
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propUVGroups->properties.push_back(propBtnRenameUVGroup);
#endif

    // MISMAS dos filas que Vertex Groups (mismo orden y mismos labels), pero POR CORNER y sobre
    // la seleccion del editor UV: se aprende una vez y sirve para las dos tarjetas.
    propRowUVGroupAssign = new PropButtonRow();
    propRowUVGroupAssign->Add(T("Assign"), ActionUVGroupAssign);
    propRowUVGroupAssign->Add(T("Remove"), ActionUVGroupRemove);
    propUVGroups->properties.push_back(propRowUVGroupAssign);
    propRowUVGroupSel = new PropButtonRow();
    propRowUVGroupSel->Add(T("Select"),   ActionUVGroupSelect);
    propRowUVGroupSel->Add(T("Deselect"), ActionUVGroupDeselect);
    propUVGroups->properties.push_back(propRowUVGroupSel);
    propRowUVGroupOps = new PropButtonRow();
    propRowUVGroupOps->Add(T("Delete"),    ActionGroupUV);
    propRowUVGroupOps->Add(T("Move Up"),   ActionUVGroupUp);
    propRowUVGroupOps->Add(T("Move Down"), ActionUVGroupDown);
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propUVGroups->properties.push_back(propRowUVGroupOps);
#endif

    GroupProperties.push_back(propUVGroups);

    // ===== pestania ARMATURE: tarjeta "Animation" (lista de clips del esqueleto + Add / Rename / Delete / Move) =====
    // MISMO componente que la lista de vertex groups (PropListMeshParts), pero en modo 5 (lee arm->animations).
    propArmAnim = new GroupPropertie(T("Animation"));
    propListAnims = new PropListMeshParts(T("Animation")); propListAnims->mode = 5;
    propListAnims->opDelete = ActionAnimDel; propListAnims->opRename = ActionRenameAnim;
    propListAnims->opUpload = ActionAnimUp; propListAnims->opLower = ActionAnimDown;
    propListAnims->AddExtra("Duplicate", ActionAnimDup, (int)IconType::copy, false);
    propArmAnim->properties.push_back(propListAnims);
    PropButton* pbAddAnim = new PropButton(T("New Animation"), IconType::armature); // crea un clip vacio en pose reset
    pbAddAnim->action = ActionAnimAdd;
    propArmAnim->properties.push_back(pbAddAnim);
    propBtnDupAnim = new PropButton(T("Duplicate"), IconType::armature); // duplica el clip activo (se oculta sin clips)
    propBtnDupAnim->action = ActionAnimDup;
    propArmAnim->properties.push_back(propBtnDupAnim);
    propBtnRenameAnim = new PropButton(T("Rename"), -1); // renombra el clip activo (nombre unico por armature)
    propBtnRenameAnim->action = ActionRenameAnim;
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propArmAnim->properties.push_back(propBtnRenameAnim);
#endif

    // fila Delete | Move Up | Move Down (Delete si hay >=1; Move si hay >=2)
    propRowAnimOps = new PropButtonRow();
    propRowAnimOps->Add(T("Delete"),    ActionAnimDel);
    propRowAnimOps->Add(T("Move Up"),   ActionAnimUp);
    propRowAnimOps->Add(T("Move Down"), ActionAnimDown);
#ifdef W3D_SYMBIAN   // (con teclado y sin mouse: los botones de siempre; en el resto, el tacho, el menu y el arrastre de la lista)
    propArmAnim->properties.push_back(propRowAnimOps);
#endif

    GroupProperties.push_back(propArmAnim);

    // ===== pestania ARMATURE: tarjeta "Bones": lista de huesos + Name editable + Parent desplegable
    // + pos/rot/scale (pose) del hueso activo =====
    propArmBones = new GroupPropertie(T("Bones"));
    propListBones = new PropListMeshParts(T("Bones")); propListBones->mode = 6; // lee arm->bones (mismo componente de lista)
    propArmBones->properties.push_back(propListBones);
    // fila "Name": cuadro editable inline (patron del Name del objeto). Al confirmar renombra el hueso
    // Y su vertex group asociado (SyncBoneName -> BoneRename; binding por nombre).
    propBoneName = new PropText(T("Name"), "");
    propArmBones->properties.push_back(propBoneName);
    // fila "Parent": desplegable con "None" + los huesos validos (sin el propio ni sus descendientes)
    propBoneParent = new PropButton(T("Parent"));
    propBoneParent->withLabel = true;
    propBoneParent->button->dropdown = true;
    propBoneParent->action = ActionMenuBoneParent;
    propArmBones->properties.push_back(propBoneParent);
    // fila "Connected": soldadura head-del-hijo <-> tail-del-padre. Nace TILDADA para los huesos
    // creados por extrude (el flag arranca en true). Se oculta si el hueso no tiene padre.
    propBoneConnected = new PropBool(T("Connected"));
    propBoneConnected->value = &g_boneConnected;
    propBoneConnected->onChange = ActionBoneConnected;
    propArmBones->properties.push_back(propBoneConnected);
    { PropFloat* px=new PropFloat(T("Pos X")); px->value=&g_bonePosX; px->onChange=ActionBoneTransform; propArmBones->properties.push_back(px);
      PropFloat* py=new PropFloat(T("Pos Y")); py->value=&g_bonePosY; py->onChange=ActionBoneTransform; propArmBones->properties.push_back(py);
      PropFloat* pz=new PropFloat(T("Pos Z")); pz->value=&g_bonePosZ; pz->onChange=ActionBoneTransform; propArmBones->properties.push_back(pz); }
    { PropFloat* rx=new PropFloat(T("Rot X")); rx->value=&g_boneRotX; rx->onChange=ActionBoneTransform; propArmBones->properties.push_back(rx);
      PropFloat* ry=new PropFloat(T("Rot Y")); ry->value=&g_boneRotY; ry->onChange=ActionBoneTransform; propArmBones->properties.push_back(ry);
      PropFloat* rz=new PropFloat(T("Rot Z")); rz->value=&g_boneRotZ; rz->onChange=ActionBoneTransform; propArmBones->properties.push_back(rz); }
    { PropFloat* sx=new PropFloat(T("Scale X")); sx->value=&g_boneSclX; sx->onChange=ActionBoneTransform; propArmBones->properties.push_back(sx);
      PropFloat* sy=new PropFloat(T("Scale Y")); sy->value=&g_boneSclY; sy->onChange=ActionBoneTransform; propArmBones->properties.push_back(sy);
      PropFloat* sz=new PropFloat(T("Scale Z")); sz->value=&g_boneSclZ; sz->onChange=ActionBoneTransform; propArmBones->properties.push_back(sz); }
    GroupProperties.push_back(propArmBones);

    // ===== tarjeta "ARMATURE 2D" (huesos 2D del mesh): lista + Name inline + Parent desplegable +
    // Pos de lo seleccionado (y Rotation/Scale de la POSE 2D). Solo visible mientras un editor UV
    // esta en Edit Bones/Pose (ver Bones2DMeshUI / UpdateTabs). =====
    propBones2D = new GroupPropertie(T("Armature") + std::string(" 2D"));
    // lista de ARMATURES 2D (arriba de todo: dice CUAL se esta editando) + Add / Rename / Delete
    propListArm2Ds = new PropListMeshParts(T("Armature") + std::string(" 2D")); propListArm2Ds->mode = 10;
    propBones2D->properties.push_back(propListArm2Ds);
    { PropButtonRow* row = new PropButtonRow();
      row->Add(T("Add"),    ActionArm2DAdd);
      row->Add(T("Delete"), ActionArm2DDel);
      propBones2D->properties.push_back(row); }
    propBtnRenameArm2D = new PropButton(T("Rename"), -1);
    propBtnRenameArm2D->action = ActionRenameArm2D;
    propBones2D->properties.push_back(propBtnRenameArm2D);
    propListBones2D = new PropListMeshParts(T("Bones")); propListBones2D->mode = 8; // huesos del armature ACTIVO
    propBones2D->properties.push_back(propListBones2D);
    // fila "Name": renombra el hueso Y su vertex group homonimo (SyncBoneName2D)
