    propArrCount->fineStep = 1.0f; propArrCount->thickStep = 5.0f; propArrCount->dragStep = 0.2f; propArrCount->onChange = ActionModParamChanged;
    propModifierProps->properties.push_back(propArrCount);
    propArrRelOn = new PropBool(T("Relative Offset")); propArrRelOn->onChange = ActionModParamChanged; propModifierProps->properties.push_back(propArrRelOn);
    { PropFloat** rel[3] = { &propArrRelX, &propArrRelY, &propArrRelZ }; const char* et[3] = { "Factor X", "Y", "Z" };
      for (int k = 0; k < 3; k++) { PropFloat* f = new PropFloat(k == 0 ? T(et[k]) : et[k]); f->SetRange(-1000.0f, 1000.0f);
          f->fineStep = 0.1f; f->thickStep = 1.0f; f->dragStep = 0.01f; f->onChange = ActionModParamChanged;
          propModifierProps->properties.push_back(f); *rel[k] = f; } }
    propArrConstOn = new PropBool(T("Constant Offset")); propArrConstOn->onChange = ActionModParamChanged; propModifierProps->properties.push_back(propArrConstOn);
    { PropFloat** cst[3] = { &propArrConstX, &propArrConstY, &propArrConstZ }; const char* et[3] = { "Distance X", "Y", "Z" };
      for (int k = 0; k < 3; k++) { PropFloat* f = new PropFloat(k == 0 ? T(et[k]) : et[k], "m"); f->SetRange(-100000.0f, 100000.0f);
          f->fineStep = 0.1f; f->thickStep = 1.0f; f->dragStep = 0.01f; f->onChange = ActionModParamChanged;
          propModifierProps->properties.push_back(f); *cst[k] = f; } }
    propArrTarget = new PropButton(T("Object Offset"), IconType::object);
