// arrastre del borde inferior de la lista de mesh parts (cambia rowsMax)
static bool gListResize = false;
static int gListResizeY0 = 0;
static int gRowList0 = 3;
// DRAG-SCROLL tactil de un mini-listado (UV/color/grupos/modificadores/parts): al arrastrar el dedo sobre la lista
// se scrollea ELLA (scrollRow), no el panel entero. Antes solo se podia con la rueda -> inusable en tactil.
static PropListMeshParts* gListScrollList = NULL;
// ARRASTRAR UN PASO de la lista de una rutina: de que fila salio, donde empezo y el tope de la lista en pantalla
static PropListMeshParts* gStepDrag = NULL;
static int gStepFrom = -1, gStepY0 = 0, gStepLimit = 0;
static bool gStepMoved = false;
static int gListScrollY0 = 0;   // my del press
static int gListScroll0 = 0;    // scrollRow al empezar el arrastre
// ARRASTRAR UNA FILA de cualquier lista con operaciones (PropListMeshParts::Reordenable): la fila sigue al mouse (o al
// dedo, despues de mantenerlo apretado) y una linea marca donde cae. En los bordes de arriba y de abajo la lista
// scrollea sola. Soltar la mueve con el Subir / Bajar de su tarjeta (los mismos de siempre: con su Ctrl+Z)
static void ListRename(Properties* p, PropListMeshParts* l, int row, int yTop, GroupPropertie* g);
static int RowListIn(Properties* p, int mx, int my, PropListMeshParts** list, int* yTop, GroupPropertie** group);
// LA BARRITA DE SCROLL de una lista bajo el puntero (NULL = ninguna); deja la y de arriba de su riel en pantalla
static PropListMeshParts* gListSbDrag = NULL;
static Button* gHighlightedSide = NULL;   // (el boton del costado resaltado: se suelta al levantar el dedo)
static int gListSbTop = 0;
static PropListMeshParts* ListSbIn(Properties* p, int mx, int my, int* top) {
    int yTop = 0, hF = 0; GroupPropertie* g = NULL;
    PropListMeshParts* l = p->ListIn(my, &yTop, &hF, &g);
    int track = 0, th = 0;
    if (!l || !g || !l->ScrollGeo(&track, &th, NULL)) return NULL;
    const int cx = p->x + p->PosX + borderGS * 2 + gapGS;   // (donde arranca el texto de las filas)
    const int x1 = cx + l->width - gapGS * 3 + GlobalScale * 3, x0 = x1 - GlobalScale * 9;
    const int y0 = yTop + borderGS;
    if (mx < x0 || mx > x1 + GlobalScale * 2 || my < y0 || my > y0 + track) return NULL;
    if (top) *top = y0;
    return l;
}
static void ListRowMenu(Properties* p, PropListMeshParts* l, int row, int yTop, GroupPropertie* g, int menuX, int menuY);
static PropListMeshParts* gRowDrag = NULL;
static int gRowFrom = -1, gRowY0 = 0, gRowLimit = 0, gLastRowY = 0;
static bool gRowMoved = false, gRowFinger = false;
static unsigned gRowScrollMs = 0;
static PropListMeshParts* gListResizeList = NULL;   // la lista cuyo borde de abajo se arrastra
static bool gTouchResize = false; static float gTouchResizeAcc = 0.0f;
static void RowDragDestination(int my) {
    if (!gRowDrag) return;
    const int rowH = RowHeightGS + gapGS;
    const int n = gRowDrag->ListCount();
    int d = gRowDrag->scrollRow + (my - gRowLimit + rowH / 2) / rowH;
    if (d < 0) d = 0;
    if (d > n) d = n;
    if (d != gRowDrag->rowDestination) { gRowDrag->rowDestination = d; g_redraw = true; }
}
// cada cuadro mientras se arrastra: con el puntero pegado al borde de arriba o de abajo de la lista, scrollea una fila
// cada tanto (y sigue redibujando para que siga)
static void RowDragTick() {
    if (!gRowDrag || !gRowMoved) return;
    PropListMeshParts* l = gRowDrag;
    const int rowH = RowHeightGS + gapGS;
    const int n = l->ListCount(), vis = n < l->rowsMax ? n : l->rowsMax;
    if (n <= vis) return;
    const int down = gRowLimit + vis * rowH;
    int step = 0;
    if (gLastRowY < gRowLimit + rowH / 2 && l->scrollRow > 0) step = -1;
    else if (gLastRowY > down - rowH / 2 && l->scrollRow < n - vis) step = 1;
    if (!step) return;
    extern double W3dNowMs();
    const unsigned now = (unsigned)W3dNowMs();
    if (now - gRowScrollMs >= 140u) { gRowScrollMs = now; l->scrollRow += step; RowDragDestination(gLastRowY); }
    g_redraw = true;
}
// soltar: la fila 'desde' cae ARRIBA de la fila 'hasta' (hasta = n: al final)
static void RowDragRelease() {
    PropListMeshParts* l = gRowDrag;
    gRowDrag = NULL;
    if (!l) return;
    const int until = l->rowDestination;
    l->rowDestination = -1;
    g_redraw = true;
    if (!gRowMoved || until < 0 || !l->Reordenable()) return;
    const int n = l->ListCount();
    if (gRowFrom < 0 || gRowFrom >= n) return;
    int steps = (until > gRowFrom) ? until - gRowFrom - 1 : until - gRowFrom;   // (+ baja, - sube)
    if (!steps) return;
    l->ListSelect(gRowFrom);
    for (; steps > 0; steps--) l->opLower();
    for (; steps < 0; steps++) l->opUpload();
    l->FitWindow();
    PropertiesLayoutDirty = true;
}

// arrastre de un PropFloat con el mouse: click + mover horizontal acumula el
