// el rebind global opera sobre el panel con el que se interactuo
void RebindMaterialMeshPart(){
    // EL MATERIAL ES DATO DE LA MALLA: si la malla del objeto activo es un RECURSO compartido,
    // el material que se le acaba de poner a una parte lo ven TODOS sus objetos (como Blender)
    if (ActiveObj && ActiveObj->getType() == ObjectType::mesh) {
        Mesh* m = (Mesh*)ActiveObj;
        if (m->mesh && m->materialsGroup.size() == m->mesh->parts.size())
            for (size_t k = 0; k < m->materialsGroup.size(); k++)
                if (k >= m->mesh->materials.size() || m->mesh->materials[k] != m->materialsGroup[k].material)
                    W3dMeshResourceChangeMaterial(m->mesh, (int)k, m->materialsGroup[k].material);
    }
    if (PropsActive) PropsActive->Rebind();
}

// ============================================================================
//  EL RECURSO ACTIVO de la BIBLIOTECA (el outliner), en la pestania "Malla 3D" (la 3)
// ============================================================================
// Name / Folder del recurso: muestran lo vigente mientras no se editan y, al perder el foco,
// renombran / mueven con su paso de undo (W3dViewRecRename / W3dViewRecMove). Mismo patron
// que el Name del objeto: el destino se captura al ENFOCAR (si el activo cambia mientras se tipea,
// el commit va al que se estaba editando).
struct RecFieldEdit { bool editing; int view; std::string id; RecFieldEdit() : editing(false), view(-1) {} };
static RecFieldEdit gRecNameEd, gRecFolderEd;
static void SyncFieldResource(PropText* pt, bool folder, RecFieldEdit& ed) {
    if (!pt) return;
    const bool focus = (g_activeTextField == &pt->field);
    int v = -1; std::string id;
    const bool has = W3dResourceActive(&v, &id);
    if (focus && !ed.editing && has) { ed.editing = true; ed.view = v; ed.id = id; }
    if (!focus && ed.editing) {
        ed.editing = false;
        if (folder) W3dViewRecMove(ed.view, ed.id, pt->field.text);
        else W3dViewRecRename(ed.view, ed.id, pt->field.text, NULL);
        PropertiesLayoutDirty = true;
        g_redraw = true;
    }
    if (!focus && has) {
        W3dResourceItem it;
        if (W3dViewRecInfo(v, id, &it)) {
            const std::string& val = folder ? it.folder : it.name;
            if (pt->field.text != val) { pt->field.SetText(val); g_redraw = true; }
        }
    }
}
static void SyncResource(Properties* p) {
    if (!p) return;
    SyncFieldResource(p->propRecName, false, gRecNameEd);
    SyncFieldResource(p->propRecFolder, true, gRecFolderEd);
}
