static int gRecDeleteView = -1;
static std::string gRecDeleteId;
static bool gRecDeleteForced = false;
static void RecDeleteConfirmed() {
    std::string reason;
    const bool ok = gRecDeleteForced ? W3dViewRecDeleteForced(gRecDeleteView, gRecDeleteId, &reason)
                                      : W3dViewRecDelete(gRecDeleteView, gRecDeleteId, &reason);
    if (ok) Notify(std::string(T("Deleted")) + ": " + gRecDeleteId, false);
    else Notify(std::string(T("Not deleted")) + ": " + T(reason.c_str()), true);
    gRecDeleteId.clear();
    gRecDeleteForced = false;
    PropertiesLayoutDirty = true;
    g_redraw = true;
}
// "Delete": un huerfano se confirma; uno EN USO avisa CUANTOS lo usan y ofrece borrarlo igual (sus usuarios
// quedan sin el, con Ctrl+Z) o cancelar
